  }
}

.collapse-tools-wrapper {
  padding: 0 0 0.5rem 0 !important;
  margin: 0 !important;
}

.final-answer-container {
  margin-top: 0.75rem !important;
  margin-bottom: 0.5rem;
}

.collapsing {
  transition: height 0.35s cubic-bezier(0.4, 0, 0.2, 1) !important;
  overflow: hidden !important;
}

import React, { useEffect, useMemo, useRef } from "react";
import "./Chat.css";
import ChatItem from "./ChatItem";
import { actionTypes } from "../../reducers/chatReducer";

const Chat = ({
  results,
  dispatch,
  setCurrentQuestion,
  setQuestionType,
  contextUsage,
}) => {
  const resultsEndRef = useRef(null);
  const resultsContainerRef = useRef(null);

  const receivedToolOutputs = useMemo(() => {
    const map = {};
    for (const item of contextUsage?.received_tool_outputs || []) {
      if (item?.tool_call_id) map[item.tool_call_id] = item.content;
    }
    return map;
  }, [contextUsage]);

  const scrollToBottom = () => {
    resultsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (results.length > 0) {
      scrollToBottom();
    }
  }, [results]);

  useEffect(() => {
    if (results.some(r => r.isExiting)) {
      const timer = setTimeout(() => {
        dispatch({ type: actionTypes.PURGE_EXITING_ITEMS });
      }, 400);
      return () => clearTimeout(timer);
    }
  }, [results, dispatch]);

  if (results.length === 0) {
    return null;
  }

  return (
    <div
      className="d-flex flex-column align-items-center w-100 text-light"
      ref={resultsContainerRef}
    >
      {results.map((result, index) => (
        <div
          key={result.id || result._key || `msg-${index}`}
          className={`w-100 ${result.isExiting ? 'chat-item-exit' : ''}`}
        >
          <ChatItem
            result={result}
            index={index}
            dispatch={dispatch}
            setCurrentQuestion={setCurrentQuestion}
            setQuestionType={setQuestionType}
            resultsContainerRef={resultsContainerRef}
            receivedToolOutputs={receivedToolOutputs}
            contextViews={contextUsage?.views || []}
          />
        </div>
      ))}
      <div ref={resultsEndRef} />
    </div>
  );
};

export default Chat;

import React, { useState, useEffect } from "react";
import PropTypes from "prop-types";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import Card from "react-bootstrap/Card";
import Collapse from "react-bootstrap/Collapse";
import Spinner from "react-bootstrap/Spinner";
import TableModal from "./Modals/TableModal";
import { useConfig } from "../../contexts/ConfigContext";
import AdditionalInformationModal from "./Modals/AdditionalInformationModal";
import GraphModal from "./Modals/GraphModal";
import FeedbackModal from "./Modals/FeedbackModal";
import RelatedQuestions from "./RelatedQuestions";
import ChatItemActions from "./ChatItemActions";
import ContextTablesAction from "./ContextTablesAction";
import ContextTablesModal from "./Modals/ContextTablesModal";
import ToolBlocks from "./ToolBlocks";
import NotificationToast from "../NotificationToast/NotificationToast";
import CopyButton from "../CopyButton/CopyButton";
import { markdownComponents } from "./markdownComponents";
import { InlineGraphsProvider, replaceGraphFences } from "./inlineGraphs";

// Tracks active streaming messages during this session so that,
// even if React unmounts the component upon receiving a UUID,
// it mounts expanded, displays the toggle, and smoothly auto-collapses once finished.
const activeStreamItems = new Set();

const ChatItem = ({
  result,
  index,
  dispatch,
  setCurrentQuestion,
  setQuestionType,
  resultsContainerRef,
  receivedToolOutputs,
  contextViews,
}) => {
  const { config } = useConfig();
  const [isExpanded, setIsExpanded] = useState(() => {
    if (result.isLoading) return true;
    if (activeStreamItems.has(index) || (result.uuid && activeStreamItems.has(result.uuid))) {
      return true;
    }
    return false;
  });
  const [showInfoModal, setShowInfoModal] = useState(false);
  const [showGraphModal, setShowGraphModal] = useState(false);
  const [graph, setGraph] = useState(null);
  const [graphVql, setGraphVql] = useState("");
  const [showTableModal, setShowTableModal] = useState(false);
  const [tableData, setTableData] = useState(null);
  const [showContextModal, setShowContextModal] = useState(false);
  const [contextTables, setContextTables] = useState({ tables: [], vql: "" });
  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [modalOverride, setModalOverride] = useState(null);
  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: "",
    variant: "info",
    title: "",
    showCopyButton: true,
  });

  useEffect(() => {
    const isStreaming =
      activeStreamItems.has(index) ||
      (result.uuid && activeStreamItems.has(result.uuid));

    if (result.isLoading) {
      activeStreamItems.add(index);
      if (result.uuid) activeStreamItems.add(result.uuid);
      setIsExpanded(true);
      return;
    }

    // Only auto-collapse the first time (when triggered by an active stream completion)
    if (!result.isLoading && isExpanded && isStreaming) {
      const timer = setTimeout(() => {
        setIsExpanded(false);
        activeStreamItems.delete(index);
        if (result.uuid) activeStreamItems.delete(result.uuid);
      }, 750);

      return () => clearTimeout(timer);
    }

    // If already collapsed or manually closed by the user, release the active flag
    if (!isExpanded) {
      activeStreamItems.delete(index);
      if (result.uuid) activeStreamItems.delete(result.uuid);
    }
  }, [result.isLoading, isExpanded, index, result.uuid]);

  const handleAskRelated = (question) => {
    setCurrentQuestion(question);
    setQuestionType(result?.toolName || 'auto');
  };

  const handleAskDeepQuery = (question) => {
    setCurrentQuestion(question);
    setQuestionType("deep_query");
  };

  const handleOpenInfo = () => {
    setModalOverride(null);
    setShowInfoModal(true);
  };

  const handleCloseInfo = () => {
    setShowInfoModal(false);
  };

  const handleResetInfo = () => {
    setModalOverride(null);
  };

  const handleToolIconClick = (toolResult) => {
    setModalOverride({
      ...result,
      ...toolResult,
      toolName: toolResult.modalTool || null
    });
    setShowInfoModal(true);
  };

  const handleOpenGraph = (graphData) => {
    const entry = graphData || result.graph;
    if (!entry) return;
    const src = typeof entry === "string" ? entry : entry.src || entry.graph;
    if (!src) return;
    setGraph(src);
    setGraphVql(typeof entry === "string" ? "" : entry.vql || "");
    setShowGraphModal(true);
  };

  const handleCloseGraph = () => {
    setShowGraphModal(false);
  };

  const handleResetGraph = () => {
    setGraph(null);
    setGraphVql("");
  };

  const handleOpenTable = (data) => {
    const d = data || result.execution_result?.full;
    if (!d) return;
    setTableData(d);
    setShowTableModal(true);
  };

  const handleCloseTable = () => {
    setShowTableModal(false);
  };

  const handleResetTableData = () => {
    setTableData(null);
  };

  const handleOpenContext = (tables, vql) => {
    if (!tables || tables.length === 0) return;
    setContextTables({ tables, vql });
    setShowContextModal(true);
  };

  const handleCloseContext = () => {
    setShowContextModal(false);
  };

  const handleResetContext = () => {
    setContextTables({ tables: [], vql: "" });
  };

  const handleOpenFeedback = () => {
    if (!config.chatbot_feedback || result.disableFeedback) return;
    setShowFeedbackModal(true);
  };

  const handleCloseFeedback = () => {
    setShowFeedbackModal(false);
  };

  const handleClipboardError = (errorMessage) => {
    setToastConfig({
      show: true,
      title: "Clipboard Error",
      message:
        errorMessage ||
        "Unable to copy to clipboard. Clipboard permissions may be blocked or the connection is not secure (HTTP/0.0.0.0).",
      variant: "warning",
      showCopyButton: false,
    });
  };

  const renderContent = () => {
    if (result.isLoading && (!result.blocks || result.blocks.length === 0)) {
      return (
        <Card.Text className="query-loading-text">
          <div className="d-flex align-items-start">
            <Spinner
              size="sm"
              animation="border"
              className="me-2 mt-1"
            />
            <span>Processing...</span>
          </div>
        </Card.Text>
      );
    }

    // Logic to separate technical process (tools + intermediate reasoning) from the final response.
    const blocks = result.blocks || [];

    let lastToolIndex = -1;
    for (let i = blocks.length - 1; i >= 0; i--) {
      if (blocks[i].type === "tool") {
        lastToolIndex = i;
        break;
      }
    }

    // We assume the last block is the final answer if it's a message,
    // AND either we are not loading OR there were tools executed before it.
    let processBlocks = [];
    let finalAnswerBlock = null;

    if (lastToolIndex === -1) {
      processBlocks = [];
      finalAnswerBlock = blocks[blocks.length - 1] || null;
    } else if (!result.isLoading) {
      processBlocks = blocks.slice(0, lastToolIndex + 1);
      if (lastToolIndex < blocks.length - 1) {
        finalAnswerBlock = blocks[blocks.length - 1];
      }
    } else {
      processBlocks = blocks;
      finalAnswerBlock = null;
    }

    const toolExecutionCount = processBlocks.filter((b) => b.type === "tool").length;
    const hasProcess = processBlocks.length > 0 && toolExecutionCount > 0;
    const emptyBlocksText = (!blocks || blocks.length === 0)
      ? (result.result || (result.isError ? result.errorMessage : null))
      : null;
    const responseCopyText =
      (finalAnswerBlock && finalAnswerBlock.content) ||
      emptyBlocksText ||
      "";

    return (
      <>
        {result.feedback && !result.isError && (
          <div className="mb-2">
            <span className={`badge bg-${result.feedback === "positive" ? "success" : "danger"} ms-2`}>
              {result.feedback === "positive" ? "Positive feedback" : "Negative feedback"}
            </span>
          </div>
        )}

        {!result.isLoading && hasProcess && (
          <div className="process-toggle-container mb-2 toggle-fade-in">
            <button
              className="btn btn-sm process-toggle-btn d-flex align-items-center"
              onClick={() => setIsExpanded(!isExpanded)}
              aria-expanded={isExpanded}
              type="button"
            >
              <i className={`bi bi-caret-${isExpanded ? "down" : "right"}-fill`}></i>
              <span className="ms-2">
                {`${toolExecutionCount} ${toolExecutionCount === 1 ? 'executed tool' : 'executed tools'}`}
              </span>
            </button>
          </div>
        )}

        {hasProcess && (
          <Collapse in={isExpanded}>
            <div id={`collapse-tools-${index}`} className="collapse-tools-wrapper">
              <ToolBlocks
                blocks={processBlocks}
                resultsContainerRef={resultsContainerRef}
                onOpenGraph={handleOpenGraph}
                onOpenTable={handleOpenTable}
                onToolIconClick={handleToolIconClick}
                receivedToolOutputs={receivedToolOutputs}
                onClipboardError={handleClipboardError}
              />
            </div>
          </Collapse>
        )}

        {finalAnswerBlock && finalAnswerBlock.content && (
          <Card.Text as="div" className="mt-0">
            <div className="markdown-container">
              <ReactMarkdown
                remarkPlugins={[remarkGfm]}
                components={markdownComponents}
              >
                {replaceGraphFences(finalAnswerBlock.content)}
              </ReactMarkdown>
            </div>
          </Card.Text>
        )}

        {emptyBlocksText && (
          <Card.Text as="div" className="mt-0">
            <div className="markdown-container">
              <ReactMarkdown
                remarkPlugins={[remarkGfm]}
                components={markdownComponents}
              >
                {replaceGraphFences(emptyBlocksText)}
              </ReactMarkdown>
            </div>
          </Card.Text>
        )}

        <RelatedQuestions
          relatedQuestions={result.relatedQuestions}
          relatedQuestionsDeepQuery={result.relatedQuestionsDeepQuery}
          onAskRelated={handleAskRelated}
          onAskDeepQuery={handleAskDeepQuery}
        />

        <ContextTablesAction
          tables={result.combinedTablesUsed}
          vql={result.combinedVqls}
          dataCatalogUrl={config.data_marketplace_url}
          contextViews={contextViews}
          icons={
            <ChatItemActions
              result={result}
              config={{ ...config, chatbot_feedback: config.chatbot_feedback && !result.disableFeedback }}
              onOpenInfo={handleOpenInfo}
              onFeedback={handleOpenFeedback}
              resultsContainerRef={resultsContainerRef}
              copyText={responseCopyText}
              onError={handleClipboardError}
            />
          }
          onOpenContext={handleOpenContext}
        />
      </>
    );
  };

  return (
    <>
      <div className="w-100 d-flex justify-content-center mb-3">
        <div className="w-70 d-flex justify-content-end">
          <div
            className="user-question-container d-flex align-items-center gap-2"
            style={{ maxWidth: "80%" }}
          >
            {result.question && (
              <CopyButton
                text={result.question}
                tooltipText="Copy question"
                placement="top"
                className="user-question-copy-btn flex-shrink-0"
                onError={handleClipboardError}
              />
            )}
            <Card
              style={{
                backgroundColor: "#ffffff",
                borderRadius: "1.25em",
                color: "#112533",
                boxShadow: "0 4px 12px rgba(0, 0, 0, 0.1)",
                width: "fit-content",
              }}
            >
              <Card.Body>
                <Card.Text className="mb-0">{result.question}</Card.Text>
              </Card.Body>
            </Card>
          </div>
        </div>
      </div>

      <div className="w-100 d-flex justify-content-center mb-3">
        <div className="w-60 d-flex justify-content-start">
          <Card
            className={`w-100 ${
              result.isLoading ? "card-loading-pulse" : ""
            }`}
            style={{
              backgroundColor: "#ffffff",
              color: "#112533",
              borderRadius: "1.25em",
              boxShadow: "0 4px 12px rgba(0, 0, 0, 0.1)",
              borderColor: result.isError ? "#dc3545" : undefined,
              borderWidth: result.isError ? "2px" : undefined
            }}
            data-result-index={index}
          >
            <Card.Body className="position-relative">
              <div className="card-content-area">
                <InlineGraphsProvider blocks={result.blocks} onOpenGraph={handleOpenGraph}>
                  {renderContent()}
                </InlineGraphsProvider>
              </div>
            </Card.Body>
          </Card>
        </div>
      </div>

      <AdditionalInformationModal
        show={showInfoModal}
        onClose={handleCloseInfo}
        onExited={handleResetInfo}
        result={modalOverride || result}
      />
      <GraphModal
        show={showGraphModal}
        graph={graph}
        vql={graphVql}
        onClose={handleCloseGraph}
        onExited={handleResetGraph}
      />
      <TableModal
        show={showTableModal}
        handleClose={handleCloseTable}
        handleResetData={handleResetTableData}
        executionResult={tableData}
      />
      <ContextTablesModal
        show={showContextModal}
        onClose={handleCloseContext}
        onExited={handleResetContext}
        tables={contextTables.tables}
        vql={contextTables.vql}
        dataCatalogUrl={config.data_marketplace_url}
        contextViews={contextViews}
      />
      <FeedbackModal
        show={showFeedbackModal}
        onClose={handleCloseFeedback}
        result={result}
        dispatch={dispatch}
        resultIndex={index}
        feedbackEnabled={config.chatbot_feedback}
        onShowToast={setToastConfig}
      />
      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        showCopyButton={toastConfig.showCopyButton !== false}
        onError={handleClipboardError}
        onClose={() => setToastConfig((prev) => ({ ...prev, show: false }))}
      />
    </>
  );
};

export default ChatItem;

ChatItem.propTypes = {
  result: PropTypes.shape({
    execution_result: PropTypes.shape({
      full: PropTypes.object,
    }),
    isError: PropTypes.bool,
    errorMessage: PropTypes.string,
    blocks: PropTypes.array,
    result: PropTypes.string,
    question: PropTypes.string,
    isLoading: PropTypes.bool,
    uuid: PropTypes.string,
    feedback: PropTypes.string,
    combinedTablesUsed: PropTypes.array,
    combinedVqls: PropTypes.string,
    relatedQuestions: PropTypes.array,
    relatedQuestionsDeepQuery: PropTypes.array,
    toolName: PropTypes.string,
    graph: PropTypes.any,
    disableFeedback: PropTypes.bool,
  }).isRequired,
  index: PropTypes.number,
  dispatch: PropTypes.func,
  setCurrentQuestion: PropTypes.func,
  setQuestionType: PropTypes.func,
  resultsContainerRef: PropTypes.object,
  receivedToolOutputs: PropTypes.object,
  contextViews: PropTypes.array,
};

import React from "react";
import PropTypes from "prop-types";
import OverlayTrigger from "react-bootstrap/OverlayTrigger";
import Tooltip from "react-bootstrap/Tooltip";
import CopyButton from "../CopyButton/CopyButton";

const assetBaseUrl = import.meta.env.BASE_URL;

const renderTooltip = (content) => (
  <Tooltip id="chat-item-action-tooltip">{content}</Tooltip>
);

const ChatItemActions = ({
  result,
  config,
  onOpenInfo,
  onFeedback,
  resultsContainerRef,
  copyText,
  onError,
}) => {
  const isError = Boolean(result && result.isError);

  const feedbackIcon = !isError && config.chatbot_feedback ? (
    <OverlayTrigger
      placement="left"
      delay={{ show: 250, hide: 400 }}
      overlay={renderTooltip("Provide feedback")}
      container={resultsContainerRef && resultsContainerRef.current}
    >
      <img
        src={`${assetBaseUrl}feedback.svg`}
        alt="Feedback"
        width="20"
        height="20"
        className="ms-2 cursor-pointer"
        onClick={onFeedback}
      />
    </OverlayTrigger>
  ) : null;

  const copyIcon = copyText ? (
    <CopyButton
      text={copyText}
      tooltipText={isError ? "Copy error" : "Copy response"}
      placement="left"
      container={resultsContainerRef && resultsContainerRef.current}
      className={isError ? "" : "ms-2"}
      onError={onError}
    />
  ) : null;

  const renderBaseIcon = () => {
    if (isError) return null;

    return (
      <OverlayTrigger
        placement="left"
        delay={{ show: 250, hide: 400 }}
        overlay={renderTooltip("AI")}
        container={resultsContainerRef && resultsContainerRef.current}
      >
        <img
          src={`${assetBaseUrl}ai.png`}
          alt="AI Icon"
          width="20"
          height="20"
          className="cursor-pointer"
          onClick={onOpenInfo}
        />
      </OverlayTrigger>
    );
  };

  return (
    <div className="d-flex flex-row align-items-center position-relative">
      {renderBaseIcon()}
      {copyIcon}
      {feedbackIcon}
    </div>
  );
};

ChatItemActions.propTypes = {
  result: PropTypes.shape({
    isError: PropTypes.bool,
  }),
  config: PropTypes.shape({
    chatbot_feedback: PropTypes.bool,
  }),
  onOpenInfo: PropTypes.func,
  onFeedback: PropTypes.func,
  resultsContainerRef: PropTypes.object,
  copyText: PropTypes.string,
  onError: PropTypes.func,
};

export default ChatItemActions;

import React, { useId, useMemo } from "react";
import OverlayTrigger from "react-bootstrap/OverlayTrigger";
import Tooltip from "react-bootstrap/Tooltip";
import { ViewChip } from "../QuestionForm/ContextViewsRow";
import {
  splitUsedTables,
  buildViewTokenLookup,
  viewTokens,
  cleanViewName,
} from "../../utils/viewUsage";

const renderTooltip = (id, content) => (
  <Tooltip id={id}>{content}</Tooltip>
);

// Views searched for an answer, shown at the bottom of the answer card.
// Views actually referenced by the generated VQL appear as green chips in
// the current context-view chip format; the rest sit behind a "+N more"
// chip that opens the Context Tables modal. If no view was used, no chips
// are shown at all.
const ContextTablesAction = ({ tables, vql, dataCatalogUrl, icons, onOpenContext, contextViews }) => {
  const tooltipId = `context-tooltip-${useId().replace(/[^A-Za-z0-9_-]/g, "")}`;
  const { usedTables, unusedTables } = useMemo(
    () => splitUsedTables(tables, vql, contextViews),
    [tables, vql, contextViews],
  );
  const tokenLookup = useMemo(
    () => buildViewTokenLookup(contextViews),
    [contextViews],
  );

  if (usedTables.length === 0) {
    if (!icons) return null;
    return (
      <div
        style={{
          backgroundColor: "transparent",
          padding: "1rem 0",
          marginBottom: "0",
        }}
      >
        <div className="mb-2 d-flex justify-content-end align-items-center">
          <div
            className="d-flex flex-row align-items-center"
            style={{ gap: "8px" }}
          >
            {icons}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div
      style={{
        backgroundColor: "transparent",
        padding: "1rem 0",
        marginBottom: "0",
      }}
    >
      <div className="mb-2 d-flex justify-content-between align-items-center">
        <div className="context-badges-container d-flex flex-wrap align-items-center" style={{ gap: "8px", flex: 1, minWidth: 0 }}>
          {usedTables.map((table) => (
            <ViewChip
              key={table}
              view={{ name: cleanViewName(table), tokens: viewTokens(table, tokenLookup) }}
              dataCatalogUrl={dataCatalogUrl}
              showHint={false}
              used
            />
          ))}
          {unusedTables.length > 0 && (
            <OverlayTrigger
              placement="top"
              delay={{ show: 250, hide: 400 }}
              overlay={renderTooltip(tooltipId, "View all searched tables")}
            >
              <button
                type="button"
                className="context-view-more-chip"
                onClick={() => onOpenContext(tables, vql)}
              >
                +{unusedTables.length} more
              </button>
            </OverlayTrigger>
          )}
        </div>
        {icons && (
          <div
            className="d-flex flex-row align-items-center"
            style={{ gap: "8px", flexShrink: 0 }}
          >
            {icons}
          </div>
        )}
      </div>
    </div>
  );
};

export default ContextTablesAction;

import React from "react";
import { BaseModal } from "../../Common/Modal";
import { format } from "sql-formatter";
import hljs from "highlight.js/lib/core";
import sqlLanguage from "highlight.js/lib/languages/sql";
import "highlight.js/styles/github.css";
import { useNumberFormat } from "../../../contexts/ConfigContext";

hljs.registerLanguage("sql", sqlLanguage);

const formatSql = (sql) => {
  if (!sql || sql === "N/A") return sql;
  try {
    return format(sql, {
      language: "postgresql",
      keywordCase: "upper",
      tabWidth: 2,
    }).replace(/\b([A-Z][A-Z0-9_]*)\s+\(/g, "$1(");
  } catch {
    return sql;
  }
};

const sqlBlockStyle = {
  marginTop: "0.5rem",
  marginBottom: "1rem",
  padding: "0.75rem",
  backgroundColor: "#f6f8fa",
  border: "1px solid #dee2e6",
  borderRadius: "0.25rem",
  maxHeight: "320px",
  overflow: "auto",
  whiteSpace: "pre-wrap",
  fontSize: "0.8rem",
};

export const SqlBlock = ({ sql }) => (
  <pre
    className="hljs"
    style={sqlBlockStyle}
    dangerouslySetInnerHTML={{
      __html: hljs.highlight(formatSql(sql || "N/A"), { language: "sql" }).value,
    }}
  />
);

const AdditionalInformationModal = ({ show, onClose, onExited, result }) => {
  const formatNumber = useNumberFormat();

  if (!result) return null;

  const renderContent = () => {
    const modalTool = (result.modalTool || result.toolName || "").toLowerCase();

    const clickedBlock = result.modalToolCallId
      ? result.blocks?.find((b) => b.toolCallId === result.modalToolCallId) ||
        result.toolCalls?.find((t) => t.toolCallId === result.modalToolCallId)
      : null;

    const targetBlock =
      clickedBlock ||
      result.blocks?.find(b => (b.toolName || b.modalTool || "").toLowerCase() === modalTool) ||
      result.toolCalls?.find(t => (t.toolName || "").toLowerCase() === modalTool);

    const activeArtifact = targetBlock?.artifact || result.modalArtifact || {};
    // ------------------------------------

    const errorMessage =
      result.error_message ||
      activeArtifact.error_message ||
      (typeof activeArtifact.error === "string" ? activeArtifact.error : null) ||
      (result.isError ? result.errorMessage || result.result : null);
    const traceback = result.traceback || activeArtifact.traceback || result.errorDetails;
    const hasError = !!(errorMessage || traceback);

    const renderErrorSection = () => {
      if (!errorMessage && !traceback) return null;
      return (
        <div
          style={{
            marginBottom: "1rem",
            borderRadius: "0.25rem",
            padding: "0.5rem 0.75rem",
            backgroundColor: "rgba(220,53,69,0.08)",
            color: "#842029",
            fontSize: "0.9rem",
          }}
        >
          {errorMessage && (
            <p style={{ marginBottom: traceback ? "0.25rem" : 0 }}>
              <strong>Error:</strong> {errorMessage}
            </p>
          )}
          {traceback && (
            <div>
              <strong>Traceback:</strong>
              <pre
                style={{
                  marginTop: "0.25rem",
                  maxHeight: "250px",
                  overflow: "auto",
                  whiteSpace: "pre-wrap",
                  fontSize: "0.8rem",
                }}
              >
                {traceback}
              </pre>
            </div>
          )}
        </div>
      );
    };

    if (!result.modalTool && !result.toolName) {
      return (
        <div>
          {renderErrorSection()}
          {!hasError && (
            <p>
              <strong>Chatbot LLM:</strong> {result.chatbot_llm || "N/A"}
            </p>
          )}
        </div>
      );
    }

    switch (modalTool) {
      case "generate_vql":
      case "data_agent": // backwards compatibility for chats saved before data_agent was split
        if (errorMessage || traceback) {
          return <div>{renderErrorSection()}</div>;
        }

        const totalTime = activeArtifact.total_execution_time ?? activeArtifact.ai_sdk_time ?? result.ai_sdk_time;
        const vectorTime = activeArtifact.vector_store_search_time;
        const llmTime = activeArtifact.llm_time;
        const sqlTime = activeArtifact.sql_execution_time;
        const hasBreakdown = vectorTime != null || llmTime != null || sqlTime != null;

        const totalTokens = activeArtifact.total_tokens ?? activeArtifact.tokens ?? result.tokens;
        const inputTokens = activeArtifact.input_tokens ?? result.input_tokens;
        const outputTokens = activeArtifact.output_tokens ?? result.output_tokens;
        const hasTokenBreakdown = inputTokens != null || outputTokens != null;

        return (
          <div>
            <p>
              <strong>Source:</strong> Denodo
            </p>
            <p>
              <strong>AI SDK LLM:</strong>{" "}
              {activeArtifact.llm_provider && activeArtifact.llm_model
                ? `${activeArtifact.llm_provider}/${activeArtifact.llm_model}`
                : (result.llm_provider && result.llm_model ? `${result.llm_provider}/${result.llm_model}` : "N/A")}
            </p>
            <div>
              <strong>AI-Generated VQL:</strong>
              <SqlBlock sql={activeArtifact.vql || result.vql || "N/A"} />
            </div>
            <p>
              <strong>Query explanation:</strong> {activeArtifact.query_explanation || result.query_explanation || "N/A"}
            </p>
            {/* --- TOKEN BREAKDOWN RENDER --- */}
            <p style={{ marginBottom: hasTokenBreakdown ? "0.25rem" : "1rem" }}>
              <strong>AI SDK Tokens (Total):</strong>{" "}
              {totalTokens != null ? formatNumber(totalTokens) : "N/A"}
            </p>

            {hasTokenBreakdown && (
              <div style={{ paddingLeft: "1.25rem", marginBottom: "1rem", fontSize: "0.95rem", color: "#555" }}>
                <div style={{ marginBottom: "0.25rem" }}>
                  <span style={{ color: "#adb5bd", marginRight: "6px" }}>↳</span>
                  <strong>Input Tokens:</strong> {inputTokens != null ? formatNumber(inputTokens) : 0}
                </div>
                <div>
                  <span style={{ color: "#adb5bd", marginRight: "6px" }}>↳</span>
                  <strong>Output Tokens:</strong> {outputTokens != null ? formatNumber(outputTokens) : 0}
                </div>
              </div>
            )}
            {/* ------------------------------- */}

            {/* --- TIMING BREAKDOWN RENDER --- */}
            <p style={{ marginBottom: hasBreakdown ? "0.25rem" : "1rem" }}>
              <strong>AI SDK Time (Total):</strong>{" "}
              {totalTime != null ? `${formatNumber(totalTime, 2)}s` : "N/A"}
            </p>

            {hasBreakdown && (
              <div style={{ paddingLeft: "1.25rem", marginBottom: "1rem", fontSize: "0.95rem", color: "#555" }}>
                <div style={{ marginBottom: "0.25rem" }}>
                  <span style={{ color: "#adb5bd", marginRight: "6px" }}>↳</span>
                  <strong>Vector Search:</strong> {`${formatNumber(vectorTime ?? 0, 2)}s`}
                </div>
                <div style={{ marginBottom: "0.25rem" }}>
                  <span style={{ color: "#adb5bd", marginRight: "6px" }}>↳</span>
                  <strong>LLM Processing:</strong> {`${formatNumber(llmTime ?? 0, 2)}s`}
                </div>
                <div>
                  <span style={{ color: "#adb5bd", marginRight: "6px" }}>↳</span>
                  <strong>VQL Execution:</strong> {`${formatNumber(sqlTime ?? 0, 2)}s`}
                </div>
              </div>
            )}
            {/* --------------------------------- */}
          </div>
        );
      case "execute_vql":
      case "generate_graph":
        if (errorMessage || traceback) {
          return <div>{renderErrorSection()}</div>;
        }
        return (
          <div>
            <p>
              <strong>Source:</strong> Denodo
            </p>
            <div>
              <strong>Executed VQL:</strong>
              <SqlBlock sql={activeArtifact.vql || result.vql || "N/A"} />
            </div>
          </div>
        );
      case "deep_query":
        if (errorMessage || traceback) {
          return <div>{renderErrorSection()}</div>;
        }
        return (
          <div>
            <p>
              <strong>Source:</strong> Denodo DeepQuery
            </p>
            {activeArtifact.analysis_id && (
              <>
                <p>
                  <strong>Analysis ID:</strong> <code>{activeArtifact.analysis_id}</code>
                </p>
                <p>
                  <strong>Execution:</strong> Background job (follow it in the DeepQuery Reports Manager)
                </p>
                {Array.isArray(activeArtifact.languages) && activeArtifact.languages.length > 0 && (
                  <p>
                    <strong>Languages:</strong> {activeArtifact.languages.join(", ")}
                  </p>
                )}
                {Array.isArray(activeArtifact.report_ids) && activeArtifact.report_ids.length > 0 && (
                  <div>
                    <strong>Report IDs:</strong>
                    <ul className="mb-2">
                      {activeArtifact.report_ids.map((reportId, index) => (
                        <li key={reportId}>
                          <code>{reportId}</code>
                          {activeArtifact.languages?.[index] ? ` (${activeArtifact.languages[index]})` : ""}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </>
            )}
            {!activeArtifact.analysis_id && !activeArtifact.report_ids && (
              <p>
                <strong>Execution:</strong> Legacy analysis (run synchronously before background reports existed).
                {activeArtifact.deepquery_metadata
                  ? " Use \"Generate report\" in the chat block to create a report from its stored data."
                  : " Its data is no longer available."}
              </p>
            )}
            {/* Chats saved before DeepQuery became asynchronous stored the metadata in the artifact */}
            {activeArtifact.deepquery_metadata && (
              <>
                <p>
                  <strong>Planning LLM:</strong>{" "}
                  {activeArtifact.deepquery_metadata.planning_provider &&
                  activeArtifact.deepquery_metadata.planning_model
                    ? `${activeArtifact.deepquery_metadata.planning_provider}/${activeArtifact.deepquery_metadata.planning_model}`
                    : "N/A"}
                </p>
                <p>
                  <strong>Execution LLM:</strong>{" "}
                  {activeArtifact.deepquery_metadata.executing_provider &&
                  activeArtifact.deepquery_metadata.executing_model
                    ? `${activeArtifact.deepquery_metadata.executing_provider}/${activeArtifact.deepquery_metadata.executing_model}`
                    : "N/A"}
                </p>
                <p>
                  <strong>Number of tool calls:</strong>{" "}
                  {activeArtifact.deepquery_metadata.tool_calls
                    ? activeArtifact.deepquery_metadata.tool_calls.length
                    : "N/A"}
                </p>
              </>
            )}
            {(activeArtifact.total_execution_time ?? result.total_execution_time) != null && (
              <p>
                <strong>Execution time:</strong>{" "}
                {formatNumber(activeArtifact.total_execution_time ?? result.total_execution_time, 2)}s
              </p>
            )}
          </div>
        );
      case "metadata_search":
        if (errorMessage || traceback) {
          return <div>{renderErrorSection()}</div>;
        }

        // Only rely on the total time, as the LLM is bypassed for this tool.
        const mdTotalTime = activeArtifact.total_execution_time ?? activeArtifact.ai_sdk_time ?? result.total_execution_time ?? result.ai_sdk_time;

        return (
          <div>
            <p>
              <strong>Source:</strong> Denodo Metadata
            </p>

            <p style={{ marginBottom: mdTotalTime != null ? "0.25rem" : "1rem" }}>
              <strong>AI SDK Time (Total):</strong>{" "}
              {mdTotalTime != null ? `${formatNumber(mdTotalTime, 2)}s` : "N/A"}
            </p>

            {mdTotalTime != null && (
              <div style={{ paddingLeft: "1.25rem", marginBottom: "1rem", fontSize: "0.95rem", color: "#555" }}>
                <div>
                  <span style={{ color: "#adb5bd", marginRight: "6px" }}>↳</span>
                  <strong>Vector Search:</strong> {formatNumber(mdTotalTime, 2)}s
                </div>
              </div>
            )}
          </div>
        );
      case "knowledge_query": {
        if (errorMessage || traceback) {
          return <div>{renderErrorSection()}</div>;
        }
        const collectionName = result.collection_name || activeArtifact.collection_name || "N/A";
        const collectionDescription =
          result.collection_description || activeArtifact.collection_description || "";
        return (
          <div>
            <p>
              <strong>Source:</strong> Knowledge Base
            </p>
            <p>
              <strong>Collection:</strong> {collectionName}
            </p>
            <p>
              <strong>Collection description:</strong> {collectionDescription || "N/A"}
            </p>
          </div>
        );
      }
      default:
        return (
          <div>
            <p>
              <strong>Source:</strong> AI
            </p>
            <p>
              <strong>Chatbot LLM:</strong> {result.chatbot_llm || "N/A"}
            </p>
          </div>
        );
    }
  };

  return (
    <BaseModal
      show={show}
      onHide={onClose}
      onExited={onExited}
      title="Additional Information"
      size="lg"
      scrollableBody
      footer={null}
    >
      {renderContent()}
    </BaseModal>
  );
};

export default AdditionalInformationModal;

import React, { useMemo } from "react";
import { BaseModal } from "../../Common/Modal";
import { ViewChip } from "../../QuestionForm/ContextViewsRow";
import {
  splitUsedTables,
  buildViewTokenLookup,
  viewTokens,
  cleanViewName,
} from "../../../utils/viewUsage";

const ContextTablesModal = ({ show, onClose, onExited, tables, vql, dataCatalogUrl, contextViews }) => {
  const { usedTables, unusedTables } = useMemo(
    () => splitUsedTables(tables, vql, contextViews),
    [tables, vql, contextViews],
  );
  const tokenLookup = useMemo(
    () => buildViewTokenLookup(contextViews),
    [contextViews],
  );

  const renderChips = (list, used) => (
    <div className="d-flex flex-wrap" style={{ gap: "8px" }}>
      {list.map((table) => (
        <ViewChip
          key={table}
          view={{ name: cleanViewName(table), tokens: viewTokens(table, tokenLookup) }}
          dataCatalogUrl={dataCatalogUrl}
          showHint={false}
          used={used}
        />
      ))}
    </div>
  );

  return (
    <BaseModal
      show={show}
      onHide={onClose}
      onExited={onExited}
      title="Context Tables"
      size="lg"
      scrollableBody
      footer={null}
    >
      <>
        {usedTables.length > 0 && (
          <div className="mb-4">
            <h6 className="mb-3">
              <strong>Used in Query ({usedTables.length})</strong>
            </h6>
            {renderChips(usedTables, true)}
          </div>
        )}

        {unusedTables.length > 0 && (
          <div className="mb-3">
            <h6 className="mb-3">
              <strong>
                Searched but Not Used ({unusedTables.length})
              </strong>
            </h6>
            {renderChips(unusedTables, false)}
          </div>
        )}

        <div className="mt-4 pt-3 border-top border-secondary">
          <small>
            <strong>Note:</strong> Views in green were used to find the answer,
            while grey tables were found in the database but found not relevant
            to the question.
          </small>
        </div>
      </>
    </BaseModal>
  );
};

export default ContextTablesModal;

import React, { useState } from "react";
import Form from "react-bootstrap/Form";
import { BaseModal } from "../../Common/Modal";
import { actionTypes } from "../../../reducers/chatReducer";
import { buildApiUrl } from "../../../api/client";
import CustomTooltip from "../../CustomTooltip/CustomTooltip";

const FeedbackModal = ({ 
  show, 
  onClose, 
  result, 
  dispatch, 
  resultIndex, 
  feedbackEnabled,
  onShowToast
}) => {
  const [feedbackValue, setFeedbackValue] = useState("");
  const [feedbackDetails, setFeedbackDetails] = useState("");
  const [submitting, setSubmitting] = useState(false);

  if (!feedbackEnabled || !result) return null;

  const handleSubmit = async () => {
    if (!result.uuid) return;

    setSubmitting(true);

    try {
      const response = await fetch(buildApiUrl("submit_feedback"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          uuid: result.uuid,
          feedback_value: feedbackValue,
          feedback_details: feedbackDetails,
        }),
      });

      let data = {};
      try {
        data = await response.json();
      } catch {
        data = {
          message: `The server returned an invalid response (HTTP ${response.status}).`,
        };
      }

      if (response.ok) {
        dispatch({
            type: actionTypes.SET_CHAT_ITEM_FEEDBACK,
            payload: { resultIndex, feedback: feedbackValue, feedbackDetails }
        });

        if (onShowToast) {
          onShowToast({
            show: true,
            title: "Feedback Submitted",
            message: "Thank you for your feedback.",
            variant: "success"
          });
        }

        onClose();
      } else {
        if (data.error === "uuid_not_found") {
          if (onShowToast) {
            onShowToast({
              show: true,
              title: "Feedback Not Saved",
              message: "This conversation is too old and its original record has been deleted to save space. Your feedback could not be saved.",
              variant: "warning"
            });
          }
          onClose();
        } else {
          const detail = data.message || `Feedback could not be saved (HTTP ${response.status}).`;
          if (onShowToast) {
            onShowToast({
              show: true,
              title: "Error",
              message: detail,
              variant: "danger"
            });
          } else {
            alert(detail);
          }
        }
      }
    } catch (error) {
      console.error("Error submitting feedback:", error);
      const detail =
        error?.message ||
        "Unable to reach the server. Check your connection and try again.";

      if (onShowToast) {
        onShowToast({
          show: true,
          title: "Connection Error",
          message: `Error submitting feedback: ${detail}`,
          variant: "danger"
        });
      } else {
        alert(`Error submitting feedback: ${detail}`);
      }
    } finally {
      setSubmitting(false);
    }
  };

  const handleHide = () => {
    if (submitting) return;
    onClose();
  };

  const handleExited = () => {
    setFeedbackValue("");
    setFeedbackDetails("");
  };

  return (
    <BaseModal
      show={show}
      onHide={handleHide}
      onExited={handleExited}
      title="Provide Feedback"
      size="md"
      scrollableBody
      footer={
        <>
          <button type="button" className="rcc-ghost-btn" onClick={handleHide} disabled={submitting}>
            Cancel
          </button>
          <button
            type="button"
            className="rcc-primary-btn"
            onClick={handleSubmit}
            disabled={!feedbackValue || submitting}
          >
            {submitting ? "Submitting..." : "Submit Feedback"}
          </button>
        </>
      }
    >
      <>
        <div className="mb-3">
          <p className="mb-1">
            <strong>Question:</strong>
          </p>
          <p>{result.question}</p>
        </div>
        <Form>
          <Form.Group className="mb-3">
            <Form.Label className="small fw-semibold d-flex align-items-center">
              Was this answer helpful?
              <CustomTooltip 
                id="tooltip-feedback-info" 
                content="The feedback submitted in this form is saved in the reports/ folder at the root level of the AI SDK."
              >
                <i className="bi bi-info-circle info-icon ms-2"></i>
              </CustomTooltip>
            </Form.Label>
            <div>
              <Form.Check
                inline
                type="radio"
                id="positive-feedback"
                label="Yes"
                name="feedback"
                value="positive"
                checked={feedbackValue === "positive"}
                onChange={() => setFeedbackValue("positive")}
              />
              <Form.Check
                inline
                type="radio"
                id="negative-feedback"
                label="No"
                name="feedback"
                value="negative"
                checked={feedbackValue === "negative"}
                onChange={() => setFeedbackValue("negative")}
              />
            </div>
          </Form.Group>
          <Form.Group className="mb-3">
            <Form.Label className="small fw-semibold">Additional details (optional)</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              value={feedbackDetails}
              onChange={(e) => setFeedbackDetails(e.target.value)}
              placeholder="Please provide any additional comments..."
            />
          </Form.Group>
        </Form>
      </>
    </BaseModal>
  );
};

export default FeedbackModal;

import React, { useEffect, useState } from "react";
import Tab from "react-bootstrap/Tab";
import Tabs from "react-bootstrap/Tabs";
import { BaseModal } from "../../Common/Modal";
import CopyButton from "../../CopyButton/CopyButton";
import { SqlBlock } from "./AdditionalInformationModal";

// Graph image without any modal wrapper, so it can also be shown inline
export const GraphView = ({ graph }) => (
  <div className="text-center">
    {graph && <img src={graph} alt="Graph" className="img-fluid" />}
  </div>
);

const VqlPanel = ({ vql }) => (
  <div>
    <div className="d-flex align-items-center justify-content-between mb-2">
      <span className="text-muted" style={{ fontSize: "0.85rem" }}>
        VQL query used to generate this graph
      </span>
      <span className="d-inline-flex align-items-center gap-1">
        <CopyButton text={String(vql)} tooltipText="Copy VQL" />
        <span style={{ fontSize: "0.85rem" }}>Copy VQL</span>
      </span>
    </div>
    <SqlBlock sql={String(vql)} />
  </div>
);

const GraphModal = ({ show, graph, vql, onClose, onExited }) => {
  const [segment, setSegment] = useState("graph");

  useEffect(() => {
    if (show) setSegment("graph");
  }, [show]);

  const hasVql = Boolean(vql && String(vql).trim());

  return (
    <BaseModal
      show={show}
      onHide={onClose}
      onExited={onExited}
      title="Graph View"
      size="lg"
      footer={null}
    >
      <Tabs activeKey={segment} onSelect={(key) => key && setSegment(key)}>
        <Tab eventKey="graph" title="Graph">
          <div className="modal-scroll-container">
            <GraphView graph={graph} />
          </div>
        </Tab>
        <Tab eventKey="vql" title="VQL">
          <div className="modal-scroll-container">
            {hasVql ? (
              <VqlPanel vql={vql} />
            ) : (
              <p className="text-muted mb-0">
                VQL not available for this graph. It may have been saved before the VQL was stored with the graph.
              </p>
            )}
          </div>
        </Tab>
      </Tabs>
    </BaseModal>
  );
};

export default GraphModal;

import React from "react";
import { ConfirmationModal } from "../../Common/Modal";

const LimitReachedModal = ({ modalState, onClose, onAccept }) => {
  const isMessages = modalState.type === "messages";
  const targets = modalState.targetsToDelete || [];
  const targetCount = targets.length;

  const itemText = isMessages
    ? targetCount === 1
      ? "message"
      : "messages"
    : targetCount === 1
      ? "conversation"
      : "conversations";

  const deletionTargetText =
    targetCount === 1
      ? `the oldest ${itemText}`
      : `the oldest ${targetCount} ${itemText}`;

  const message = isMessages ? (
    <>
      Cannot save the new message because the storage limit (
      <strong>{modalState.limit}</strong>) has been reached. If you accept,{" "}
      <strong>{deletionTargetText}</strong> will be permanently deleted from
      the database:
    </>
  ) : (
    <>
      Cannot create a new conversation because the limit of{" "}
      <strong>{modalState.limit}</strong> has been reached. If you accept,{" "}
      <strong>{deletionTargetText}</strong> will be permanently deleted:
    </>
  );

  return (
    <ConfirmationModal
      show={modalState.show}
      onHide={onClose}
      onConfirm={onAccept}
      title={isMessages ? "Message Limit Reached" : "Conversation Limit Reached"}
      message={message}
      iconClass="bi-exclamation-triangle-fill text-warning"
      confirmLabel="Accept"
      confirmVariant="primary"
      size="md"
    >
      <div className="limit-list-container mb-3">
        <ul className="list-group list-group-flush text-start mb-0">
          {targets.map((target, idx) => (
            <li
              key={idx}
              className="list-group-item list-group-item-danger text-truncate"
            >
              {isMessages ? `"${target}"` : target}
            </li>
          ))}
        </ul>
      </div>
      <p className="mb-0 small text-muted">
        {isMessages
          ? "Note: If you accept, from this point forward, the oldest messages will be automatically deleted in the background as you continue chatting in this conversation."
          : "You can also cancel and manually delete previous conversations from the sidebar."}
      </p>
    </ConfirmationModal>
  );
};

export default LimitReachedModal;

import React, { useState, useMemo, useRef } from "react";
import PropTypes from "prop-types";
import { BaseModal } from "../../Common/Modal";
import Table from "react-bootstrap/Table";
import Pagination from "react-bootstrap/Pagination";

// Table content (pagination included) without any modal wrapper, so it can also be shown inline
export const TableView = ({ executionResult }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const rowsPerPage = 10;
  const tableScrollRef = useRef(null);


  const tableData = useMemo(() => {
    if (
      !executionResult ||
      typeof executionResult === "string" ||
      Object.keys(executionResult).length === 0
    ) {
      return { headers: [], rows: [] };
    }

    const rows = Object.values(executionResult);
    if (rows.length === 0 || !Array.isArray(rows[0])) {
      return { headers: [], rows: [] };
    }

    const headers = rows[0].map((item) => item.columnName);
    const dataRows = rows.map((row) => row.map((item) => item.value));

    return { headers, rows: dataRows };
  }, [executionResult]);

  const totalRows = tableData.rows.length;
  const totalPages = Math.ceil(totalRows / rowsPerPage);

  const paginatedRows = useMemo(() => {
    const startIndex = (currentPage - 1) * rowsPerPage;
    const endIndex = Math.min(startIndex + rowsPerPage, totalRows);
    return tableData.rows.slice(startIndex, endIndex);
  }, [tableData.rows, currentPage, rowsPerPage, totalRows]);

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
    if (tableScrollRef.current) {
      tableScrollRef.current.scrollLeft = 0;
    }
  };

  const renderPagination = () => {
    if (totalPages <= 1) return null;

    const items = [];
    const maxPageItems = 5;
    let startPage = Math.max(1, currentPage - Math.floor(maxPageItems / 2));
    let endPage = Math.min(totalPages, startPage + maxPageItems - 1);

    if (endPage - startPage + 1 < maxPageItems) {
      startPage = Math.max(1, endPage - maxPageItems + 1);
    }

    items.push(
      <Pagination.Prev
        key="prev"
        onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
        disabled={currentPage === 1}
      />
    );

    if (startPage > 1) {
      items.push(
        <Pagination.Item key={1} onClick={() => handlePageChange(1)}>
          1
        </Pagination.Item>
      );
      if (startPage > 2) {
        items.push(<Pagination.Ellipsis key="ellipsis-1" disabled />);
      }
    }

    for (let page = startPage; page <= endPage; page++) {
      items.push(
        <Pagination.Item
          key={page}
          active={page === currentPage}
          onClick={() => handlePageChange(page)}
        >
          {page}
        </Pagination.Item>
      );
    }

    if (endPage < totalPages) {
      if (endPage < totalPages - 1) {
        items.push(<Pagination.Ellipsis key="ellipsis-2" disabled />);
      }
      items.push(
        <Pagination.Item key={totalPages} onClick={() => handlePageChange(totalPages)}>
          {totalPages}
        </Pagination.Item>
      );
    }

    items.push(
      <Pagination.Next
        key="next"
        onClick={() => handlePageChange(Math.min(totalPages, currentPage + 1))}
        disabled={currentPage === totalPages}
      />
    );

    return (
      <div className="d-flex justify-content-center mt-3" data-bs-theme="light">
        <Pagination>{items}</Pagination>
      </div>
    );
  };

  return (
    <>
        {totalRows > 0 ? (
          <>
            <div
              className="table-responsive"
              ref={tableScrollRef}
              tabIndex={0}
              role="region"
              aria-label="Scrollable execution result"
            >
              <Table className="custom-table" striped bordered hover variant="light">
                <thead>
                  <tr>
                    {tableData.headers.map((header, index) => (
                      <th key={index} title={header}>{header}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {paginatedRows.map((row, rowIndex) => (
                    <tr key={rowIndex}>
                      {row.map((cell, cellIndex) => (
                        <td key={cellIndex} title={String(cell)}>{String(cell)}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </Table>
            </div>
            {renderPagination()}
            <div className="mt-3 text-center">
              Showing rows {(currentPage - 1) * rowsPerPage + 1}-
              {Math.min(currentPage * rowsPerPage, totalRows)} of {totalRows}
            </div>
          </>
        ) : (
          <div className="text-center py-4">No data available</div>
        )}
    </>
  );
};

TableView.propTypes = {
  executionResult: PropTypes.oneOfType([PropTypes.object, PropTypes.string]),
};

const TableModal = ({ show, handleClose, handleResetData, executionResult }) => (
  <BaseModal
    show={show}
    onHide={handleClose}
    onExited={() => handleResetData && handleResetData()}
    title="Execution Result"
    size="xl"
    scrollableBody
    footer={null}
  >
    <TableView executionResult={executionResult} />
  </BaseModal>
);

export default TableModal;

TableModal.propTypes = {
  show: PropTypes.bool,
  handleClose: PropTypes.func,
  handleResetData: PropTypes.func,
  executionResult: PropTypes.oneOfType([PropTypes.object, PropTypes.string]),
};

import React, { useState } from "react";
import Button from "react-bootstrap/Button";
import Badge from "react-bootstrap/Badge";

const RelatedQuestions = ({
  relatedQuestions,
  relatedQuestionsDeepQuery,
  onAskRelated,
  onAskDeepQuery,
}) => {
  const hasRegularQuestions =
    relatedQuestions && relatedQuestions.length > 0;
  const hasDeepQueryQuestions =
    relatedQuestionsDeepQuery && relatedQuestionsDeepQuery.length > 0;

  const [currentIndex, setCurrentIndex] = useState(0);
  const [animationClass, setAnimationClass] = useState("");

  if (!hasRegularQuestions && !hasDeepQueryQuestions) return null;

  const showCarouselArrows =
    hasRegularQuestions && relatedQuestions.length > 1;

  const navigate = (direction) => {
    if (!hasRegularQuestions || relatedQuestions.length <= 1) return;

    const total = relatedQuestions.length;
    let nextIndex;

    if (direction === "next") {
      nextIndex = (currentIndex + 1) % total;
      setAnimationClass("slide-in-right");
    } else {
      nextIndex = currentIndex === 0 ? total - 1 : currentIndex - 1;
      setAnimationClass("slide-in-left");
    }

    setCurrentIndex(nextIndex);

    setTimeout(() => {
      setAnimationClass("");
    }, 400);
  };

  const currentQuestion =
    hasRegularQuestions && relatedQuestions[currentIndex];

  return (
    <div className="d-flex flex-column align-items-start mt-3">
      {hasRegularQuestions && (
        <div className="w-100 mb-2">
          <Button
            variant="outline-light"
            size="sm"
            className="text-start w-100 related-question-btn"
            onClick={() => currentQuestion && onAskRelated(currentQuestion)}
          >
            <div className="d-flex align-items-center justify-content-between w-100">
              {showCarouselArrows && (
                <i
                  className="bi bi-chevron-left carousel-arrow-inner"
                  onClick={(e) => {
                    e.stopPropagation();
                    navigate("prev");
                  }}
                />
              )}
              <span
                className={`related-question-text flex-grow-1 text-center ${animationClass}`}
              >
                {currentQuestion}
              </span>
              {showCarouselArrows && (
                <i
                  className="bi bi-chevron-right carousel-arrow-inner"
                  onClick={(e) => {
                    e.stopPropagation();
                    navigate("next");
                  }}
                />
              )}
            </div>
          </Button>
        </div>
      )}

      {hasDeepQueryQuestions &&
        relatedQuestionsDeepQuery.map((q, index) => (
          <Button
            key={`deep_query-${index}`}
            variant="outline-warning"
            size="sm"
            className="mb-2 text-start w-100 analyst-question-btn"
            onClick={() => onAskDeepQuery(q)}
          >
            <div className="d-flex align-items-center justify-content-between w-100">
              <span
                className="text-white flex-grow-1"
                style={{ fontWeight: "500" }}
              >
                {q}
              </span>
              <Badge className="analyst-mode-badge">DeepQuery</Badge>
            </div>
          </Button>
        ))}
    </div>
  );
};

export default RelatedQuestions;

