/* DeepQuery "magic": animated glow + sweeping light while the analysis is running */
.deepquery-magic {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(132, 181, 206, 0.35);
  background: linear-gradient(120deg, rgba(132, 181, 206, 0.10), rgba(167, 139, 250, 0.14), rgba(132, 181, 206, 0.10));
  background-size: 200% 100%;
  box-shadow: 0 0 12px rgba(132, 181, 206, 0.25);
  animation: deepquery-glow 3s ease-in-out infinite;
}

.deepquery-magic::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 40%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.16), transparent);
  transform: translateX(-120%);
  animation: deepquery-sweep 2.4s ease-in-out infinite;
  pointer-events: none;
}

.deepquery-magic i {
  color: #c4b5fd;
  animation: deepquery-sparkle 1.6s ease-in-out infinite;
}

@keyframes deepquery-glow {
  0%, 100% { background-position: 0% 0; box-shadow: 0 0 8px rgba(132, 181, 206, 0.2); }
  50% { background-position: 100% 0; box-shadow: 0 0 16px rgba(167, 139, 250, 0.35); }
}

@keyframes deepquery-sweep {
  to { transform: translateX(350%); }
}

@keyframes deepquery-sparkle {
  0%, 100% { transform: scale(1) rotate(0deg); opacity: 1; }
  50% { transform: scale(1.25) rotate(12deg); opacity: 0.7; }
}

@media (prefers-reduced-motion: reduce) {
  .deepquery-magic,
  .deepquery-magic::after,
  .deepquery-magic i {
    animation: none;
  }

  .deepquery-magic::after {
    display: none;
  }
}

