  min-height: 38px;
  height: auto;
  padding: 0.375rem 0.75rem;
  cursor: text;
}

.chip-input-badge {
  font-size: 0.85rem;
  font-weight: 500;
}

.chip-input-remove-btn {
  font-size: 0.45rem;
}

