}

import React, { useState } from 'react';
import Badge from 'react-bootstrap/Badge';
import './ChipInput.css';

const ChipInput = ({ items, setItems, placeholder, id }) => {
  const [inputValue, setInputValue] = useState('');

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addCurrentItem();
    } 
    else if ((e.key === 'Backspace' || e.key === 'Delete') && inputValue === '' && items.length > 0) {
      e.preventDefault();
      setItems(items.slice(0, -1));
    }
  };

  const handleBlur = () => {
    addCurrentItem();
  };

  const handlePaste = (e) => {
    e.preventDefault();
    const paste = e.clipboardData.getData('text');
    if (paste) {
      const pastedItems = paste.split(/\r?\n/).map(s => s.trim()).filter(s => s);
      if (pastedItems.length > 0) {
        const uniqueItems = Array.from(new Set([...items, ...pastedItems]));
        setItems(uniqueItems);
      }
    }
  };

  const addCurrentItem = () => {
    const trimmed = inputValue.trim();
    if (trimmed && !items.includes(trimmed)) {
      setItems([...items, trimmed]);
    }
    setInputValue('');
  };

  const removeItem = (itemToRemove) => {
    setItems(items.filter(item => item !== itemToRemove));
  };

  return (
    <div 
      className="form-control d-flex flex-wrap gap-2 align-items-center chip-input-container" 
      onClick={() => document.getElementById(id)?.focus()}
    >
      {items.map(item => (
        <Badge 
          key={item} 
          bg="secondary" 
          className="d-flex align-items-center px-2 py-1 chip-input-badge" 
        >
          {item}
          <button 
            type="button" 
            className="btn-close btn-close-white ms-2 chip-input-remove-btn" 
            onClick={(e) => { e.stopPropagation(); removeItem(item); }}
            aria-label="Remove"
          />
        </Badge>
      ))}
      <input
        id={id}
        type="text"
        className="border-0 flex-grow-1 bg-transparent chip-input-field"
        placeholder={items.length === 0 ? placeholder : ''}
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        onPaste={handlePaste}
      />
    </div>
  );
};

export default ChipInput;

import React from 'react';
import PropTypes from 'prop-types';
import Modal from 'react-bootstrap/Modal';
import './Modal.css';

const BaseModal = ({
  show,
  onHide,
  onExited,
  title,
  headerBadges = null,
  size = 'md',
  fixedHeight = false,
  scrollableBody = false,
  backdrop = true,
  nested = false,
  className = '',
  dialogClassName = '',
  footer = null,
  footerClassName = '',
  children,
}) => {
  const modalClass = ['rcc-modal', nested ? 'rcc-modal-nested' : '', className].filter(Boolean).join(' ');
  const dialogClass = ['rcc-dialog', `rcc-dialog-${size}`, fixedHeight ? 'rcc-dialog-fixed' : '', dialogClassName]
    .filter(Boolean)
    .join(' ');
  const bootstrapSize = size === 'md' ? undefined : size;

  return (
    <Modal
      show={show}
      onHide={onHide}
      onExited={onExited}
      backdrop={backdrop}
      size={bootstrapSize}
      centered
      className={modalClass}
      dialogClassName={dialogClass}
      backdropClassName={nested ? 'rcc-backdrop-nested' : 'rcc-backdrop'}
    >
      <Modal.Header closeButton>
        <Modal.Title as="div" className="rcc-modal-title">
          {title}
          {headerBadges}
        </Modal.Title>
      </Modal.Header>
      <Modal.Body className="rcc-body">
        {scrollableBody ? <div className="modal-scroll-container">{children}</div> : children}
      </Modal.Body>
      {footer ? <Modal.Footer className={footerClassName}>{footer}</Modal.Footer> : null}
    </Modal>
  );
};

BaseModal.propTypes = {
  show: PropTypes.bool.isRequired,
  onHide: PropTypes.func.isRequired,
  onExited: PropTypes.func,
  title: PropTypes.node.isRequired,
  headerBadges: PropTypes.node,
  size: PropTypes.oneOf(['sm', 'md', 'lg', 'xl']),
  fixedHeight: PropTypes.bool,
  scrollableBody: PropTypes.bool,
  backdrop: PropTypes.oneOf([true, false, 'static']),
  nested: PropTypes.bool,
  className: PropTypes.string,
  dialogClassName: PropTypes.string,
  footer: PropTypes.node,
  footerClassName: PropTypes.string,
  children: PropTypes.node,
};

export default BaseModal;

import React from 'react';
import PropTypes from 'prop-types';
import BaseModal from './BaseModal';

const ConfirmationModal = ({
  show,
  onHide,
  onConfirm,
  title,
  message = null,
  iconClass = 'bi-exclamation-circle text-danger',
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  confirmVariant = 'danger',
  nested = false,
  size = 'sm',
  children = null,
}) => (
  <BaseModal
    show={show}
    onHide={onHide}
    title={title}
    headerBadges={
      iconClass ? (
        <i className={`bi ${iconClass} rcc-confirm-icon`} aria-hidden="true" />
      ) : null
    }
    size={size}
    nested={nested}
    className="rcc-confirm"
    footer={
      <>
        <button type="button" className="rcc-ghost-btn" onClick={onHide}>
          {cancelLabel}
        </button>
        <button
          type="button"
          className={confirmVariant === 'primary' ? 'rcc-primary-btn' : 'rcc-danger-btn'}
          onClick={onConfirm}
        >
          {confirmLabel}
        </button>
      </>
    }
  >
    <div className="rcc-confirm-content">
      {message && <div className="rcc-confirm-message">{message}</div>}
      {children && <div className="rcc-confirm-extra">{children}</div>}
    </div>
  </BaseModal>
);

ConfirmationModal.propTypes = {
  show: PropTypes.bool.isRequired,
  onHide: PropTypes.func.isRequired,
  onConfirm: PropTypes.func.isRequired,
  title: PropTypes.node.isRequired,
  message: PropTypes.node,
  iconClass: PropTypes.string,
  confirmLabel: PropTypes.node,
  cancelLabel: PropTypes.node,
  confirmVariant: PropTypes.oneOf(['danger', 'primary']),
  nested: PropTypes.bool,
  size: PropTypes.oneOf(['sm', 'md']),
  children: PropTypes.node,
};

export default ConfirmationModal;

