@keyframes rcc-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.85); }
}

import React, { useState, useEffect, useCallback } from 'react';
import PropTypes from 'prop-types';
import { BaseModal, ConfirmationModal } from '../Common/Modal';
import Spinner from 'react-bootstrap/Spinner';
import Table from 'react-bootstrap/Table';
import api from '../../api/client';
import AddCSVForm from './AddCSVForm';
import SourceRow from './SourceRow';
import ScannedFileRow from './ScannedFileRow';
import NotificationToast from '../NotificationToast/NotificationToast';
import './KnowledgeBaseManagerModal.css';

const emptyNewCSV = {
  file: null,
  description: '',
  delimiter: ';',
  path: null,
  sourceName: null,
  vectorizedColumns: [],
  private: false
};

const KnowledgeBaseManagerModal = ({ show, handleClose, hasActiveConversation = false, selectedChatbot }) => {
  const [sources, setSources] = useState([]);
  const [scannedFiles, setScannedFiles] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newCSV, setNewCSV] = useState(emptyNewCSV);
  const [isAdding, setIsAdding] = useState(false);
  const [preview, setPreview] = useState(null);
  const [isLoadingPreview, setIsLoadingPreview] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [editingSource, setEditingSource] = useState(null);
  const [editingDescription, setEditingDescription] = useState('');
  const [currentUsername, setCurrentUsername] = useState('');
  const [currentUserIsAdmin, setCurrentUserIsAdmin] = useState(false);
  const [downloadingSources, setDownloadingSources] = useState(() => new Set());
  const [deletingSources, setDeletingSources] = useState(() => new Set());
  const [togglingPrivateSources, setTogglingPrivateSources] = useState(() => new Set());
  const [confirmDelete, setConfirmDelete] = useState({ show: false, sourceName: '', deleteFile: false });

  const [showInfoBanner, setShowInfoBanner] = useState(true);
  const [showNoteBanner, setShowNoteBanner] = useState(true);

  // Tracks whether the user has made any change to sources during this
  // open-session of the modal. Used to decide whether to warn on close
  // that changes won't apply to an ongoing conversation.
  const [hasChanges, setHasChanges] = useState(false);

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: '',
    variant: 'info',
    title: '',
    duration: 8000,
  });

  const showToast = (message, variant, title, duration = 8000) => {
    setToastConfig({ show: true, message, variant, title, duration });
  };

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  // Flip the dirty flag whenever a mutation succeeds, so we know on close
  // whether to warn that changes won't apply to the ongoing conversation.
  const notifySourcesChanged = useCallback(() => {
    setHasChanges(true);
  }, []);

  // Reset dirty state every time the modal is opened.
  useEffect(() => {
    if (show) {
      setHasChanges(false);
    }
  }, [show]);

  // Intercept the Close button / backdrop dismiss: if the user made changes
  // and there's an ongoing conversation, show the warning via Toast.
  const requestClose = () => {
    if (hasChanges && hasActiveConversation) {
      showToast(
        "Changes saved. The agent may rely on previous context and ignore new files. Ask it to 'search again' or start a new chat.",
        "info",
        "Knowledge base updated",
        8000
      );
    }
    handleClose();
  };

  const addBusy = (setter, name) =>
    setter((prev) => {
      const next = new Set(prev);
      next.add(name);
      return next;
    });
  const removeBusy = (setter, name) =>
    setter((prev) => {
      const next = new Set(prev);
      next.delete(name);
      return next;
    });

  useEffect(() => {
    setCurrentUsername(localStorage.getItem('current_user') || '');
  }, [show]);

  const fetchSources = useCallback(async () => {
    if (!show) return;
    setIsLoading(true);
    setError(null);
    try {
      const response = await api.get('csv/list');
      if (response.data.success) {
        setSources(response.data.sources || []);
        setCurrentUserIsAdmin(!!response.data.current_user_is_admin);
      }
    } catch (err) {
      setError('Failed to load CSV sources');
      console.error('Error fetching CSV sources:', err);
    } finally {
      setIsLoading(false);
    }
  }, [show]);

  const fetchScannedFiles = useCallback(async () => {
    if (!show) return;
    try {
      const response = await api.get('csv/scan');
      if (response.data.success) {
        const sourceNames = new Set(sources.map((s) => s.source_name));
        setScannedFiles((response.data.files || []).filter((f) => !sourceNames.has(f.source_name)));
      }
    } catch (err) {
      console.error('Error scanning CSV files:', err);
    }
  }, [show, sources]);

  useEffect(() => { fetchSources(); }, [fetchSources]);
  useEffect(() => { fetchScannedFiles(); }, [fetchScannedFiles]);

  const handleDelete = (sourceName, deleteFile = false) => {
    if (deletingSources.has(sourceName)) return;
    setConfirmDelete({ show: true, sourceName, deleteFile });
  };

  const executeDelete = async () => {
    const { sourceName, deleteFile } = confirmDelete;
    setConfirmDelete((prev) => ({ ...prev, show: false }));
    if (!sourceName || deletingSources.has(sourceName)) return;
    addBusy(setDeletingSources, sourceName);
    try {
      const response = await api.delete(`csv/delete/${sourceName}`, { data: { delete_file: deleteFile } });
      if (response.data.success) {
        setSources((prev) => prev.filter((s) => s.source_name !== sourceName));
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to delete source: ${err.response?.data?.error || err.message}`);
    } finally {
      removeBusy(setDeletingSources, sourceName);
    }
  };

  const handleTogglePrivate = async (sourceName, nextPrivate) => {
    if (togglingPrivateSources.has(sourceName)) return;
    addBusy(setTogglingPrivateSources, sourceName);
    try {
      const response = await api.post('csv/set_private', { source_name: sourceName, private: nextPrivate });
      if (response.data.success) {
        setSources((prev) => prev.map((s) =>
          s.source_name === sourceName ? { ...s, private: nextPrivate } : s
        ));
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to update visibility: ${err.response?.data?.error || err.message}`);
    } finally {
      removeBusy(setTogglingPrivateSources, sourceName);
    }
  };

  const handleDownload = async (sourceName) => {
    if (downloadingSources.has(sourceName)) return;
    setDownloadingSources((prev) => {
      const next = new Set(prev);
      next.add(sourceName);
      return next;
    });
    try {
      const response = await api.get(`csv/download/${sourceName}`, { responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([response.data], { type: 'text/csv' }));
      const link = document.createElement('a');
      link.href = url;
      link.download = `${sourceName}_with_embeddings.csv`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      setError(`Failed to download CSV: ${err.response?.data?.error || err.message}`);
    } finally {
      setDownloadingSources((prev) => {
        const next = new Set(prev);
        next.delete(sourceName);
        return next;
      });
    }
  };

  const handleUpdateDescription = async (sourceName) => {
    if (!editingDescription.trim()) { setError('Description cannot be empty'); return; }
    try {
      const response = await api.post('csv/update_description', {
        source_name: sourceName,
        description: editingDescription.trim()
      });
      if (response.data.success) {
        setSources((prev) => prev.map((s) =>
          s.source_name === sourceName ? { ...s, description: editingDescription.trim() } : s
        ));
        setEditingSource(null);
        setEditingDescription('');
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to update description: ${err.response?.data?.error || err.message}`);
    }
  };

  const handleStartEditing = (source) => {
    setEditingSource(source.source_name);
    setEditingDescription(source.description || '');
  };

  const handleCancelEditing = () => {
    setEditingSource(null);
    setEditingDescription('');
  };

  const handleAddScannedFile = async (scannedFile) => {
    setIsLoadingPreview(true);
    setShowAddForm(true);
    setNewCSV({ ...emptyNewCSV, path: scannedFile.path, sourceName: scannedFile.source_name });
    try {
      const response = await api.post('csv/preview', { path: scannedFile.path });
      if (response.data.success) {
        setPreview(response.data);
        setNewCSV((prev) => ({
          ...prev,
          delimiter: response.data.delimiter,
          vectorizedColumns: response.data.columns || []
        }));
      }
    } catch (err) {
      setError(`Failed to preview CSV: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsLoadingPreview(false);
    }
  };

  const handleGenerateDescription = async () => {
    if (!newCSV.file && !newCSV.path) return;
    setIsGeneratingDescription(true);
    try {
      let response;
      const vectorizedColumns = newCSV.vectorizedColumns || [];
      if (newCSV.path) {
        response = await api.post('csv/generate_description', {
          path: newCSV.path,
          delimiter: newCSV.delimiter,
          vectorized_columns: vectorizedColumns
        });
      } else {
        const formData = new FormData();
        formData.append('file', newCSV.file);
        formData.append('delimiter', newCSV.delimiter);
        formData.append('vectorized_columns', JSON.stringify(vectorizedColumns));
        response = await api.post('csv/generate_description', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
      }
      if (response.data.success) {
        setNewCSV((prev) => ({ ...prev, description: response.data.description }));
      }
    } catch (err) {
      setError(`Failed to generate description: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsGeneratingDescription(false);
    }
  };

  const handleAddSource = async (e) => {
    e.preventDefault();
    if (!newCSV.file && !newCSV.path) { setError('Please select a CSV file'); return; }
    if (!newCSV.description) { setError('Description is required'); return; }
    if (!newCSV.vectorizedColumns || newCSV.vectorizedColumns.length === 0) {
      setError('Select at least one column to vectorize');
      return;
    }

    setIsAdding(true);
    setError(null);
    try {
      let response;
      const vectorizedColumnsJson = JSON.stringify(newCSV.vectorizedColumns);
      if (newCSV.path) {
        response = await api.post('csv/add', {
          path: newCSV.path,
          source_name: newCSV.sourceName,
          description: newCSV.description,
          delimiter: newCSV.delimiter,
          auto_detect_delimiter: false,
          auto_generate_description: false,
          vectorized_columns: newCSV.vectorizedColumns,
          private: currentUserIsAdmin ? !!newCSV.private : true
        });
      } else {
        const formData = new FormData();
        formData.append('file', newCSV.file);
        formData.append('description', newCSV.description);
        formData.append('delimiter', newCSV.delimiter);
        formData.append('auto_detect_delimiter', 'false');
        formData.append('auto_generate_description', 'false');
        formData.append('vectorized_columns', vectorizedColumnsJson);
        formData.append('private', (currentUserIsAdmin ? !!newCSV.private : true) ? 'true' : 'false');
        response = await api.post('csv/add', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
      }

      if (response.data.success) {
        await fetchSources();
        setNewCSV(emptyNewCSV);
        setPreview(null);
        setShowAddForm(false);
        notifySourcesChanged();
      }
    } catch (err) {
      setError(`Failed to add CSV: ${err.response?.data?.error || err.message}`);
    } finally {
      setIsAdding(false);
    }
  };

  const handleFileChange = async (e) => {
    const file = e.target.files?.[0];
    if (file?.name.endsWith('.csv')) {
      setNewCSV((prev) => ({ ...prev, file, sourceName: file.name.replace(/\.csv$/, '') }));
      setPreview(null);
      setIsLoadingPreview(true);
      try {
        const formData = new FormData();
        formData.append('file', file);
        const response = await api.post('csv/preview', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        if (response.data.success) {
          setPreview(response.data);
          setNewCSV((prev) => ({
            ...prev,
            delimiter: response.data.delimiter,
            vectorizedColumns: response.data.columns || []
          }));
        }
      } catch (err) {
        setError(`Failed to preview CSV: ${err.response?.data?.error || err.message}`);
      } finally {
        setIsLoadingPreview(false);
      }
    } else if (file) {
      setError('Please select a valid CSV file');
      e.target.value = null;
    }
  };

  const handleCancelAddForm = () => {
    setShowAddForm(false);
    setPreview(null);
    setNewCSV(emptyNewCSV);
  };

  const hasNoData = sources.length === 0 && scannedFiles.length === 0;

  return (
    <>
      <BaseModal
        show={show}
        onHide={requestClose}
        title="Knowledge Base Manager"
        headerBadges={
          <>
            <span className="rcc-quota">
              {sources.length} sources
            </span>
            {scannedFiles.length > 0 && (
              <span className="rcc-live" title="Scanned files detected">
                <span className="rcc-live-dot" />
                {scannedFiles.length} scanned
              </span>
            )}
          </>
        }
        size="xl"
        fixedHeight
        scrollableBody
        backdrop="static"
        className="kbm-modal"
      >
          <>
            {error && (
              <div className="rcc-banner rcc-banner-danger" role="alert">
                <i className="bi bi-exclamation-triangle-fill" />
                <div>{error}</div>
                <button
                  type="button"
                  className="rcc-banner-close"
                  onClick={() => setError(null)}
                  aria-label="Dismiss error"
                >
                  <i className="bi bi-x" />
                </button>
              </div>
            )}

            {showInfoBanner && (
              <div className="rcc-banner rcc-banner-info">
                <i className="bi bi-info-circle-fill" />
                <div>
                  Knowledge base collections are available to both the general chatbot and specialized agents.
                  To activate or deactivate collections per agent, open that agent's settings under <strong>Administration</strong>.
                </div>
                <button
                  type="button"
                  className="rcc-banner-close"
                  onClick={() => setShowInfoBanner(false)}
                  aria-label="Dismiss note"
                >
                  <i className="bi bi-x" />
                </button>
              </div>
            )}

            {showNoteBanner && (
              <div className="rcc-banner rcc-banner-note">
                <i className="bi bi-info-circle" />
                <div>
                  <strong>Note:</strong> Files in <code>sample_chatbot/sample_data/unstructured</code> are scanned automatically and shown as "Scanned" until someone adds them.
                </div>
                <button
                  type="button"
                  className="rcc-banner-close"
                  onClick={() => setShowNoteBanner(false)}
                  aria-label="Dismiss note"
                >
                  <i className="bi bi-x" />
                </button>
              </div>
            )}

            {showAddForm ? (
              <AddCSVForm
                newCSV={newCSV}
                setNewCSV={setNewCSV}
                preview={preview}
                isLoadingPreview={isLoadingPreview}
                isGeneratingDescription={isGeneratingDescription}
                isAdding={isAdding}
                currentUserIsAdmin={currentUserIsAdmin}
                onSubmit={handleAddSource}
                onCancel={handleCancelAddForm}
                onFileChange={handleFileChange}
                onGenerateDescription={handleGenerateDescription}
              />
            ) : (
              <button
                type="button"
                className="rcc-light-btn mb-3"
                onClick={() => setShowAddForm(true)}
              >
                <i className="bi bi-plus-lg" />
                Add CSV Source
              </button>
            )}

            {isLoading && !showAddForm && (
              <div className="text-center p-5">
                <Spinner animation="border" variant="secondary" />
              </div>
            )}

            {!isLoading && hasNoData && (
              <div className="rcc-empty">
                <i className="bi bi-file-earmark-spreadsheet" />
                <p className="mb-1 fw-semibold">No CSV sources configured</p>
                <p className="text-muted mb-0 small">
                  Click "Add CSV Source" above to import your first dataset.
                </p>
              </div>
            )}

            {!isLoading && !hasNoData && (
              <div
                className="kbm-table-wrapper table-responsive"
                tabIndex={0}
                role="region"
                aria-label="Scrollable knowledge base table"
              >
                <Table hover size="sm" className="mb-0">
                  <thead>
                    <tr>
                      <th style={{ minWidth: '10rem' }}>Name</th>
                      <th style={{ minWidth: '8rem' }}>Status</th>
                      <th style={{ minWidth: '12rem' }}>Description</th>
                      <th style={{ minWidth: '7rem' }}>Owner</th>
                      <th style={{ minWidth: '11rem' }}>Uploaded</th>
                      <th style={{ minWidth: '11rem' }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {[...sources]
                      .sort((a, b) => {
                        const getOrder = (s) => (s.path_valid === false ? 2 : s.private ? 1 : 0);
                        return getOrder(a) - getOrder(b);
                      })
                      .map((source) => (
                      <SourceRow
                        key={source.source_name}
                        source={source}
                        currentUsername={currentUsername}
                        editingSource={editingSource}
                        editingDescription={editingDescription}
                        onDelete={handleDelete}
                        onDownload={handleDownload}
                        isDownloading={downloadingSources.has(source.source_name)}
                        isDeleting={deletingSources.has(source.source_name)}
                        isTogglingPrivate={togglingPrivateSources.has(source.source_name)}
                        onTogglePrivate={handleTogglePrivate}
                        onStartEditing={handleStartEditing}
                        onUpdateDescription={handleUpdateDescription}
                        onCancelEditing={handleCancelEditing}
                        setEditingDescription={setEditingDescription}
                      />
                    ))}
                    {scannedFiles.map((scannedFile) => (
                      <ScannedFileRow
                        key={`scanned-${scannedFile.source_name}`}
                        scannedFile={scannedFile}
                        onAdd={handleAddScannedFile}
                      />
                    ))}
                  </tbody>
                </Table>
              </div>
            )}
          </>
      </BaseModal>

      <ConfirmationModal
        show={confirmDelete.show}
        onHide={() => setConfirmDelete((prev) => ({ ...prev, show: false }))}
        onConfirm={executeDelete}
        nested
        title="Delete CSV Source"
        message={`Are you sure you want to permanently delete "${confirmDelete.sourceName}"? This removes it for all users of this chatbot.${confirmDelete.deleteFile ? ' The CSV file will also be deleted.' : ''}`}
        confirmLabel="Yes, delete"
      />

      <NotificationToast
        show={toastConfig.show}
        message={toastConfig.message}
        variant={toastConfig.variant}
        title={toastConfig.title}
        duration={toastConfig.duration}
        onClose={handleToastClose}
      />
    </>
  );
};

KnowledgeBaseManagerModal.propTypes = {
  show: PropTypes.bool.isRequired,
  handleClose: PropTypes.func.isRequired,
  hasActiveConversation: PropTypes.bool,
  selectedChatbot: PropTypes.object
};

export default KnowledgeBaseManagerModal;

import React from 'react';
import PropTypes from 'prop-types';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Tooltip from 'react-bootstrap/Tooltip';

const OVERLAY_PROPS = { container: () => document.body, popperConfig: { strategy: 'fixed' } };

const ScannedFileRow = ({ scannedFile, onAdd }) => {
  return (
    <tr style={{ backgroundColor: '#fffdf5' }}>
      <td style={{ maxWidth: '260px', overflowWrap: 'anywhere', wordBreak: 'break-word' }}>
        <span className="skm-code-badge">{scannedFile.source_name}</span>
      </td>

      <td>
        <span className="rcc-badge rcc-badge-warning">
          <i className="bi bi-radar" />
          Scanned
        </span>
      </td>

      <td>
        <span className="small text-muted fst-italic">Not yet vectorized</span>
      </td>

      <td>
        <span className="small text-muted">—</span>
      </td>

      <td>
        <span className="small text-muted">—</span>
      </td>

      <td>
        <div className="d-flex align-items-center">
          <OverlayTrigger
            placement="top"
            overlay={<Tooltip id={`tip-add-${scannedFile.source_name}`}>Add scanned CSV</Tooltip>}
            {...OVERLAY_PROPS}
          >
            <button
              type="button"
              className="rcc-icon-btn"
              onClick={() => onAdd(scannedFile)}
              aria-label="Add scanned file"
            >
              <i className="bi bi-plus-circle" />
            </button>
          </OverlayTrigger>
        </div>
      </td>
    </tr>
  );
};

ScannedFileRow.propTypes = {
  scannedFile: PropTypes.shape({
    source_name: PropTypes.string.isRequired,
    path: PropTypes.string.isRequired
  }).isRequired,
  onAdd: PropTypes.func.isRequired
};

export default ScannedFileRow;

import React from 'react';
import PropTypes from 'prop-types';
import Form from 'react-bootstrap/Form';
import Spinner from 'react-bootstrap/Spinner';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Tooltip from 'react-bootstrap/Tooltip';

const OVERLAY_PROPS = { container: () => document.body, popperConfig: { strategy: 'fixed' } };

const formatDate = (ms) => {
  if (!ms) return '—';
  const d = new Date(typeof ms === 'number' ? ms : Number(ms));
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleString(undefined, {
    year: 'numeric', month: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit'
  });
};

const SourceRow = ({
  source,
  currentUsername,
  editingSource,
  editingDescription,
  onDelete,
  isDeleting,
  onDownload,
  isDownloading,
  onTogglePrivate,
  isTogglingPrivate,
  onStartEditing,
  onUpdateDescription,
  onCancelEditing,
  setEditingDescription
}) => {
  const isEditing = editingSource === source.source_name;
  const hasDescription = Boolean(source.description?.trim());
  const isOwner = source.is_owner ?? (source.owner && source.owner === currentUsername);
  const isPrivate = Boolean(source.private);
  const canSubscribe = source.can_subscribe ?? !isPrivate ?? isOwner;
  const canDelete = source.can_delete ?? isOwner;
  const canEdit = source.can_edit ?? isOwner;
  const canMakePublic = source.can_make_public ?? false;
  const canMakePrivate = source.can_make_private ?? isOwner;
  const canTogglePrivacy = isPrivate ? canMakePublic : canMakePrivate;

  return (
    <tr>
      <td style={{ maxWidth: '260px', overflowWrap: 'anywhere', wordBreak: 'break-word' }}>
        <span className="skm-code-badge">{source.source_name}</span>
        {source.document_count ? (
          <span className="text-muted ms-2 small">
            ({source.document_count} rows)
          </span>
        ) : null}
      </td>

      <td>
        <div className="d-flex flex-wrap gap-1 align-items-center">
          {isPrivate ? (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tip-priv-${source.source_name}`}>Visible only to you</Tooltip>}
              {...OVERLAY_PROPS}
            >
              <span className="rcc-badge rcc-badge-personal">
                <i className="bi bi-lock-fill" />
                Private
              </span>
            </OverlayTrigger>
          ) : (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tip-pub-${source.source_name}`}>Any user in this chatbot can have access to this knowledge base</Tooltip>}
              {...OVERLAY_PROPS}
            >
              <span className="rcc-badge rcc-badge-system">
                <i className="bi bi-globe2" />
                Public
              </span>
            </OverlayTrigger>
          )}

          {source.agent_managed && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tip-agent-${source.source_name}`}>Declared in the agent's configuration — always active for every user of this agent</Tooltip>}
              {...OVERLAY_PROPS}
            >
              <span className="rcc-badge rcc-badge-personal">
                <i className="bi bi-robot" />
                Agent
              </span>
            </OverlayTrigger>
          )}

          {!source.path_valid && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tip-missing-${source.source_name}`}>Original CSV file is gone, but vectors are still searchable.</Tooltip>}
              {...OVERLAY_PROPS}
            >
              <span className="rcc-badge rcc-badge-error">
                <i className="bi bi-exclamation-triangle-fill" />
                File missing
              </span>
            </OverlayTrigger>
          )}
        </div>
      </td>

      <td>
        {isEditing ? (
          <div className="d-flex flex-column gap-2 p-1">
            <Form.Control
              as="textarea"
              rows={2}
              size="sm"
              value={editingDescription}
              onChange={(e) => setEditingDescription(e.target.value)}
              autoFocus
              className="skm-input"
            />
            <div className="d-flex gap-2">
              <button
                type="button"
                className="rcc-light-btn"
                style={{ height: '28px', padding: '0 0.65rem', fontSize: '0.78rem' }}
                onClick={() => onUpdateDescription(source.source_name)}
              >
                Save
              </button>
              <button
                type="button"
                className="rcc-ghost-btn"
                style={{ height: '28px', padding: '0 0.65rem', fontSize: '0.78rem' }}
                onClick={onCancelEditing}
              >
                Cancel
              </button>
            </div>
          </div>
        ) : (
          <div
            className="small text-secondary"
            onDoubleClick={() => canEdit && onStartEditing(source)}
            style={{ cursor: canEdit ? 'pointer' : 'default' }}
            title={canEdit ? 'Double-click to edit description' : 'Only the owner can edit the description'}
          >
            {hasDescription ? (
              <>
                {source.description.substring(0, 100)}
                {source.description.length > 100 ? '...' : ''}
              </>
            ) : (
              <em className="text-muted">No description</em>
            )}
          </div>
        )}
      </td>

      <td>
        <span className="small text-secondary">
          {source.owner || '—'}
        </span>
      </td>

      <td>
        <span className="small text-muted">
          {formatDate(source.last_vectorized)}
        </span>
      </td>

      <td>
        <div className="d-flex align-items-center gap-1">
          {canSubscribe && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tip-dl-${source.source_name}`}>{isDownloading ? 'Preparing CSV…' : 'Download CSV'}</Tooltip>}
              {...OVERLAY_PROPS}
            >
              <button
                type="button"
                className="rcc-icon-btn"
                onClick={() => onDownload(source.source_name)}
                disabled={isDownloading}
                aria-label="Download CSV"
              >
                {isDownloading ? (
                  <Spinner animation="border" size="sm" />
                ) : (
                  <i className="bi bi-download" />
                )}
              </button>
            </OverlayTrigger>
          )}

          {canTogglePrivacy && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tip-priv-toggle-${source.source_name}`}>
                {isTogglingPrivate
                  ? 'Updating visibility…'
                  : isPrivate
                    ? 'Publish (admin only)'
                    : 'Make private (only you can see it)'}
              </Tooltip>}
              {...OVERLAY_PROPS}
            >
              <button
                type="button"
                className="rcc-icon-btn"
                onClick={() => onTogglePrivate(source.source_name, !isPrivate)}
                disabled={isTogglingPrivate || isDeleting}
                aria-label={isPrivate ? 'Publish' : 'Make private'}
              >
                {isTogglingPrivate ? (
                  <Spinner animation="border" size="sm" />
                ) : (
                  <i className={`bi ${isPrivate ? 'bi-unlock' : 'bi-lock'}`} />
                )}
              </button>
            </OverlayTrigger>
          )}

          {canDelete && (
            <OverlayTrigger
              placement="top"
              overlay={<Tooltip id={`tip-del-${source.source_name}`}>{isOwner ? 'Delete collection' : 'Admin: delete collection'}</Tooltip>}
              {...OVERLAY_PROPS}
            >
              <button
                type="button"
                className="rcc-icon-btn rcc-icon-btn-danger"
                onClick={() => onDelete(source.source_name, false)}
                disabled={isDeleting || isTogglingPrivate}
                aria-label="Delete collection"
              >
                {isDeleting ? (
                  <Spinner animation="border" size="sm" />
                ) : (
                  <i className="bi bi-trash" />
                )}
              </button>
            </OverlayTrigger>
          )}
        </div>
      </td>
    </tr>
  );
};

SourceRow.propTypes = {
  source: PropTypes.shape({
    source_name: PropTypes.string.isRequired,
    active: PropTypes.bool.isRequired,
    description: PropTypes.string,
    path_valid: PropTypes.bool,
    owner: PropTypes.string,
    is_owner: PropTypes.bool,
    document_count: PropTypes.number,
    vectorized_columns: PropTypes.arrayOf(PropTypes.string),
    last_vectorized: PropTypes.number,
    private: PropTypes.bool,
    agent_managed: PropTypes.bool,
    can_subscribe: PropTypes.bool,
    can_delete: PropTypes.bool,
    can_edit: PropTypes.bool,
    can_make_public: PropTypes.bool,
    can_make_private: PropTypes.bool
  }).isRequired,
  currentUsername: PropTypes.string,
  editingSource: PropTypes.string,
  editingDescription: PropTypes.string.isRequired,
  onDelete: PropTypes.func.isRequired,
  isDeleting: PropTypes.bool,
  onDownload: PropTypes.func.isRequired,
  isDownloading: PropTypes.bool,
  onTogglePrivate: PropTypes.func.isRequired,
  isTogglingPrivate: PropTypes.bool,
  onStartEditing: PropTypes.func.isRequired,
  onUpdateDescription: PropTypes.func.isRequired,
  onCancelEditing: PropTypes.func.isRequired,
  setEditingDescription: PropTypes.func.isRequired
};

export default SourceRow;

// Helper function to format delimiter label
export const getDelimiterLabel = (delimiter) => {
  if (delimiter === ',') return 'comma (,)';
  if (delimiter === ';') return 'semicolon (;)';
  return `"${delimiter}"`;
};

