import Form from "react-bootstrap/Form";
import Navbar from "react-bootstrap/Navbar";
import Button from "react-bootstrap/Button";
import Dropdown from "react-bootstrap/Dropdown";
import React, { useEffect, useState } from "react";
import ContextSelectionModal from "./ContextSelectionModal";
import useQuestionForm from "../../hooks/useQuestionForm";
import NotificationToast from "../NotificationToast/NotificationToast";
import ContextUsageIndicator from "./ContextUsageIndicator";
import ContextViewsRow from "./ContextViewsRow";
import "./QuestionForm.css";

const baseToolOptions = [
  { id: 'auto', label: 'Auto (Default)', bg: '#6c757d', icon: 'bi-stars', iconColor: '#6c757d' }, 
  { id: 'deep_query', label: 'Deep Query', bg: 'linear-gradient(135deg, #ED342A 0%, #413581 100%)', icon: 'bi-magic', iconColor: '#7953aa' },
  { id: 'generate_vql', label: 'Generate VQL', bg: '#0d6efd', icon: 'bi-database', iconColor: '#0d6efd' },
  { id: 'execute_vql', label: 'Execute VQL', bg: '#0dcaf0', icon: 'bi-play-circle', iconColor: '#0dcaf0' },
  { id: 'generate_graph', label: 'Generate Graph', bg: '#6f42c1', icon: 'bi-bar-chart', iconColor: '#6f42c1' },
  { id: 'metadata_search', label: 'Metadata Search', bg: '#20c997', icon: 'bi-code-slash', iconColor: '#20c997' }, 
  { id: 'knowledge_query', label: 'Knowledge Base Query', bg: '#fd7e14', icon: 'bi-book', iconColor: '#fd7e14' }
];

const QuestionForm = ({ 
  results, 
  dispatch, 
  isAuthenticated, 
  currentQuestion: propCurrentQuestion,
  setCurrentQuestion: propSetCurrentQuestion,
  questionType,
  setQuestionType,
  sdk,
  syncedResources,
  partialResources,
  selectedChatbot,
  contextUsage,
  showContextUsage,
}) => {
  const {
    currentQuestion,
    showFilterModal,
    setShowFilterModal,
    searchFilters,
    allowExternalAssociations,
    isQueryRunning,
    isAnyQueryRunning,
    filterCount,
    textInputRef,
    handleQuestionChange,
    handleFilterSave,
    handleSendClick,
    handleCancelQuery,
    lastToolRequest,
    config,
    profile,
  } = useQuestionForm(
    propCurrentQuestion,
    propSetCurrentQuestion,
    results,
    dispatch,
    sdk,
    isAuthenticated,
    selectedChatbot
  );

  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: "",
    variant: "info",
    title: "",
  });

  const toolOptions = baseToolOptions.filter(tool => {
    if (tool.id === 'deep_query') return config.enable_deep_query;
    if (tool.id === 'knowledge_query') return config.unstructured_mode;
    return true;
  });

  const activeTool = toolOptions.find(t => t.id === questionType) || toolOptions.find(t => t.id === 'auto') || baseToolOptions[0];

  useEffect(() => {
    setQuestionType('auto');
  }, [selectedChatbot, setQuestionType]);

  const handleToastClose = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  useEffect(() => {
    if (lastToolRequest) {
      if (lastToolRequest.name === 'deep_query' && !config.enable_deep_query) return;
      if (lastToolRequest.name === 'knowledge_query' && !config.unstructured_mode) return;

      const matchedTool = baseToolOptions.find(tool => tool.id === lastToolRequest.name);
      const toolLabel = (matchedTool && matchedTool.label) || lastToolRequest.prettyName || lastToolRequest.name || "tool";

      setToastConfig({
        show: true,
        message: `Requested the "${toolLabel}" tool for this question.`,
        variant: "info",
        title: "Tool Requested",
      });
    }
  }, [lastToolRequest, config.enable_deep_query, config.unstructured_mode]);

  const handleSubmitWithTool = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    const forceTool = activeTool.id === 'auto' ? null : activeTool.id;
    handleSendClick(e, forceTool);
    setQuestionType('auto');
  };

  const handleQuestionKeyDown = (e) => {
    if (e.key !== 'Enter') return;

    if (profile.input_method === 'ctrl_enter') {
      // metaKey is checked because macOS reports Cmd as metaKey, never as ctrlKey,
      // so Cmd+Enter is accepted alongside Ctrl+Enter on Mac keyboards
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        handleSubmitWithTool(e);
      } else if (!e.shiftKey) {
        // Plain Enter is ignored so the Enter that completes an IME conversion never sends
        e.preventDefault();
      }
    } else if (!e.shiftKey) {
      e.preventDefault();
      handleSubmitWithTool(e);
    }
  };

  const getPlaceholder = () => {
    if (!isAuthenticated) return "Please sign in to ask questions";

    let options = ['@data', '@vql', '@graph', '@metadata'];
    if (config.unstructured_mode) options.push('@kb');
    if (config.enable_deep_query) options.push('@deepquery');

    return `Type your question here. Use @ to ask the LLM to use a specific tool, e.g. ${options.join(', ')}.`;
  };

  const getPaddingRight = () => {
    let base = 60;
    if (isQueryRunning) {
      base += 80;
    } else {
      base += 40;
    }
    return `${base}px`;
  };

  return (
    <>
    <NotificationToast
      show={toastConfig.show}
      message={toastConfig.message}
      variant={toastConfig.variant}
      title={toastConfig.title}
      onClose={handleToastClose}
    />

    <Navbar className="justify-content-center w-100" data-bs-theme="dark" style={{ backgroundColor: "transparent" }}>
      <div className="w-100 d-flex justify-content-center">
        <div style={{ width: '80%', maxWidth: '800px' }}>
          {isAuthenticated && (showContextUsage || (contextUsage?.views || []).length > 0) && (
            <div className="context-composer-bar">
              <ContextViewsRow
                views={contextUsage?.views || []}
                dataCatalogUrl={config.data_marketplace_url}
              />
              {showContextUsage && (
                <ContextUsageIndicator
                  usage={contextUsage}
                  draftText={isAnyQueryRunning ? "" : currentQuestion}
                />
              )}
            </div>
          )}
          <Form onSubmit={handleSubmitWithTool}>
            <div className="position-relative">
              <div
                className="position-absolute" 
                style={{ left: '12px', top: '50%', transform: 'translateY(-50%)', zIndex: 5, display: 'flex', alignItems: 'center' }}
              >
                {config.filters_enabled && (
                  <Button
                    variant="link"
                    onClick={() => setShowFilterModal(true)}
                    disabled={!isAuthenticated || isAnyQueryRunning}
                    title="Context selection"
                    style={{ 
                      color: '#6c757d', 
                      textDecoration: 'none',
                      padding: '0.2rem 0.4rem',
                      position: 'relative'
                    }}
                    onMouseEnter={(e) => e.target.style.color = '#112533'}
                    onMouseLeave={(e) => e.target.style.color = '#6c757d'}
                  >
                    <i className="bi bi-filter" style={{ fontSize: '1.25rem' }}></i>
                    {filterCount > 0 && (
                      <span 
                        className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                        style={{ 
                              fontSize: '0.6em', 
                              padding: '0.3em 0.5em',
                              pointerEvents: 'none' 
                          }}
                      >
                        {filterCount}
                      </span>
                    )}
                  </Button>
                )}
              </div>
              <Form.Control
                ref={textInputRef}
                as="textarea"
                type="text"
                placeholder={getPlaceholder()}
                value={currentQuestion}
                onChange={handleQuestionChange}
                onKeyDown={handleQuestionKeyDown}
                disabled={!isAuthenticated}
                className="question-textarea bg-white"
                style={{ 
                  paddingRight: getPaddingRight(),
                  paddingLeft: '60px',
                  paddingTop: '12px',
                  paddingBottom: '12px',
                  minHeight: '47px',
                  resize: 'none',
                  color: '#212529',
                  border: '1px solid #ced4da',
                  borderRadius: '1.25em',
                  boxShadow: '0 2px 6px rgba(0,0,0,0.05)'
                }}
              />
              <div className="position-absolute" style={{ right: '12px', top: '50%', transform: 'translateY(-50%)', display: 'flex', gap: '8px', alignItems: 'center' }}>
                {isQueryRunning ? (
                  <Button
                    variant="link"
                    type="button"
                    onClick={handleCancelQuery}
                    title="Stop"
                    style={{
                      color: '#dc3545',
                      textDecoration: 'none',
                      padding: '0.2rem',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      transition: 'all 0.2s ease'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.color = '#a71d2a';
                      e.currentTarget.style.transform = 'scale(1.15)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.color = '#dc3545';
                      e.currentTarget.style.transform = 'scale(1)';
                    }}
                  >
                    <i className="bi bi-stop-circle" style={{ fontSize: '1.2rem', pointerEvents: 'none' }}></i>
                  </Button>
                ) : (
                  <Dropdown drop="up" title={activeTool.label}>
                    <Dropdown.Toggle
                      size="sm"
                      disabled={!isAuthenticated || isAnyQueryRunning}
                      style={{
                        background: activeTool.id === 'auto' ? 'transparent' : activeTool.bg,
                        border: activeTool.id === 'auto' ? '1px solid #ced4da' : 'none',
                        color: activeTool.id === 'auto' ? '#6c757d' : 'white',
                        height: '32px',
                        transition: 'all 0.3s ease',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: '0 10px',
                        borderRadius: '8px'
                      }}
                      id="dropdown-tool-selector"
                    >
                      <i className={`bi ${activeTool.icon}`} style={{ fontSize: '1.1rem' }}></i>
                    </Dropdown.Toggle>

                    <Dropdown.Menu
                      align="end"
                      className="shadow border-0 mb-2"
                      style={{
                        fontSize: '0.9rem',
                        minWidth: '200px',
                        borderRadius: '0.75rem',
                        backgroundColor: '#ffffff',
                        padding: '0.5rem 0'
                      }}
                    >
                      <Dropdown.Header className="py-1 fw-bold" style={{ fontSize: '0.75rem', textTransform: 'uppercase', color: '#112533' }}>
                        Select Mode
                      </Dropdown.Header>

                      {toolOptions.map(tool => (
                        <Dropdown.Item
                          key={tool.id}
                          onClick={() => setQuestionType(tool.id)}
                          className={`py-2 d-flex align-items-center ${activeTool.id === tool.id ? 'fw-bold' : ''}`}
                          style={{
                            color: '#212529',
                            backgroundColor: activeTool.id === tool.id ? '#f8f9fa' : 'transparent',
                            cursor: 'pointer'
                          }}
                        >
                          <i
                            className={`bi ${tool.icon} me-2`}
                            style={{
                              fontSize: '1.1rem',
                              color: activeTool.id === tool.id ? (tool.iconColor || tool.bg.split(' ')[0]) : '#6c757d'
                            }}
                          ></i>
                          {tool.label}
                        </Dropdown.Item>
                      ))}
                    </Dropdown.Menu>
                  </Dropdown>
                )}

                <Button
                  variant="link"
                  type="button"
                  onClick={handleSubmitWithTool}
                  disabled={!isAuthenticated || isAnyQueryRunning}
                  title="Send question"
                  style={{
                    color: activeTool.id === 'auto' ? '#112533' : (activeTool.iconColor || activeTool.bg.split(' ')[0]),
                    textDecoration: 'none',
                    padding: '0.2rem',
                    opacity: (!isAuthenticated || isAnyQueryRunning || !currentQuestion.trim()) ? 0.4 : 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    transition: 'all 0.2s ease'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.color = activeTool.id === 'auto' ? '#0056b3' : (activeTool.iconColor || activeTool.bg.split(' ')[0]);
                    e.currentTarget.style.transform = 'scale(1.15)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.color = activeTool.id === 'auto' ? '#112533' : (activeTool.iconColor || activeTool.bg.split(' ')[0]);
                    e.currentTarget.style.transform = 'scale(1)';
                  }}
                >
                  <i className="bi bi-send" style={{ fontSize: '1.2rem', pointerEvents: 'none' }}></i>
                </Button>
               </div>
            </div>
          </Form>
        </div>
       </div>
     </Navbar>

    <ContextSelectionModal 
      show={showFilterModal}
      handleClose={() => setShowFilterModal(false)}
      syncedResources={syncedResources}
      partialResources={partialResources}
      currentFilters={searchFilters}
      currentAllowExternalAssociations={allowExternalAssociations}
      onSave={handleFilterSave}
    />
  </>
  );
};

export default QuestionForm;

import React, { useEffect, useMemo, useState } from "react";
import PropTypes from "prop-types";
import Badge from "react-bootstrap/Badge";
import Spinner from "react-bootstrap/Spinner";
import Alert from "react-bootstrap/Alert";
import { useReport } from "../../contexts/ReportContext";
import { SqlBlock } from "../Chat/Modals/AdditionalInformationModal";
import { TableView } from "../Chat/Modals/TableModal";
import { GraphView } from "../Chat/Modals/GraphModal";
import ReportPanelShell from "./ReportPanelShell";

// execution_result is stored either as a {full, llm} bundle or as plain rows
const getFullRows = (executionResult) => {
  if (!executionResult || typeof executionResult !== "object") return null;
  if (executionResult.full && Object.keys(executionResult.full).length > 0) return executionResult.full;
  if (executionResult.llm && Object.keys(executionResult.llm).length > 0) return executionResult.llm;
  if ("full" in executionResult || "llm" in executionResult) return null;
  return Object.keys(executionResult).length > 0 ? executionResult : null;
};

// Turns the stored deepquery_metadata into the list of data sources used by the analysis
export const extractDataSources = (metadata) => {
  const toolCalls = Array.isArray(metadata?.tool_calls) ? metadata.tool_calls : [];
  return toolCalls
    .map((toolCall, index) => {
      const output = toolCall?.output || {};
      const rows = getFullRows(output.execution_result);
      const graph =
        typeof output.raw_graph === "string" && output.raw_graph.startsWith("data:image")
          ? output.raw_graph
          : null;
      return {
        key: toolCall?.tool_id || `tool-${index}`,
        toolId: toolCall?.tool_id,
        toolName: toolCall?.tool_name,
        description: toolCall?.input?.action_description || toolCall?.input?.action || null,
        explanation: output.query_explanation || null,
        vql: output.sql_query || null,
        rows,
        rowCount: rows ? Object.keys(rows).length : 0,
        graph,
        failed: Boolean(toolCall?.error),
      };
    })
    .filter((source) => source.vql || source.rows || source.graph);
};

// Provider/model that produced the analysis, from the stored deepquery_metadata
export const extractModelLabel = (metadata) => {
  const join = (provider, model) => [provider, model].filter(Boolean).join("/");
  return (
    join(metadata?.actual_executing_provider, metadata?.actual_executing_model) ||
    join(metadata?.executing_provider, metadata?.executing_model) ||
    join(metadata?.llm_provider, metadata?.llm_model) ||
    null
  );
};

// Additional Information view. `detail` ({kind: 'table'|'graph', index}) is controlled by the manager so
// that Back / Esc step out of the drill-down before leaving the view.
const ReportExplorerPanel = ({ report, detail, onDetail, onBack, onBackToList }) => {
  const { fetchAnalysis } = useReport();
  const [state, setState] = useState({ loading: true, error: null, data: null });

  const reportId = report?.id;

  useEffect(() => {
    if (!reportId) return undefined;
    let cancelled = false;
    setState({ loading: true, error: null, data: null });
    fetchAnalysis(reportId)
      .then((data) => {
        if (!cancelled) setState({ loading: false, error: null, data });
      })
      .catch((error) => {
        if (cancelled) return;
        const message =
          error?.response?.data?.error || error?.message || "The analysis data could not be loaded.";
        setState({ loading: false, error: message, data: null });
      });
    return () => {
      cancelled = true;
    };
  }, [reportId, fetchAnalysis]);

  const sources = useMemo(() => extractDataSources(state.data?.deepquery_metadata), [state.data]);
  const modelLabel = useMemo(() => extractModelLabel(state.data?.deepquery_metadata), [state.data]);
  const title = state.data?.title || report?.title || report?.question || "DeepQuery analysis";

  const crumbs = [
    { label: "Reports", onClick: onBackToList },
    { label: title, onClick: detail ? () => onDetail(null) : undefined },
    { label: "Additional Information", onClick: detail ? () => onDetail(null) : undefined },
  ];
  const detailSource = detail ? sources[detail.index] : null;
  if (detailSource) {
    crumbs.push({
      label: `${detail.kind === "graph" ? "Graph" : "Table"} #${detail.index + 1}`,
    });
  }
  // The "Additional Information" crumb is the current one while no drill-down is open
  const shellCrumbs = crumbs.map((crumb, index) => ({
    ...crumb,
    onClick: index === 0 || detailSource ? crumb.onClick : undefined,
  }));

  return (
    <ReportPanelShell crumbs={shellCrumbs} onBack={onBack} scroll>
      {state.loading && (
        <div className="text-center py-5">
          <Spinner animation="border" size="sm" className="me-2" />
          Loading additional information...
        </div>
      )}

      {state.error && <Alert variant="warning">{state.error}</Alert>}

      {state.data && detailSource && (
        <div className="rcx-detail">
          <div className="rcx-detail-head">
            <span className="rcx-source-index">{detail.index + 1}</span>
            <span className="fw-semibold">{detailSource.toolName || "Query"}</span>
            {detail.kind === "table" && (
              <Badge bg="light" text="dark" className="border ms-2">
                {detailSource.rowCount} row{detailSource.rowCount === 1 ? "" : "s"}
              </Badge>
            )}
          </div>
          {detailSource.description && <div className="text-muted small mb-3">{detailSource.description}</div>}
          {detail.kind === "graph" ? (
            <GraphView graph={detailSource.graph} />
          ) : (
            <TableView executionResult={detailSource.rows} />
          )}
        </div>
      )}

      {state.data && !detailSource && (
        <>
          <div className="rcx-summary">
            <div className="fw-semibold">{title}</div>
            {state.data.question && <div className="text-muted small mt-1">{state.data.question}</div>}
            <div className="small mt-2">
              <Badge bg="secondary" className="me-2">
                {sources.length} data source{sources.length === 1 ? "" : "s"}
              </Badge>
              {report?.language && <Badge bg="light" text="dark" className="border me-2">{report.language}</Badge>}
            </div>
            {modelLabel && (
              <div className="small mt-2">
                <span className="text-muted">Model:</span> <code>{modelLabel}</code>
              </div>
            )}
          </div>

          {sources.length === 0 ? (
            <div className="text-center text-muted py-4">
              The analysis did not store any queries, tables or graphs.
            </div>
          ) : (
            sources.map((source, index) => (
              <div className="rcx-source" key={source.key}>
                <div className="d-flex align-items-center justify-content-between flex-wrap gap-2">
                  <div className="fw-semibold">
                    <span className="rcx-source-index">{index + 1}</span>
                    {source.toolName || "Query"}
                    {source.toolId && <code className="ms-2 small">{source.toolId}</code>}
                    {source.failed && <Badge bg="danger" className="ms-2">Failed</Badge>}
                  </div>
                  <div className="d-flex gap-2">
                    {source.rows && (
                      <button type="button" className="rcc-chip-btn" onClick={() => onDetail({ kind: "table", index })}>
                        <i className="bi bi-table me-1" />
                        Table ({source.rowCount} row{source.rowCount === 1 ? "" : "s"})
                      </button>
                    )}
                    {source.graph && (
                      <button type="button" className="rcc-chip-btn" onClick={() => onDetail({ kind: "graph", index })}>
                        <i className="bi bi-bar-chart-line me-1" />
                        Graph
                      </button>
                    )}
                  </div>
                </div>
                {source.description && <div className="text-muted small mt-1">{source.description}</div>}
                {source.explanation && <div className="small mt-2">{source.explanation}</div>}
                {source.vql && <SqlBlock sql={source.vql} />}
              </div>
            ))
          )}
        </>
      )}
    </ReportPanelShell>
  );
};

ReportExplorerPanel.propTypes = {
  report: PropTypes.shape({
    id: PropTypes.string,
    title: PropTypes.string,
    question: PropTypes.string,
    language: PropTypes.string,
  }).isRequired,
  detail: PropTypes.shape({ kind: PropTypes.string, index: PropTypes.number }),
  onDetail: PropTypes.func.isRequired,
  onBack: PropTypes.func.isRequired,
  onBackToList: PropTypes.func.isRequired,
};

export default ReportExplorerPanel;

import React from "react";
import PropTypes from "prop-types";

// Common layout of the in-place views of the DeepQuery Reports Manager:
// [← Back] [breadcrumb ................] [actions]
// followed by the scrollable content of the view.
const ReportPanelShell = ({ crumbs, onBack, actions, scroll, children }) => (
  <div className="rcp-panel">
    <div className="rcp-toolbar">
      <button type="button" className="rcp-back" onClick={onBack}>
        <i className="bi bi-arrow-left" />
        Back
      </button>
      <nav className="rcp-crumbs" aria-label="Breadcrumb">
        {crumbs.map((crumb, index) => {
          const isLast = index === crumbs.length - 1;
          return (
            <React.Fragment key={`${crumb.label}-${index}`}>
              {index > 0 && <i className="bi bi-chevron-right rcp-crumb-sep" />}
              {isLast || !crumb.onClick ? (
                <span className={`rcp-crumb${isLast ? " rcp-crumb-current" : ""}`} title={crumb.label}>
                  {crumb.label}
                </span>
              ) : (
                <button type="button" className="rcp-crumb rcp-crumb-link" onClick={crumb.onClick} title={crumb.label}>
                  {crumb.label}
                </button>
              )}
            </React.Fragment>
          );
        })}
      </nav>
      {actions && <div className="rcp-actions">{actions}</div>}
    </div>
    <div className={`rcp-content${scroll ? " rcp-content-scroll" : ""}`}>{children}</div>
  </div>
);

ReportPanelShell.propTypes = {
  crumbs: PropTypes.arrayOf(
    PropTypes.shape({ label: PropTypes.string.isRequired, onClick: PropTypes.func })
  ).isRequired,
  onBack: PropTypes.func.isRequired,
  actions: PropTypes.node,
  scroll: PropTypes.bool,
  children: PropTypes.node,
};

export default ReportPanelShell;

/* In-app report viewer (rendered inside the DeepQuery Reports Manager) */
.rcv-swatch {
  display: inline-block;
  width: 12px;
  height: 12px;
  margin-right: 0.5rem;
  border: 1px solid rgba(0, 0, 0, 0.25);
  border-radius: 50%;
  vertical-align: -1px;
}

.rcv-frame {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: #fff;
}

.rcv-center {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 1rem;
}

import React, { useCallback, useEffect, useRef, useState } from "react";
import PropTypes from "prop-types";
import Button from "react-bootstrap/Button";
import Dropdown from "react-bootstrap/Dropdown";
import Spinner from "react-bootstrap/Spinner";
import Alert from "react-bootstrap/Alert";
import { useReport } from "../../contexts/ReportContext";
import { downloadHtmlFile } from "../../utils/reportFiles";
import ReportPanelShell from "./ReportPanelShell";

// Themes defined by the generated report (html[data-theme="..."] CSS variable blocks)
export const REPORT_THEMES = [
  { id: "red", label: "Red", color: "#c53030" },
  { id: "blue", label: "Blue", color: "#3182ce" },
  { id: "green", label: "Green", color: "#38a169" },
  { id: "black", label: "Black", color: "#2d3748" },
  { id: "dark", label: "Dark", color: "#121826" },
  { id: "light", label: "Light", color: "#ffffff" },
];

const DEFAULT_THEME = "red";

// The app's Content-Security-Policy (style-src 'self') is inherited by the srcdoc iframe and blocks
// the report's inline <style> tags, which left reports unstyled. The CSS is taken out of the HTML
// and applied to the iframe through a constructable stylesheet, which the policy does not restrict.
const splitReportStyles = (html) => {
  const doc = new DOMParser().parseFromString(html, "text/html");
  const styles = Array.from(doc.querySelectorAll("style"));
  const css = styles.map((style) => style.textContent).join("\n");
  styles.forEach((style) => style.remove());
  return { css, frameHtml: `<!DOCTYPE html>\n${doc.documentElement.outerHTML}` };
};

const withTheme = (html, themeId) => {
  const doc = new DOMParser().parseFromString(html, "text/html");
  doc.documentElement.setAttribute("data-theme", themeId);
  return `<!DOCTYPE html>\n${doc.documentElement.outerHTML}`;
};

const ReportViewerPanel = ({ report, onBack, onBackToList }) => {
  const { fetchHtml } = useReport();
  const iframeRef = useRef(null);
  const themeRef = useRef(DEFAULT_THEME);
  const [state, setState] = useState({ loading: true, error: null, html: null, frameHtml: null, css: "", title: "" });
  const [theme, setTheme] = useState(DEFAULT_THEME);
  // The iframe stays hidden until styles and theme are applied, avoiding a flash of unstyled content
  const [frameReady, setFrameReady] = useState(false);

  const reportId = report?.id;

  useEffect(() => {
    if (!reportId) return undefined;
    let cancelled = false;
    setState({ loading: true, error: null, html: null, frameHtml: null, css: "", title: report?.title || "" });
    setTheme(DEFAULT_THEME);
    setFrameReady(false);
    themeRef.current = DEFAULT_THEME;
    fetchHtml(reportId)
      .then((data) => {
        if (!cancelled) {
          const { css, frameHtml } = splitReportStyles(data.html_report);
          setState({
            loading: false,
            error: null,
            html: data.html_report,
            frameHtml,
            css,
            title: data.title || report?.title || "",
          });
        }
      })
      .catch((error) => {
        if (cancelled) return;
        const message = error?.response?.data?.error || error?.message || "The report could not be loaded.";
        setState({ loading: false, error: message, html: null, frameHtml: null, css: "", title: report?.title || "" });
      });
    return () => {
      cancelled = true;
    };
  }, [reportId, fetchHtml]); // eslint-disable-line react-hooks/exhaustive-deps

  // Applying a theme only flips data-theme on the iframe's <html>: the report CSS reacts instantly
  const applyTheme = useCallback((themeId) => {
    const doc = iframeRef.current?.contentDocument;
    if (doc?.documentElement) doc.documentElement.setAttribute("data-theme", themeId);
  }, []);

  const handleThemeChange = (themeId) => {
    themeRef.current = themeId;
    setTheme(themeId);
    applyTheme(themeId);
  };

  // On (re)load keep the chosen theme; the first load adopts the theme the report was generated with
  const handleIframeLoad = () => {
    const doc = iframeRef.current?.contentDocument;
    if (!doc?.documentElement) {
      setFrameReady(true);
      return;
    }
    const FrameStyleSheet = doc.defaultView?.CSSStyleSheet;
    if (state.css && FrameStyleSheet) {
      try {
        const sheet = new FrameStyleSheet();
        sheet.replaceSync(state.css);
        doc.adoptedStyleSheets = [sheet];
      } catch (error) {
        console.debug("Could not apply the report styles:", error?.message);
      }
    }
    const generated = doc.documentElement.getAttribute("data-theme");
    if (generated && themeRef.current === DEFAULT_THEME && REPORT_THEMES.some((t) => t.id === generated)) {
      themeRef.current = generated;
      setTheme(generated);
    } else {
      applyTheme(themeRef.current);
    }
    setFrameReady(true);
  };

  // Download exactly what is on screen so the selected theme is baked into the file
  const handleDownload = () => {
    if (!state.html) return;
    downloadHtmlFile(withTheme(state.html, themeRef.current), state.title || report?.title, reportId);
  };

  const currentTheme = REPORT_THEMES.find((t) => t.id === theme) || REPORT_THEMES[0];
  const title = state.title || report?.title || report?.question || "Report";

  const actions = (
    <>
      <Dropdown align="end">
        <Dropdown.Toggle variant="light" size="sm" className="rcc-soft-btn" id="rcv-theme-dropdown" disabled={!state.html}>
          <span className="rcv-swatch" style={{ background: currentTheme.color }} />
          Theme: {currentTheme.label}
        </Dropdown.Toggle>
        <Dropdown.Menu popperConfig={{ strategy: "fixed" }} renderOnMount>
          {REPORT_THEMES.map((option) => (
            <Dropdown.Item key={option.id} active={option.id === theme} onClick={() => handleThemeChange(option.id)}>
              <span className="rcv-swatch" style={{ background: option.color }} />
              {option.label}
            </Dropdown.Item>
          ))}
        </Dropdown.Menu>
      </Dropdown>
      <Button variant="dark" size="sm" className="rcc-solid-btn" onClick={handleDownload} disabled={!state.html}>
        <i className="bi bi-download me-1" />
        Download HTML
      </Button>
    </>
  );

  return (
    <ReportPanelShell
      crumbs={[{ label: "Reports", onClick: onBackToList }, { label: title }]}
      onBack={onBack}
      actions={actions}
    >
      {state.loading && (
        <div className="rcv-center">
          <Spinner animation="border" size="sm" className="me-2" />
          Loading report...
        </div>
      )}
      {state.error && (
        <div className="rcv-center">
          <Alert variant="warning" className="mb-0">{state.error}</Alert>
        </div>
      )}
      {state.frameHtml && (
        <iframe
          ref={iframeRef}
          title={title}
          className="rcv-frame"
          // No scripts: LLM generated HTML must never execute. allow-same-origin lets us switch the theme.
          sandbox="allow-same-origin"
          srcDoc={state.frameHtml}
          style={{ visibility: frameReady ? "visible" : "hidden" }}
          onLoad={handleIframeLoad}
        />
      )}
    </ReportPanelShell>
  );
};

ReportViewerPanel.propTypes = {
  report: PropTypes.shape({
    id: PropTypes.string,
    title: PropTypes.string,
    question: PropTypes.string,
  }).isRequired,
  onBack: PropTypes.func.isRequired,
  onBackToList: PropTypes.func.isRequired,
};

export default ReportViewerPanel;

/* DeepQuery Reports Manager (shared modal rules live in Common/Modal/Modal.css) */

/* ---------- List view ---------- */
.rcc-list-view {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.rcc-list-scroll {
  flex: 1;
  min-height: 0;
  padding: 0.75rem 1.25rem 1.25rem;
  overflow-y: auto;
}

.rcc-flat-list {
  display: flex;
  flex-direction: column;
}

/* ---------- Rows ---------- */
.rcc-row {
  padding: 0.85rem 0.6rem;
  background-color: #ffffff;
  border-radius: 0;
  border-bottom: 1px solid #e5e7eb;
  transition: border-color 0.15s;
}

.rcc-row:last-child {
  border-bottom-color: transparent;
}

.rcc-row-main {
  display: flex;
  align-items: center;
  gap: 0.9rem;
}

.rcc-dot {
  flex: 0 0 auto;
  width: 10px;
  height: 10px;
  background: #9ca3af;
  border-radius: 50%;
}

.rcc-st-completed .rcc-dot { background: #10b981; }
.rcc-st-failed .rcc-dot { background: #ef4444; }
.rcc-st-pending .rcc-dot { background: #f59e0b; }
.rcc-st-processing .rcc-dot { background: #3b82f6; animation: rcc-pulse 1.4s ease-in-out infinite; }

.rcc-row-text {
  flex: 1 1 auto;
  min-width: 0;
}

.rcc-row-title {
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.3;
  color: #111827;
  cursor: default;
}

.rcc-row-sub {
  margin-top: 0.15rem;
  font-size: 0.8rem;
  color: #6b7280;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rcc-row-meta {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.rcc-lang {
  display: inline-flex;
  align-items: center;
  padding: 0.15rem 0.55rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: #374151;
  background: #f3f4f6;
  border-radius: 6px;
  white-space: nowrap;
  width: 90px;
  flex-shrink: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rcc-status-wrapper {
  width: 90px;
  flex-shrink: 0;
  display: flex;
  justify-content: flex-start;
}

.rcc-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 5.5rem;
  padding: 0.15rem 0.6rem;
  font-size: 0.72rem;
  font-weight: 600;
  border-radius: 999px;
  white-space: nowrap;
}

.rcc-status.rcc-st-completed { color: #047857; background: #d1fae5; }
.rcc-status.rcc-st-failed { color: #b91c1c; background: #fee2e2; }
.rcc-status.rcc-st-pending { color: #b45309; background: #fef3c7; }
.rcc-status.rcc-st-processing { color: #1d4ed8; background: #dbeafe; }
.rcc-status.rcc-st-cancelled { color: #4b5563; background: #e5e7eb; }

.rcc-time {
  width: 75px;
  flex-shrink: 0;
  font-size: 0.75rem;
  color: #9ca3af;
  text-align: right;
  white-space: nowrap;
}

.rcc-row-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 2px;
  width: 200px;
  flex-shrink: 0;
}

/* Running rows: shimmering progress bar + stage label */
.rcc-progress {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.rcc-progress-bar {
  position: relative;
  flex: 0 1 220px;
  width: 220px;
  height: 5px;
  overflow: hidden;
  background: #e5e7eb;
  border-radius: 999px;
}

.rcc-progress-bar::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, #3b82f6, #8b5cf6, transparent);
  transform: translateX(-100%);
  animation: rcc-shimmer 1.4s ease-in-out infinite;
}

.rcc-stage {
  font-size: 0.78rem;
  color: #6b7280;
}

.rcc-error {
  margin-top: 0.4rem;
  padding: 0.4rem 0.6rem;
  font-size: 0.8rem;
  color: #b91c1c;
  background: #fef2f2;
  border-radius: 8px;
  word-break: break-word;
}

/* ---------- Buttons ---------- */
.rcc-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  font-size: 1rem;
  color: #4b5563;
  background: transparent;
  border: 0;
  border-radius: 8px;
  transition: background 0.15s, color 0.15s;
}

.rcc-icon-btn:hover:not(:disabled),
.rcc-icon-btn.is-active {
  color: #111827;
  background: #e5e7eb;
}

.rcc-icon-btn-accent:hover:not(:disabled) { color: #1d4ed8; background: #dbeafe; }
.rcc-icon-btn-danger:hover:not(:disabled) { color: #b91c1c; background: #fee2e2; }

.rcc-icon-btn:focus-visible,
.rcc-ghost-btn:focus-visible,
.rcc-filter:focus-visible,
.rcc-primary-btn:focus-visible,
.rcc-chip:focus-visible,
.rcc-chip-btn:focus-visible,
.rcp-back:focus-visible,
.rcp-crumb-link:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.rcc-icon-btn:disabled {
  opacity: 0.4;
}

.rcc-ghost-btn,
.rcc-primary-btn,
.rcc-soft-btn,
.rcc-solid-btn {
  height: 32px;
  padding: 0 0.85rem;
  font-size: 0.82rem;
  font-weight: 500;
  border-radius: 8px;
}

.rcc-ghost-btn {
  color: #ffffff;
  background: #006699;
  border: 1px solid #006699;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}

.rcc-ghost-btn:hover:not(:disabled) {
  color: #ffffff;
  background: #005580;
  border-color: #005580;
}

.rcc-ghost-danger {
  color: #ffffff;
  background: #2d3f4b;
  border: 1px solid #2d3f4b;
}

.rcc-ghost-danger:hover:not(:disabled) {
  color: #ffffff;
  background: #1a2b34;
  border-color: #1a2b34;
}

.rcc-primary-btn {
  color: #ffffff;
  background: #2d3f4b;
  border: 1px solid #2d3f4b;
  transition: background 0.15s, border-color 0.15s;
}

.rcc-primary-btn:hover:not(:disabled) {
  background: #1a2b34;
  border-color: #1a2b34;
}

.rcc-primary-btn:disabled {
  opacity: 0.5;
}

.rcc-soft-btn.btn {
  color: #1f2937;
  background: #f1f3f5;
  border: 0;
  display: inline-flex;
  align-items: center;
}

.rcc-soft-btn.btn:hover,
.rcc-soft-btn.btn.show {
  background: #e5e7eb;
}

.rcc-solid-btn.btn {
  display: inline-flex;
  align-items: center;
  border: 0;
}

.rcc-chip,
.rcc-chip-btn {
  padding: 0.15rem 0.65rem;
  font-size: 0.78rem;
  color: #374151;
  background: #f3f4f6;
  border: 0;
  border-radius: 999px;
  transition: background 0.15s;
}

.rcc-chip:hover,
.rcc-chip-btn:hover {
  background: #e5e7eb;
}

.rcc-chip-btn {
  padding: 0.3rem 0.8rem;
  font-weight: 500;
}

/* ---------- Inline variant form ---------- */
.rcc-variant-form {
  margin: 0.6rem 0 0.2rem 1.4rem;
  padding: 0.75rem 0.9rem;
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}

.rcc-variant-label {
  margin-bottom: 0.5rem;
  font-size: 0.82rem;
  font-weight: 600;
  color: #374151;
}

.rcc-variant-label .text-muted {
  font-weight: 400;
}

.rcc-variant-controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.rcc-language-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

/* Full-title popover: width-limited and scrollable */
.rcc-title-popover {
  max-width: 420px;
}

.rcc-title-popover .popover-body {
  max-height: 40vh;
  overflow-y: auto;
  font-size: 0.85rem;
  text-align: left;
  white-space: pre-wrap;
  word-break: break-word;
}

/* ---------- Empty state ---------- */
.rcc-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
  padding: 3rem 1rem;
  text-align: center;
}

.rcc-empty i {
  margin-bottom: 0.75rem;
  font-size: 2.5rem;
  color: #d1d5db;
}

.rcc-empty-small {
  padding: 2rem 1rem;
}

/* ---------- In-place panels (explorer / viewer) ---------- */
.rcp-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.rcp-toolbar {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  padding: 0.6rem 1.25rem;
  background: #fff;
  border-bottom: 1px solid #eef1f4;
}

.rcp-back {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  height: 32px;
  padding: 0 0.8rem;
  font-size: 0.85rem;
  font-weight: 500;
  color: #1f2937;
  background: #f1f3f5;
  border: 0;
  border-radius: 8px;
  transition: background 0.15s;
}

.rcp-back:hover {
  background: #e5e7eb;
}

.rcp-crumbs {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
  font-size: 0.85rem;
  overflow: hidden;
}

.rcp-crumb {
  max-width: 320px;
  padding: 0;
  color: #6b7280;
  background: none;
  border: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rcp-crumb-link:hover {
  color: #111827;
  text-decoration: underline;
}

.rcp-crumb-current {
  font-weight: 600;
  color: #111827;
}

.rcp-crumb-sep {
  flex: 0 0 auto;
  font-size: 0.65rem;
  color: #9ca3af;
}

.rcp-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.rcp-content {
  position: relative;
  flex: 1;
  min-height: 0;
  background: #fff;
}

.rcp-content-scroll {
  padding: 1.25rem;
  overflow-y: auto;
}

/* ---------- Explorer ---------- */
.rcx-summary {
  margin-bottom: 1rem;
  padding: 0.9rem 1rem;
  background: #f8fafc;
  border-radius: 10px;
}

.rcx-source {
  margin-bottom: 1rem;
  padding: 0.9rem 1rem;
  border: 1px solid #eef1f4;
  border-radius: 10px;
}

.rcx-source-index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  margin-right: 0.5rem;
  font-size: 0.72rem;
  font-weight: 700;
  color: #fff;
  background: #1f2937;
  border-radius: 50%;
}

.rcx-detail-head {
  display: flex;
  align-items: center;
  margin-bottom: 0.5rem;
}

/* ---------- Animations ---------- */
@keyframes rcc-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.85); }
}

@keyframes rcc-shimmer {
  to { transform: translateX(100%); }
}

@media (max-width: 991px) {
  .rcc-row-main {
    flex-wrap: wrap;
  }

  .rcc-row-meta {
    order: 3;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rcc-live-dot,
  .rcc-st-processing .rcc-dot,
  .rcc-progress-bar::after {
    animation: none;
  }

  .rcc-progress-bar::after {
    transform: none;
    background: #3b82f6;
    opacity: 0.6;
  }
}

import React, { useMemo, useRef, useState } from "react";
import { BaseModal, ConfirmationModal } from "../Common/Modal";
import Overlay from "react-bootstrap/Overlay";
import Popover from "react-bootstrap/Popover";
import OverlayTrigger from "react-bootstrap/OverlayTrigger";
import Tooltip from "react-bootstrap/Tooltip";
import { useReport, REPORT_STATUS, isActiveStatus } from "../../contexts/ReportContext";
import { downloadHtmlFile } from "../../utils/reportFiles";
import ReportExplorerPanel from "./ReportExplorerPanel";
import ReportViewerPanel from "./ReportViewerPanel";
import "./ReportsManagerModal.css";
import "./ReportViewerModal.css";

const assetBaseUrl = import.meta.env.BASE_URL;

const STATUS_META = {
  [REPORT_STATUS.PENDING]: { label: "Pending", className: "rcc-st-pending" },
  [REPORT_STATUS.PROCESSING]: { label: "Processing", className: "rcc-st-processing" },
  [REPORT_STATUS.COMPLETED]: { label: "Completed", className: "rcc-st-completed" },
  [REPORT_STATUS.FAILED]: { label: "Failed", className: "rcc-st-failed" },
  [REPORT_STATUS.CANCELLED]: { label: "Cancelled", className: "rcc-st-cancelled" },
};

const STAGE_LABELS = {
  queued: "Waiting in queue",
  extracting_data: "Extracting data",
  generating_html: "Generating HTML",
};

const FILTERS = [
  { id: "all", label: "All", match: () => true },
  { id: "running", label: "Running", match: (report) => isActiveStatus(report.status) },
  { id: "completed", label: "Completed", match: (report) => report.status === REPORT_STATUS.COMPLETED },
  {
    id: "failed",
    label: "Failed",
    match: (report) => report.status === REPORT_STATUS.FAILED || report.status === REPORT_STATUS.CANCELLED,
  },
];

const SUGGESTED_LANGUAGES = ["English", "Spanish", "French", "German", "Italian", "Portuguese"];
const LANGUAGE_PATTERN = /^[a-zA-Z\u00C0-\u024F\s-]*$/;
const LIST_VIEW = { type: "list" };

// Every floating element is mounted on <body> with a fixed strategy so that the
// modal body (overflow) never clips it and it always stays above the modal.
const OVERLAY_PROPS = { container: () => document.body, popperConfig: { strategy: "fixed" } };

const formatRelative = (iso) => {
  if (!iso) return "-";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "-";
  const seconds = Math.max(0, Math.round((Date.now() - date.getTime()) / 1000));
  if (seconds < 45) return "just now";
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes} min ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours} h ago`;
  return date.toLocaleString(undefined, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "numeric",
    minute: "2-digit",
  });
};

const formatExact = (iso) => (iso ? new Date(iso).toLocaleString() : "");

const IconAction = ({ tooltip, onClick, disabled, tone = "", active = false, children }) => (
  <OverlayTrigger placement="top" overlay={<Tooltip id={`rcc-tip-${tooltip}`}>{tooltip}</Tooltip>} {...OVERLAY_PROPS}>
    <button
      type="button"
      className={`rcc-icon-btn ${tone ? `rcc-icon-btn-${tone}` : ""} ${active ? "is-active" : ""}`}
      onClick={onClick}
      disabled={disabled}
      aria-label={tooltip}
    >
      {children}
    </button>
  </OverlayTrigger>
);

const HoverTitle = ({ text }) => {
  const [show, setShow] = useState(false);
  const targetRef = useRef(null);
  const timerRef = useRef(null);

  const open = () => {
    clearTimeout(timerRef.current);
    setShow(true);
  };
  const close = () => {
    clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setShow(false), 150);
  };

  return (
    <>
      <div ref={targetRef} className="rcc-row-title" onMouseEnter={open} onMouseLeave={close}>
        {text}
      </div>
      <Overlay target={targetRef.current} show={show} placement="bottom-start" {...OVERLAY_PROPS}>
        <Popover id="rcc-title-popover" className="rcc-title-popover" onMouseEnter={open} onMouseLeave={close}>
          <Popover.Body>{text}</Popover.Body>
        </Popover>
      </Overlay>
    </>
  );
};

const VariantForm = ({ onCreate, onClose }) => {
  const [language, setLanguage] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const trimmed = language.trim();

  const submit = async (event) => {
    event.preventDefault();
    if (!trimmed || submitting) return;
    setSubmitting(true);
    const created = await onCreate(trimmed);
    setSubmitting(false);
    if (created) onClose();
  };

  return (
    <form className="rcc-variant-form" onSubmit={submit}>
      <div className="rcc-variant-label">
        <i className="bi bi-translate me-1" />
        New variant in another language
        <span className="text-muted ms-2">Reuses the extracted data, so it only takes the report generation time.</span>
      </div>
      <div className="rcc-variant-controls">
        <input
          type="text"
          className="rcc-input"
          autoFocus
          placeholder="e.g. French"
          value={language}
          maxLength={30}
          onChange={(e) => {
            if (LANGUAGE_PATTERN.test(e.target.value)) setLanguage(e.target.value);
          }}
        />
        <button type="submit" className="rcc-primary-btn" disabled={!trimmed || submitting}>
          {submitting ? "Creating..." : "Create"}
        </button>
        <button type="button" className="rcc-ghost-btn" onClick={onClose}>
          Cancel
        </button>
      </div>
      <div className="rcc-language-chips">
        {SUGGESTED_LANGUAGES.map((option) => (
          <button type="button" key={option} className="rcc-chip" onClick={() => setLanguage(option)}>
            {option}
          </button>
        ))}
      </div>
    </form>
  );
};

const ReportRow = ({ report, actions }) => {
  const [variantOpen, setVariantOpen] = useState(false);
  const meta = STATUS_META[report.status] || { label: report.status, className: "rcc-st-cancelled" };
  const active = isActiveStatus(report.status);
  const completed = report.status === REPORT_STATUS.COMPLETED;
  const retryable = report.status === REPORT_STATUS.FAILED || report.status === REPORT_STATUS.CANCELLED;
  const hasAnalysisData =
    completed || (report.status === REPORT_STATUS.PROCESSING && report.stage === "generating_html");
  const displayTitle = report.title || report.question || "Untitled report";
  const showQuestion = report.title && report.question && report.title !== report.question;

  return (
    <div className={`rcc-row ${meta.className}`}>
      <div className="rcc-row-main">
        <span className="rcc-dot" aria-hidden="true" />
        <div className="rcc-row-text">
          <HoverTitle text={displayTitle} />
          {showQuestion && <div className="rcc-row-sub">{report.question}</div>}

          {active && (
            <div className="rcc-progress" aria-live="polite">
              <div className="rcc-progress-bar" />
              <span className="rcc-stage">{STAGE_LABELS[report.stage] || "Working"}</span>
            </div>
          )}
          {report.status === REPORT_STATUS.FAILED && (
            <div className="rcc-error" role="alert">
              <i className="bi bi-exclamation-triangle-fill me-1" />
              {report.error || "The report could not be generated."}
            </div>
          )}
        </div>

        <div className="rcc-row-meta">
          <span className="rcc-lang" title="Report language">
            <i className="bi bi-translate me-1" />
            {report.language}
          </span>
          <div className="rcc-status-wrapper">
            <span className={`rcc-status ${meta.className}`}>{meta.label}</span>
          </div>
          <span className="rcc-time" title={formatExact(report.completedAt || report.createdAt)}>
            {formatRelative(report.completedAt && !active ? report.completedAt : report.createdAt)}
          </span>
        </div>

        <div className="rcc-row-actions">
          {active && (
            <IconAction tooltip="Cancel" tone="danger" onClick={() => actions.onCancel(report)}>
              <i className="bi bi-stop-circle" />
            </IconAction>
          )}
          {retryable && (
            <IconAction tooltip="Retry" tone="accent" onClick={() => actions.onRetry(report)}>
              <i className="bi bi-arrow-clockwise" />
            </IconAction>
          )}
          {completed && (
            <IconAction tooltip="View report" tone="accent" onClick={() => actions.onView(report)}>
              <i className="bi bi-eye" />
            </IconAction>
          )}
          {completed && (
            <IconAction tooltip="New variant (another language)" active={variantOpen} onClick={() => setVariantOpen((prev) => !prev)}>
              <i className="bi bi-plus-circle" />
            </IconAction>
          )}
          {hasAnalysisData && (
            <IconAction tooltip="Additional information (model, VQL, tables, graphs)" onClick={() => actions.onExplore(report)}>
              <img src={`${assetBaseUrl}tools/deep_query/denodo_icon_black.svg`} alt="" width="16" height="16" />
            </IconAction>
          )}
          {completed && (
            <IconAction tooltip="Download HTML" onClick={() => actions.onDownload(report)}>
              <i className="bi bi-download" />
            </IconAction>
          )}
          <IconAction tooltip={active ? "Cancel and delete" : "Delete"} tone="danger" onClick={() => actions.onDelete(report)}>
            <i className="bi bi-trash" />
          </IconAction>
        </div>
      </div>

      {variantOpen && (
        <VariantForm
          onCreate={(language) => actions.onVariant(report, language)}
          onClose={() => setVariantOpen(false)}
        />
      )}
    </div>
  );
};

const ReportsManagerModal = () => {
  const {
    reports,
    reportLimit,
    activeCount,
    isModalOpen,
    setIsModalOpen,
    cancelReport,
    createVariant,
    retryReport,
    deleteReport,
    clearAllReports,
    fetchHtml,
    showToast,
  } = useReport();

  const [view, setView] = useState(LIST_VIEW);
  const [filter, setFilter] = useState("all");
  const [search, setSearch] = useState("");
  const [confirmDelete, setConfirmDelete] = useState({ show: false, type: null, report: null });

  const handleClose = () => setIsModalOpen(false);

  const remainingSlots = Math.max(0, reportLimit - reports.length);
  const quotaTone = remainingSlots === 0 ? "is-full" : remainingSlots <= 3 ? "is-warn" : "";
  const quotaTitle = remainingSlots === 0
    ? `Report limit reached (${reportLimit}). Delete some reports to create new ones.`
    : `You can store up to ${reportLimit} reports (${remainingSlots} left).`;

  const goBack = () => {
    if (view.type === "explore" && view.detail) setView({ ...view, detail: null });
    else setView(LIST_VIEW);
  };
  const handleHide = () => (view.type === "list" ? handleClose() : goBack());

  const handleDownload = async (report) => {
    try {
      const { html_report: html, title } = await fetchHtml(report.id);
      downloadHtmlFile(html, title || report.title, report.id);
    } catch (error) {
      showToast("Download failed", error?.response?.data?.error || error?.message || "The report could not be downloaded.", "danger");
    }
  };

  const executeDelete = () => {
    if (confirmDelete.type === "single" && confirmDelete.report) {
      deleteReport(confirmDelete.report.id);
    } else if (confirmDelete.type === "all") {
      clearAllReports();
    }
    setConfirmDelete((prev) => ({ ...prev, show: false }));
  };

  const actions = {
    onView: (report) => setView({ type: "viewer", report }),
    onExplore: (report) => setView({ type: "explore", report, detail: null }),
    onDownload: handleDownload,
    onCancel: (report) => cancelReport(report.id),
    onRetry: (report) => retryReport(report.id),
    onDelete: (report) => setConfirmDelete({ show: true, type: "single", report }),
    onVariant: (report, language) => createVariant(report.id, language),
  };

  const counts = useMemo(() => {
    const result = {};
    FILTERS.forEach((option) => {
      result[option.id] = reports.filter(option.match).length;
    });
    return result;
  }, [reports]);

  const filteredReports = useMemo(() => {
    const activeFilter = FILTERS.find((option) => option.id === filter) || FILTERS[0];
    const needle = search.trim().toLowerCase();

    return reports.filter((report) => {
      if (!activeFilter.match(report)) return false;
      if (needle && !`${report.title} ${report.question} ${report.language}`.toLowerCase().includes(needle)) return false;
      return true;
    });
  }, [reports, filter, search]);

  const renderList = () => (
    <div className="rcc-list-view">
      {reports.length === 0 ? (
        <div className="rcc-empty">
          <i className="bi bi-inbox" />
          <p className="mb-1 fw-semibold">No reports yet</p>
          <p className="text-muted mb-0">
            Ask the chatbot for a DeepQuery analysis and it will appear here while it runs in the background.
          </p>
        </div>
      ) : (
        <>
          <div className="rcc-tabs-bar">
            <ul className="nav nav-tabs rcc-report-tabs" role="tablist" aria-label="Filter reports">
              {FILTERS.map((option) => (
                <li className="nav-item" role="presentation" key={option.id}>
                  <button
                    type="button"
                    role="tab"
                    aria-selected={filter === option.id}
                    className={`nav-link rcc-tab-link ${filter === option.id ? "active" : ""}`}
                    onClick={() => setFilter(option.id)}
                  >
                    {option.label}
                    <span className="rcc-filter-count">{counts[option.id]}</span>
                  </button>
                </li>
              ))}
            </ul>
            <div className="rcc-toolbar-right">
              <div className="rcc-search">
                <i className="bi bi-search" />
                <input
                  type="search"
                  placeholder="Search reports"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  aria-label="Search reports"
                />
              </div>
              <button 
                type="button" 
                className="rcc-ghost-btn rcc-ghost-danger" 
                onClick={() => setConfirmDelete({ show: true, type: "all", report: null })}
              >
                <i className="bi bi-trash me-1" />
                Clear all
              </button>
            </div>
          </div>

          <div className="rcc-list-scroll">
            {filteredReports.length === 0 ? (
              <div className="rcc-empty rcc-empty-small">
                <p className="text-muted mb-0">No reports match the current filter.</p>
              </div>
            ) : (
              <div className="rcc-flat-list">
                {filteredReports.map((report) => (
                  <ReportRow key={report.id} report={report} actions={actions} />
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );

  return (
    <>
      <BaseModal
        show={isModalOpen}
        onHide={handleHide}
        onExited={() => setView(LIST_VIEW)}
        title="DeepQuery Reports Manager"
        headerBadges={
          <>
            <span className={`rcc-quota ${quotaTone}`} title={quotaTitle}>
              {reports.length} / {reportLimit} reports
            </span>
            {activeCount > 0 && (
              <span className="rcc-live" title="Reports are being generated in the background">
                <span className="rcc-live-dot" />
                {activeCount} running
              </span>
            )}
          </>
        }
        size="xl"
        fixedHeight
        backdrop="static"
      >
          {view.type === "list" && renderList()}
          {view.type === "explore" && (
            <ReportExplorerPanel
              report={view.report}
              detail={view.detail}
              onDetail={(detail) => setView({ ...view, detail })}
              onBack={goBack}
              onBackToList={() => setView(LIST_VIEW)}
            />
          )}
          {view.type === "viewer" && (
            <ReportViewerPanel report={view.report} onBack={goBack} onBackToList={() => setView(LIST_VIEW)} />
          )}
      </BaseModal>

      <ConfirmationModal
        show={confirmDelete.show}
        onHide={() => setConfirmDelete((prev) => ({ ...prev, show: false }))}
        onConfirm={executeDelete}
        nested
        title={confirmDelete.type === 'all' ? 'Clear All Reports' : 'Delete Report'}
        message={
          confirmDelete.type === 'all'
            ? "Are you sure you want to permanently delete ALL reports? This action cannot be undone."
            : "Are you sure you want to permanently delete this report? This action cannot be undone."
        }
        confirmLabel="Yes, delete"
      />
    </>
  );
};

export default ReportsManagerModal;

import React from "react";
import { ConfirmationModal } from "../Common/Modal";

const DeleteChatModal = ({ show, onHide, onConfirm }) => (
  <ConfirmationModal
    show={show}
    onHide={onHide}
    onConfirm={onConfirm}
    title="Delete conversation"
    message={
      <>
        Are you sure you want to delete this chat? This action is{" "}
        <strong>irreversible</strong>.
      </>
    }
    confirmLabel="Yes, delete"
  />
);

export default DeleteChatModal;

import React from "react";
import { Form } from "react-bootstrap";
import { BaseModal } from "../Common/Modal";

const RenameChatModal = ({
  show,
  onHide,
  newChatName,
  setNewChatName,
  onConfirm,
}) => (
  <BaseModal
    show={show}
    onHide={onHide}
    title="Rename Chat"
    size="sm"
    scrollableBody
    footer={
      <>
        <button type="button" className="rcc-ghost-btn" onClick={onHide}>
          Cancel
        </button>
        <button type="button" className="rcc-primary-btn" onClick={onConfirm}>
          Save
        </button>
      </>
    }
  >
    <Form.Group>
      <Form.Label className="small fw-semibold">Chat Title</Form.Label>
      <Form.Control
        type="text"
        value={newChatName}
        onChange={(e) => setNewChatName(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") onConfirm();
        }}
        autoFocus
      />
    </Form.Group>
  </BaseModal>
);

export default RenameChatModal;

.sidebar-container {
  height: 100vh;
  flex-shrink: 0;
  transition: width 0.3s ease-in-out;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-size: 0.95rem;
  position: relative;
  z-index: 1020;
}

.sidebar-container.closed {
  width: 0px;
}

.sidebar-container.open {
  width: 260px;
}

/* Header Styles */
.sidebar-header {
  height: 76px;
  min-height: 76px;
  background-color: #143142;
  border-right: 2px solid #143b5c;
  position: relative;
  z-index: 9999;
}

.sidebar-header-logo {
  height: 30px;
  object-fit: contain;
}

.sidebar-close-btn {
  font-size: 1.5rem;
  cursor: pointer;
  transition: opacity 0.2s;
  color: white;
}

.sidebar-close-btn:hover {
  opacity: 0.7;
}

/* Content Area */
.sidebar-content {
  background-color: #ffffff; 
  border-right: 2px solid #e1e5e8;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: #c1c1c1 transparent;
}

.sidebar-content::-webkit-scrollbar {
  width: 6px;
}
.sidebar-content::-webkit-scrollbar-track {
  background: transparent;
}
.sidebar-content::-webkit-scrollbar-thumb {
  background-color: #e5e5e5;
  border-radius: 10px;
}
.sidebar-content::-webkit-scrollbar-thumb:hover {
  background-color: #c1c1c1;
}

/* Generic Icon Container */
.sidebar-icon-container {
  width: 32px;
  display: flex;
  justify-content: center;
  align-items: center;
  margin-right: 0.75rem;
  flex-shrink: 0;
}

/* Sidebar Items */
.sidebar-item {
  transition: background-color 0.2s ease, color 0.2s ease !important;
  color: #112533 !important;
  background-color: transparent !important;
  border-radius: 6px !important;
  margin: 2px 10px !important;
  width: auto !important;
  position: relative;
  min-width: 0;
}

.sidebar-item:hover {
  background-color: #f1f3f5 !important;
  color: #000000 !important;
  text-decoration: none;
}

.sidebar-item.active {
  background-color: #e9ecef !important;
  font-weight: 600 !important;
  color: #112533 !important;
  border: none !important;
}

.sidebar-item-text {
  flex-grow: 1;
  text-align: left;
  font-size: 0.95rem;
}

/* New Chat Style (Flat and minimalist) */
.new-chat-icon {
  font-size: 1.15rem;
  color: #006699;
}

/* Agent Icons */
.agent-icon {
  width: 30px;
  height: 30px;
  object-fit: contain;
}

.agent-icon-fallback {
  font-size: 1.4rem;
}

/* Section Headers */
.sidebar-section-header {
  font-size: 0.85rem; 
  font-weight: 650;
  color: #006699;
  text-align: left; 
  display: flex;
  justify-content: space-between; 
  align-items: center;
  position: relative; 
  margin-top: 0.5rem; 
  margin-bottom: 0.5rem;
  user-select: none;
  cursor: pointer;
  transition: color 0.2s ease;
}

.sidebar-section-header:hover {
  color: #143142;
}

.sidebar-divider {
  height: 1.5px;
  min-height: 1.5px;
  background-color: #e4e9ee;
}

/* Upload & Info Icons wrapper */
.upload-icon-wrapper,
.info-icon-wrapper {
  display: flex;
  align-items: center;
  cursor: pointer;
}

.upload-icon,
.info-icon {
  font-size: 1rem; 
  color: #006699;
  transition: color 0.2s ease;
}

.upload-icon:hover,
.info-icon:hover {
  color: #143142;
}

/* Search Box */
.sidebar-search-wrapper {
  margin: 1.25rem 10px; 
}

.sidebar-search-container {
  padding: 8px 10px; 
  border-color: #ced4da;
  background-color: transparent !important; 
}

.sidebar-search-container input {
  font-size: inherit !important;
}

.search-clear-icon {
  font-size: 0.85rem;
}

/* Empty State / Loading State */
.sidebar-status-message {
  font-size: 0.85rem;
}

.sidebar-empty-state {
  font-style: italic;
  margin-top: 10px;
}

/* --- CHAT & AGENT ITEM ACTIONS --- */
.sidebar-item-actions {
  position: absolute;
  right: 10px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* By default, the 3-dots menu wrapper is hidden */
.sidebar-dots-menu {
  display: none;
}

/* The pin icon is visible by default (if the chat is pinned) */
.sidebar-pin-icon {
  display: block;
  font-size: 0.9rem;
  color: #006699;
}

/* When hovering over the item, hide the pin and show the dots */
.sidebar-item:hover .sidebar-pin-icon {
  display: none;
}

.sidebar-item:hover .sidebar-dots-menu {
  display: flex;
}

/* Also show the dots if the dropdown is currently open (active) */
.sidebar-item.dropdown-open .sidebar-dots-menu {
  display: flex;
}
.sidebar-item.dropdown-open .sidebar-pin-icon {
  display: none;
}

/* Custom Dropdown Toggle (to remove caret) */
.dropdown-toggle-custom {
  cursor: pointer;
  padding: 4px;
}

.dropdown-dots-icon {
  font-size: 1rem;
}

/* Custom Dropdown Menu */
.sidebar-dropdown-menu {
  font-size: 0.9rem;
  min-width: 150px;
  border-color: #dcdfe3;
  border-radius: 8px;
  z-index: 1030;
  color: #006699;
}

/* Load More Button */
.sidebar-load-more {
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.3px;
  color: #6c757d;
  transition: color 0.2s;
}

.sidebar-load-more:hover {
  color: #143142;
}

/* --- Dropdown Menu Icons --- */
.sidebar-dropdown-menu .dropdown-item i {
  color: #006699;
}

.sidebar-dropdown-menu .dropdown-item:not(.text-danger):hover i {
  color: #143142; 
}

.sidebar-dropdown-menu .dropdown-item.text-danger i {
  color: #dc3545;
}

import React, { useRef, useState, useEffect } from "react";
import CustomTooltip from "../CustomTooltip/CustomTooltip";
import Dropdown from "react-bootstrap/Dropdown";
import Spinner from "react-bootstrap/Spinner";
import "./Sidebar.css";

const assetBaseUrl = import.meta.env.BASE_URL;

const Sidebar = ({
  isOpen,
  toggleSidebar,
  chatbots,
  selectedChatbot,
  onSelectChatbot,
  showDenodoSidebarHeaderIcon = true,
  onNewChat,
  chatHistoryList = [],
  currentThreadId,
  onLoadOldChat,
  onDeleteChat,
  onRenameChat,
  onExportChat,
  onImportChat,
  onLoadMoreChats,
  hasMoreChats,
  isLoadingList,
  isLoadingHistory,
  onPinChat,
  searchQuery,
  onSearchChange,
  onOpenSettings,
}) => {
  const specializedBots = chatbots.filter((bot) => !bot.isGlobal);
  const fileInputRef = useRef(null);

  const [openDropdownId, setOpenDropdownId] = useState(null);
  const [isAgentsCollapsed, setIsAgentsCollapsed] = useState(false);
  const [isChatsCollapsed, setIsChatsCollapsed] = useState(false);

  useEffect(() => {
    const handleClickOutside = () => setOpenDropdownId(null);
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      onImportChat(e.target.files[0]);
      e.target.value = null;
    }
  };

  return (
    <div className={`sidebar-container ${isOpen ? "open" : "closed"}`}>
      <div
        className={`sidebar-header d-flex align-items-center px-3 ${
          showDenodoSidebarHeaderIcon
            ? "justify-content-between"
            : "justify-content-end"
        }`}
      >
        {showDenodoSidebarHeaderIcon && (
          <img
            src={`${assetBaseUrl}denodo_icon_white.svg`}
            alt="Denodo Logo"
            className="sidebar-header-logo"
            onError={(e) => (e.target.style.display = "none")}
          />
        )}

        <i
          className="bi bi-arrow-bar-left sidebar-close-btn"
          onClick={toggleSidebar}
          title="Close sidebar"
        ></i>
      </div>

      <div className="sidebar-content flex-grow-1 py-3 d-flex flex-column gap-3">
        <div className="px-2 d-flex flex-column">
          <div
            className="sidebar-item new-chat-btn d-flex align-items-center p-2 cursor-pointer"
            onClick={onNewChat}
          >
            <div className="sidebar-icon-container">
              <i className="bi bi-pencil-square new-chat-icon"></i>
            </div>
            <span className="sidebar-item-text new-chat-text text-truncate">
              New chat
            </span>
          </div>
        </div>

        {specializedBots.length > 0 && (
          <>
            <div className="mx-3 sidebar-divider"></div>

            <div className="px-2 d-flex flex-column">
              <div
                className="sidebar-section-header px-3 cursor-pointer"
                onClick={() => setIsAgentsCollapsed(!isAgentsCollapsed)}
              >
                <div className="d-flex align-items-center">
                  <i
                    className={`bi bi-chevron-${
                      isAgentsCollapsed ? "right" : "down"
                    } me-2`}
                  ></i>
                  <span>AGENTS</span>
                </div>

                <div
                  className="info-icon-wrapper px-2"
                  onClick={(e) => e.stopPropagation()}
                >
                  <CustomTooltip
                    id="tooltip-agents-info"
                    content="Specialized agents focused on specific tasks and domains."
                    delay={{ show: 200, hide: 300 }}
                  >
                    <i className="bi bi-info-circle info-icon"></i>
                  </CustomTooltip>
                </div>
              </div>

              {!isAgentsCollapsed && (
                <div className="d-flex flex-column gap-1 mt-1">
                  {specializedBots.map((bot) => {
                    const isAgentDropdownOpen =
                      openDropdownId === `agent-${bot.id}`;

                    return (
                      <div
                        key={bot.id}
                        className={`sidebar-item d-flex align-items-center p-2 cursor-pointer ${
                          selectedChatbot?.id === bot.id ? "active" : ""
                        } ${isAgentDropdownOpen ? "dropdown-open" : ""}`}
                        onClick={() => onSelectChatbot(bot)}
                      >
                        <CustomTooltip
                          id={`tooltip-${bot.id}`}
                          disabled={isAgentDropdownOpen}
                          content={
                            <div className="text-start">
                              <strong>{bot.name}</strong>
                              <br />
                              {bot.description}
                            </div>
                          }
                        >
                          <div className="d-flex align-items-center flex-grow-1 overflow-hidden pe-4">
                            <div className="sidebar-icon-container">
                              {bot.icon ? (
                                <img
                                  src={bot.icon}
                                  alt=""
                                  className="agent-icon"
                                  onError={(e) => {
                                    e.target.style.display = "none";
                                    e.target.nextSibling.style.display =
                                      "inline-block";
                                  }}
                                />
                              ) : null}
                              <i
                                className="bi bi-robot agent-icon-fallback"
                                style={{
                                  display: bot.icon ? "none" : "inline-block",
                                }}
                              ></i>
                            </div>
                            <span className="sidebar-item-text text-truncate">
                              {bot.name}
                            </span>
                          </div>
                        </CustomTooltip>

                        <div className="sidebar-item-actions">
                          <div
                            className="sidebar-dots-menu"
                            onClick={(e) => {
                              e.stopPropagation();
                              setOpenDropdownId(
                                isAgentDropdownOpen ? null : `agent-${bot.id}`,
                              );
                            }}
                          >
                            <Dropdown show={isAgentDropdownOpen} drop="end">
                              <Dropdown.Toggle
                                as="div"
                                bsPrefix="dropdown-toggle-custom"
                                className="text-muted d-flex align-items-center"
                              >
                                <i className="bi bi-three-dots-vertical dropdown-dots-icon"></i>
                              </Dropdown.Toggle>

                              <Dropdown.Menu
                                className="shadow-lg border sidebar-dropdown-menu"
                                renderOnMount
                                popperConfig={{
                                  strategy: "fixed",
                                  modifiers: [
                                    {
                                      name: "preventOverflow",
                                      options: { boundary: "window" },
                                    },
                                    {
                                      name: "computeStyles",
                                      options: { adaptive: false },
                                    },
                                  ],
                                }}
                              >
                                <Dropdown.Item
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setOpenDropdownId(null);
                                    if (onOpenSettings) onOpenSettings(bot);
                                  }}
                                >
                                  <i className="bi bi-gear-fill me-2"></i>{" "}
                                  Settings
                                </Dropdown.Item>
                              </Dropdown.Menu>
                            </Dropdown>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </>
        )}

        <div className="mx-3 sidebar-divider"></div>

        <div className="px-2 d-flex flex-column">
          <div
            className="sidebar-section-header px-3 cursor-pointer"
            onClick={() => setIsChatsCollapsed(!isChatsCollapsed)}
          >
            <div className="d-flex align-items-center">
              <i
                className={`bi bi-chevron-${
                  isChatsCollapsed ? "right" : "down"
                } me-2`}
              ></i>
              <span>RECENT CHATS</span>
            </div>

            <div
              className="upload-icon-wrapper px-2 d-flex align-items-center"
              onClick={(e) => e.stopPropagation()}
            >
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                style={{ display: "none" }}
                accept=".json"
                disabled={isLoadingHistory}
              />
              {isLoadingHistory ? (
                <Spinner
                  animation="border"
                  size="sm"
                  className="text-muted"
                  title="Importing..."
                />
              ) : (
                <i
                  className="bi bi-upload cursor-pointer upload-icon"
                  title="Import Chat"
                  onClick={() => fileInputRef.current.click()}
                ></i>
              )}
            </div>
          </div>

          {!isChatsCollapsed && (
            <>
              <div className="sidebar-search-wrapper">
                <div className="d-flex align-items-center border rounded sidebar-search-container">
                  <i className="bi bi-search text-muted me-2"></i>
                  <input
                    type="text"
                    placeholder="Search chats by title..."
                    className="form-control border-0 shadow-none bg-transparent p-0"
                    value={searchQuery}
                    onChange={(e) => onSearchChange(e.target.value)}
                  />
                  {searchQuery && (
                    <i
                      className="bi bi-x-circle-fill text-muted cursor-pointer ms-1 search-clear-icon"
                      onClick={() => onSearchChange("")}
                    ></i>
                  )}
                </div>
              </div>

              <div className="d-flex flex-column gap-1">
                {isLoadingList && chatHistoryList.length === 0 ? (
                  <div className="d-flex align-items-center gap-2 px-4 py-2 text-muted sidebar-status-message">
                    <Spinner animation="border" size="sm" />
                    <span>Loading...</span>
                  </div>
                ) : chatHistoryList.length === 0 ? (
                  <div className="px-4 text-muted text-center sidebar-status-message sidebar-empty-state">
                    {searchQuery
                      ? "No matching chats found."
                      : "No recent chats found."}
                  </div>
                ) : (
                  <>
                    {chatHistoryList.map((chat) => {
                      const isDropdownOpen = openDropdownId === chat.thread_id;

                      return (
                        <div
                          key={chat.thread_id}
                          className={`sidebar-item d-flex align-items-center p-2 cursor-pointer ${
                            currentThreadId === chat.thread_id ? "active" : ""
                          } ${isDropdownOpen ? "dropdown-open" : ""}`}
                          onClick={() => onLoadOldChat(chat)}
                          title={chat.title}
                        >
                          <span className="sidebar-item-text text-truncate pe-4">
                            {chat.title}
                          </span>

                          <div className="sidebar-item-actions">
                            {chat.is_pinned && (
                              <i className="bi bi-pin-fill sidebar-pin-icon"></i>
                            )}

                            <div
                              className="sidebar-dots-menu"
                              onClick={(e) => {
                                e.stopPropagation();
                                setOpenDropdownId(
                                  isDropdownOpen ? null : chat.thread_id,
                                );
                              }}
                            >
                              <Dropdown show={isDropdownOpen} drop="end">
                                <Dropdown.Toggle
                                  as="div"
                                  bsPrefix="dropdown-toggle-custom"
                                  className="text-muted d-flex align-items-center"
                                >
                                  <i className="bi bi-three-dots-vertical dropdown-dots-icon"></i>
                                </Dropdown.Toggle>

                                <Dropdown.Menu
                                  className="shadow-lg border sidebar-dropdown-menu"
                                  renderOnMount
                                  popperConfig={{
                                    strategy: "fixed",
                                    modifiers: [
                                      {
                                        name: "preventOverflow",
                                        options: { boundary: "window" },
                                      },
                                      {
                                        name: "computeStyles",
                                        options: { adaptive: false },
                                      },
                                    ],
                                  }}
                                >
                                  <Dropdown.Item
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      setOpenDropdownId(null);
                                      onPinChat(
                                        chat.thread_id,
                                        !chat.is_pinned,
                                      );
                                    }}
                                  >
                                    <i
                                      className={`bi ${
                                        chat.is_pinned
                                          ? "bi-pin"
                                          : "bi-pin-fill"
                                      } me-2`}
                                    ></i>
                                    {chat.is_pinned ? "Unpin chat" : "Pin chat"}
                                  </Dropdown.Item>

                                  <Dropdown.Item
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      setOpenDropdownId(null);
                                      onRenameChat(chat);
                                    }}
                                  >
                                    <i className="bi bi-pencil-fill me-2"></i>{" "}
                                    Rename
                                  </Dropdown.Item>

                                  <Dropdown.Item
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      setOpenDropdownId(null);
                                      onExportChat(chat);
                                    }}
                                  >
                                    <i className="bi bi-download me-2"></i>{" "}
                                    Export
                                  </Dropdown.Item>

                                  <Dropdown.Divider />

                                  <Dropdown.Item
                                    className="text-danger"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      setOpenDropdownId(null);
                                      onDeleteChat(chat.thread_id);
                                    }}
                                  >
                                    <i className="bi bi-trash3 me-2"></i> Delete
                                  </Dropdown.Item>
                                </Dropdown.Menu>
                              </Dropdown>
                            </div>
                          </div>
                        </div>
                      );
                    })}

                    {hasMoreChats && !searchQuery && (
                      <div
                        className="text-center py-3 mt-1 cursor-pointer sidebar-load-more"
                        onClick={onLoadMoreChats}
                      >
                        <i className="bi bi-chevron-down me-1"></i> Load older
                        chats
                      </div>
                    )}
                  </>
                )}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default Sidebar;

