import React, { createContext, useState, useContext, useEffect } from 'react';
import api from '../api/client';
import { getNumberFormat, formatNumber } from '../utils/numberFormat';

// Create the context
const ConfigContext = createContext();

const emptyProfile = () => ({
  user_details: '',
  input_method: 'enter',
  number_format: getNumberFormat(),
});

// Create a provider component
export const ConfigProvider = ({ children }) => {
  const [config, setConfig] = useState({
    // No default values - we'll only use what the server provides
  });
  // Profile is per user (details, input method, number format). It stays off
  // `config`, which /api/config replaces with the agent settings.
  const [profile, setProfile] = useState(emptyProfile);
  const [loading, setLoading] = useState(true);

  const updateConfig = (newParams) => {
    setConfig(prev => ({ ...prev, ...newParams }));
  };

  const updateProfile = (newParams) => {
    setProfile(prev => ({
      ...prev,
      ...newParams,
      number_format: newParams.number_format || prev.number_format,
    }));
  };

  const clearProfile = () => {
    setProfile(emptyProfile());
  };

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const response = await api.get("config");
        setConfig({ ...response.data });
      } catch (error) {
        console.error('Error fetching config:', error);
        // Keep empty config if fetch fails
      } finally {
        setLoading(false);
      }
    };

    fetchConfig();
  }, []);

  return (
    <ConfigContext.Provider value={{ config, profile, loading, updateConfig, updateProfile, clearProfile }}>
      {children}
    </ConfigContext.Provider>
  );
};

// Create a custom hook to use the config context
export const useConfig = () => {
  const context = useContext(ConfigContext);
  if (context === undefined) {
    throw new Error('useConfig must be used within a ConfigProvider');
  }
  return context;
};

// Returns a formatter that uses the number format chosen in the User Profile modal
export const useNumberFormat = () => {
  const { profile } = useConfig();
  return (value, decimals = 0) => formatNumber(value, profile.number_format, decimals);
};

export default ConfigContext;

import React, {
  createContext,
  useState,
  useContext,
  useCallback,
  useEffect,
  useMemo,
  useRef,
} from 'react';
import api from '../api/client';
import NotificationToast from '../components/NotificationToast/NotificationToast';

// Create the context
const ReportContext = createContext();

// Report status constants (same values as the /api/reports/status endpoint)
export const REPORT_STATUS = {
  PENDING: 'PENDING',
  PROCESSING: 'PROCESSING',
  COMPLETED: 'COMPLETED',
  FAILED: 'FAILED',
  CANCELLED: 'CANCELLED',
};

export const isActiveStatus = (status) =>
  status === REPORT_STATUS.PENDING || status === REPORT_STATUS.PROCESSING;

// No idle polling: the server is only queried while jobs are running or the manager is open
const POLL_FAST_MS = 3000; // first minute of an active job
const POLL_MEDIUM_MS = 5000; // up to 5 minutes
const POLL_SLOW_MS = 10000; // up to 15 minutes, and while the manager is open without active jobs
const POLL_IDLE_MS = 30000; // very long jobs
const POLL_MAX_BACKOFF_MS = 60000; // ceiling when the server keeps failing
const STALE_ON_VISIBLE_MS = 30000;

// Delay grows with the age of the current burst of active jobs and doubles on every consecutive error
const nextPollDelay = (activeSince, failures = 0) => {
  let delay = POLL_SLOW_MS;
  if (activeSince) {
    const elapsed = Date.now() - activeSince;
    if (elapsed < 60000) delay = POLL_FAST_MS;
    else if (elapsed < 300000) delay = POLL_MEDIUM_MS;
    else if (elapsed < 900000) delay = POLL_SLOW_MS;
    else delay = POLL_IDLE_MS;
  }
  return Math.min(delay * 2 ** Math.min(failures, 5), Math.max(delay, POLL_MAX_BACKOFF_MS));
};

// Default when the server does not report a limit (same as the backend default)
const DEFAULT_REPORT_LIMIT = 20;

const normalizeReport = (raw) => ({
  id: raw.report_id,
  analysisId: raw.analysis_id,
  title: raw.title || '',
  question: raw.question || '',
  language: raw.language || 'English',
  status: raw.status,
  stage: raw.stage,
  error: raw.error || null,
  createdAt: raw.created_at,
  startedAt: raw.started_at,
  completedAt: raw.completed_at,
});

const errorMessage = (error, fallback) =>
  error?.response?.data?.error || error?.response?.data?.message || error?.message || fallback;

// Create a provider component
export const ReportProvider = ({ children }) => {
  const [reports, setReports] = useState([]); // Newest first, mirrors the server
  const [reportsLoaded, setReportsLoaded] = useState(false);
  const [reportLimit, setReportLimit] = useState(DEFAULT_REPORT_LIMIT); // max stored reports per user
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [pollingEnabled, setPollingEnabled] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '', variant: 'info', title: '' });

  const previousStatusesRef = useRef(null); // report id -> last seen status (null until first load)
  const inFlightRef = useRef(false);
  const lastFetchRef = useRef(0);
  const activeSinceRef = useRef(null); // when the current burst of active jobs started
  const failuresRef = useRef(0); // consecutive failed status requests (drives the backoff)
  const prevCountRef = useRef(null); // report count of the previous refresh (null until first load)

  const showToast = useCallback((title, message, variant = 'info') => {
    setToast({ show: true, title, message, variant });
  }, []);

  const applyServerReports = useCallback((serverReports) => {
    const previous = previousStatusesRef.current;
    const next = {};
    serverReports.forEach((report) => {
      next[report.id] = report.status;
      if (previous && isActiveStatus(previous[report.id])) {
        const label = report.title || report.question || 'DeepQuery report';
        if (report.status === REPORT_STATUS.COMPLETED) {
          setToast({
            show: true,
            title: 'Report ready',
            message: `${label} (${report.language}) is ready in the DeepQuery Reports Manager.`,
            variant: 'success',
          });
        } else if (report.status === REPORT_STATUS.FAILED) {
          setToast({
            show: true,
            title: 'Report failed',
            message: `${label} (${report.language}) failed${report.error ? `: ${report.error}` : '.'}`,
            variant: 'danger',
          });
        }
      }
    });
    previousStatusesRef.current = next;
    setReports(serverReports);
    setReportsLoaded(true);
  }, []);

  // Fetch the current state of all reports (never contains HTML or metadata)
  const refreshReports = useCallback(async () => {
    if (inFlightRef.current) return;
    inFlightRef.current = true;
    lastFetchRef.current = Date.now();
    try {
      const response = await api.get('reports/status');
      failuresRef.current = 0;
      if (Array.isArray(response.data?.reports)) {
        if (Number.isFinite(response.data.limit)) setReportLimit(response.data.limit);
        applyServerReports(response.data.reports.map(normalizeReport));
      }
    } catch (error) {
      failuresRef.current += 1;
      if (error?.response?.status === 401) {
        // Session expired (or opened elsewhere): stop polling until the user logs in again
        setPollingEnabled(false);
      } else {
        console.debug('Could not refresh reports:', error?.message);
      }
    } finally {
      inFlightRef.current = false;
    }
  }, [applyServerReports]);

  const activeCount = useMemo(
    () => reports.filter((report) => isActiveStatus(report.status)).length,
    [reports]
  );
  const hasActive = activeCount > 0;

  const hasActiveRef = useRef(false);
  hasActiveRef.current = hasActive;
  if (hasActive && !activeSinceRef.current) activeSinceRef.current = Date.now();
  if (!hasActive) activeSinceRef.current = null;

  // Seed the state once on login and clear it on logout / expired session
  useEffect(() => {
    if (!pollingEnabled) {
      previousStatusesRef.current = null;
      setReports([]);
      setReportsLoaded(false);
      return;
    }
    refreshReports();
  }, [pollingEnabled, refreshReports]);

  // Refresh once whenever the manager is opened
  useEffect(() => {
    if (pollingEnabled && isModalOpen) refreshReports();
  }, [pollingEnabled, isModalOpen, refreshReports]);

  // Poll only while jobs are active or the manager is open. A single timeout chain
  // (delay recomputed on every tick) avoids refetching when the state flips.
  const shouldPoll = pollingEnabled && (hasActive || isModalOpen);
  useEffect(() => {
    if (!shouldPoll) return undefined;
    let timer;
    const tick = async () => {
      if (!document.hidden) await refreshReports();
      timer = setTimeout(tick, nextDelay());
    };
    const nextDelay = () =>
      nextPollDelay(hasActiveRef.current ? activeSinceRef.current : null, failuresRef.current);
    timer = setTimeout(tick, nextDelay());
    return () => clearTimeout(timer);
  }, [shouldPoll, refreshReports]);

  // Coming back to a tab that has not been refreshed for a while
  useEffect(() => {
    if (!pollingEnabled) return undefined;
    const handleVisibility = () => {
      if (!document.hidden && Date.now() - lastFetchRef.current > STALE_ON_VISIBLE_MS) refreshReports();
    };
    document.addEventListener('visibilitychange', handleVisibility);
    return () => document.removeEventListener('visibilitychange', handleVisibility);
  }, [pollingEnabled, refreshReports]);

  // Cancel a pending / running report
  const cancelReport = useCallback(async (reportId) => {
    try {
      await api.post(`reports/${reportId}/cancel`);
    } catch (error) {
      showToast('Could not cancel', errorMessage(error, 'The report could not be cancelled.'), 'danger');
    }
    await refreshReports();
  }, [refreshReports, showToast]);

  // Warn when a new report brings the user close to (or at) the stored reports limit.
  // The first load stays silent: only growth afterwards triggers a warning.
  useEffect(() => {
    if (!reportsLoaded) {
      prevCountRef.current = null;
      return;
    }
    const previous = prevCountRef.current;
    prevCountRef.current = reports.length;
    if (previous === null || reports.length <= previous) return;
    const remaining = reportLimit - reports.length;
    if (remaining > 3) return;
    showToast(
      remaining <= 0 ? 'Report limit reached' : 'Report limit almost reached',
      remaining <= 0
        ? `You have ${reports.length} of ${reportLimit} reports. Delete some in the DeepQuery Reports Manager to create new ones.`
        : `You have ${reports.length} of ${reportLimit} reports. ${remaining} left before you need to delete some.`,
      'warning'
    );
  }, [reports.length, reportLimit, reportsLoaded, showToast]);

  // Generate the same analysis in another language, reusing the extracted data
  const createVariant = useCallback(async (reportId, language) => {
    try {
      await api.post(`reports/${reportId}/variant`, { language });
      showToast('Variant queued', `A ${language} version of the report is being generated.`, 'info');
      await refreshReports();
      return true;
    } catch (error) {
      showToast('Could not create variant', errorMessage(error, 'The variant could not be created.'), 'danger');
      return false;
    }
  }, [refreshReports, showToast]);

  // Run an analysis again from its original question (used when the report of a chat message is gone).
  // Returns the new report ids (empty on failure).
  const regenerateFromQuestion = useCallback(async ({ question, languages }) => {
    try {
      const response = await api.post('reports', { question, languages });
      await refreshReports();
      return (response.data?.reports || []).map((report) => report.report_id);
    } catch (error) {
      showToast('Could not regenerate report', errorMessage(error, 'The report could not be regenerated.'), 'danger');
      return [];
    }
  }, [refreshReports, showToast]);

  // Re-queue a failed / cancelled report in place
  const retryReport = useCallback(async (reportId) => {
    try {
      await api.post(`reports/${reportId}/retry`);
      showToast('Retrying report', 'The report has been queued again.', 'info');
      await refreshReports();
      return true;
    } catch (error) {
      showToast('Could not retry', errorMessage(error, 'The report could not be retried.'), 'danger');
      return false;
    }
  }, [refreshReports, showToast]);

  // Build a report from the metadata of a chat message created before async reports existed.
  // Returns the new report id (or null on failure).
  const regenerateLegacy = useCallback(async ({ question, deepqueryMetadata, language }) => {
    try {
      const response = await api.post('reports/from-legacy', {
        question,
        deepquery_metadata: deepqueryMetadata,
        language,
      });
      await refreshReports();
      return response.data?.report?.report_id || null;
    } catch (error) {
      showToast('Could not generate report', errorMessage(error, 'The report could not be generated.'), 'danger');
      return null;
    }
  }, [refreshReports, showToast]);

  // Delete one report from the server
  const deleteReport = useCallback(async (reportId) => {
    try {
      await api.delete(`reports/${reportId}`);
      if (previousStatusesRef.current) delete previousStatusesRef.current[reportId];
      setReports((prev) => prev.filter((report) => report.id !== reportId));
    } catch (error) {
      showToast('Could not delete', errorMessage(error, 'The report could not be deleted.'), 'danger');
      await refreshReports();
    }
  }, [refreshReports, showToast]);

  // Delete every report (running ones are cancelled first)
  const clearAllReports = useCallback(async () => {
    try {
      await api.delete('reports');
      previousStatusesRef.current = {};
      setReports([]);
    } catch (error) {
      showToast('Could not clear reports', errorMessage(error, 'The reports could not be deleted.'), 'danger');
      await refreshReports();
    }
  }, [refreshReports, showToast]);

  // Heavy payloads are fetched on demand only
  const fetchHtml = useCallback(async (reportId) => {
    const response = await api.get(`reports/${reportId}/html`);
    return response.data; // { html_report, title }
  }, []);

  const fetchAnalysis = useCallback(async (reportId) => {
    const response = await api.get(`reports/${reportId}/analysis`);
    return response.data; // { question, title, deepquery_metadata }
  }, []);

  // Get counts by status
  const getStatusCounts = useCallback(() => {
    return reports.reduce((counts, report) => {
      counts[report.status] = (counts[report.status] || 0) + 1;
      return counts;
    }, {});
  }, [reports]);

  const value = useMemo(() => ({
    reports,
    reportsLoaded,
    reportLimit,
    activeCount,
    isModalOpen,
    setIsModalOpen,
    setPollingEnabled,
    refreshReports,
    cancelReport,
    createVariant,
    retryReport,
    regenerateLegacy,
    regenerateFromQuestion,
    deleteReport,
    removeReport: deleteReport,
    clearAllReports,
    fetchHtml,
    fetchAnalysis,
    getStatusCounts,
    showToast,
  }), [
    reports, reportsLoaded, reportLimit, activeCount, isModalOpen, refreshReports, cancelReport,
    createVariant, retryReport, regenerateLegacy, regenerateFromQuestion, deleteReport, clearAllReports, fetchHtml, fetchAnalysis, getStatusCounts, showToast,
  ]);

  return (
    <ReportContext.Provider value={value}>
      {children}
      <NotificationToast
        show={toast.show}
        message={toast.message}
        variant={toast.variant}
        title={toast.title}
        onClose={() => setToast((prev) => ({ ...prev, show: false }))}
      />
    </ReportContext.Provider>
  );
};

// Create a custom hook to use the report context
export const useReport = () => {
  const context = useContext(ReportContext);
  if (context === undefined) {
    throw new Error('useReport must be used within a ReportProvider');
  }
  return context;
};

export default ReportContext;

import { useState, useMemo } from "react";
import api from "../api/client";

export const useAgentManager = (updateConfig) => {
  const [chatbots, setChatbots] = useState([]);
  const [selectedChatbot, setSelectedChatbot] = useState(null);
  const [globalEnabled, setGlobalEnabled] = useState(false);
  const [isSwitchingAgent, setIsSwitchingAgent] = useState(false);
  const [syncedResources, setSyncedResources] = useState({});
  const [partialResources, setPartialResources] = useState({});
  const [userSyncPermissions, setUserSyncPermissions] = useState(true);

  const activeChatbot = useMemo(() => {
    if (selectedChatbot) return selectedChatbot;
    const globalBot = chatbots.find((bot) => bot.isGlobal);
    return globalBot || { id: "global", isGlobal: true, name: "General Chat" };
  }, [selectedChatbot, chatbots]);

  const switchAgentInBackend = async (bot) => {
    const payload = { id: bot.id };

    const response = await api.post("change_agent", payload);
    if (response.data.success) {
      if (response.data.syncedResources)
        setSyncedResources(response.data.syncedResources);
      if (response.data.partialResources)
        setPartialResources(response.data.partialResources);
      if (response.data.config) updateConfig(response.data.config);
    }
  };

  return {
    chatbots,
    setChatbots,
    selectedChatbot,
    setSelectedChatbot,
    globalEnabled,
    setGlobalEnabled,
    isSwitchingAgent,
    setIsSwitchingAgent,
    syncedResources,
    setSyncedResources,
    partialResources,
    setPartialResources,
    userSyncPermissions,
    setUserSyncPermissions,
    activeChatbot,
    switchAgentInBackend,
  };
};

import { useState } from "react";
import api from "../api/client";
import { actionTypes } from "../reducers/chatReducer";

const CHAT_PAGE_LIMIT = 20;

export const useChatHistory = (
  dispatch,
  chatbots,
  switchAgentInBackend,
  setSelectedChatbot,
  setAutoOverwriteAccepted,
  handleLimitReached
) => {
  const [currentThreadId, setCurrentThreadId] = useState(null);
  const [chatHistoryList, setChatHistoryList] = useState([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [chatToDelete, setChatToDelete] = useState(null);
  const [chatToRename, setChatToRename] = useState(null);
  const [newChatName, setNewChatName] = useState("");
  const [chatOffset, setChatOffset] = useState(0);
  const [hasMoreChats, setHasMoreChats] = useState(true);
  const [isLoadingList, setIsLoadingList] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [toastConfig, setToastConfig] = useState({
    show: false,
    message: "",
    variant: "info",
    title: "",
  });

  const showToast = (message, variant = "info", title = "Notification") => {
    setToastConfig({ show: true, message, variant, title });
  };

  const closeToast = () => {
    setToastConfig((prev) => ({ ...prev, show: false }));
  };

  const fetchChatHistoryList = async (
    isLoadMore = false,
    query = searchQuery,
  ) => {
    try {
      if (!isLoadMore) setIsLoadingList(true);
      const currentOffset = isLoadMore ? chatOffset + CHAT_PAGE_LIMIT : 0;
      const response = await api.get(
        `history?limit=${CHAT_PAGE_LIMIT}&offset=${currentOffset}&q=${encodeURIComponent(query)}`,
      );

      if (response.data && response.data.chats) {
        const newChats = response.data.chats;
        if (isLoadMore) {
          setChatHistoryList((prev) => [...prev, ...newChats]);
          setChatOffset(currentOffset);
        } else {
          setChatHistoryList(newChats);
          setChatOffset(0);
        }
        setHasMoreChats(newChats.length >= CHAT_PAGE_LIMIT);
      }
    } catch (error) {
      console.error("Error fetching chat history list", error);
    } finally {
      setIsLoadingList(false);
    }
  };

  const handleRequestCompletion = (requestId) => {
    fetchChatHistoryList(false);
  };

  const handleLoadOldChat = async (chat) => {
    try {
      setAutoOverwriteAccepted(false);
      setIsLoadingHistory(true);

      let targetBot = chatbots.find((b) => b.isGlobal);
      if (chat.agent_id) {
        targetBot = chatbots.find((b) => b.id === chat.agent_id) || targetBot;
      }
      await switchAgentInBackend(targetBot);

      setCurrentThreadId(chat.thread_id);
      setSelectedChatbot(targetBot);
      dispatch({ type: actionTypes.CLEAR_CHAT });

      const response = await api.get(`history/${chat.thread_id}/export`);
      const rawMessages = response.data.messages || [];
      const formattedResults = [];
      let currentInteraction = null;

      for (let i = 0; i < rawMessages.length; i++) {
        const msg = rawMessages[i];

        if (msg.role === "human" || msg.role === "user") {
          // Push previous interaction if exists
          if (currentInteraction) formattedResults.push(currentInteraction);

          let cleanQuestion = msg.content || "";
          if (cleanQuestion.includes("<user_query>")) {
            const match = cleanQuestion.match(
              /<user_query>([\s\S]*?)<\/user_query>/,
            );
            if (match && match[1]) cleanQuestion = match[1].trim();
          }

          // Start a new interaction
          currentInteraction = {
            question: cleanQuestion,
            result: "",
            blocks: [],
            uuid: msg.uuid || `hist-${chat.thread_id}-${formattedResults.length}`,
            isLoading: false,
            isError: false,
            toolCalls: [],
            chatbot_llm: null,
            relatedQuestions: [],
            relatedQuestionsDeepQuery: [],
            combinedTablesUsed: [],
            combinedVqls: "",
            disableFeedback: false,
          };
        } else if (currentInteraction) {
          // --- AI/ASSISTANT MESSAGES ---
          if (msg.role === "ai" || msg.role === "assistant") {

            if (msg.is_imported) {
              currentInteraction.disableFeedback = true;
            }

            if (msg.chatbot_llm) {
              currentInteraction.chatbot_llm = msg.chatbot_llm;
            } else if (!currentInteraction.chatbot_llm) {
              currentInteraction.chatbot_llm = "History Record";
            }

            // 1. Process Text Block sequentially
            if (msg.content && typeof msg.content === "string") {
              let text = msg.content;

              // Extract related questions
              const rqRegex =
                /<related_question[^>]*>([\s\S]*?)<\/related_question>/gi;
              let match;
              while ((match = rqRegex.exec(text)) !== null)
                currentInteraction.relatedQuestions.push(match[1].trim());

              const rqdqRegex =
                /<related_question_deepquery[^>]*>([\s\S]*?)<\/related_question_deepquery>/gi;
              while ((match = rqdqRegex.exec(text)) !== null)
                currentInteraction.relatedQuestionsDeepQuery.push(
                  match[1].trim(),
                );

              const rqaRegex =
                /<related_question_analysis[^>]*>([\s\S]*?)<\/related_question_analysis>/gi;
              while ((match = rqaRegex.exec(text)) !== null)
                currentInteraction.relatedQuestionsDeepQuery.push(
                  match[1].trim(),
                );

              // Clean text from tags
              text = text
                .replace(
                  /<related_question[^>]*>[\s\S]*?<\/related_question>/gi,
                  "",
                )
                .replace(
                  /<related_question_deepquery[^>]*>[\s\S]*?<\/related_question_deepquery>/gi,
                  "",
                )
                .replace(
                  /<related_question_analysis[^>]*>[\s\S]*?<\/related_question_analysis>/gi,
                  "",
                );

              const cleanText = text.trim();

              // Push text directly to blocks to maintain sequential order
              if (cleanText) {
                currentInteraction.blocks.push({
                  type: "message",
                  content: cleanText,
                });
                currentInteraction.result +=
                  (currentInteraction.result ? "\n" : "") + cleanText;
              }
            }

            // 2. Process Tool Calls sequentially
            if (msg.tool_calls && Array.isArray(msg.tool_calls)) {
              msg.tool_calls.forEach((tc) => {
                const toolBlock = {
                  type: "tool",
                  toolName: tc.name,
                  name: tc.name,
                  toolCallId: tc.id,
                  args: tc.args || {},
                  status: "running",
                };
                // Push reference to both arrays
                currentInteraction.toolCalls.push(toolBlock);
                currentInteraction.blocks.push(toolBlock);
              });
            }
          }

          // --- TOOL MESSAGES ---
          else if (msg.role === "tool") {
            let parsedResult = msg.content;
            try {
              if (msg.content && typeof msg.content === "string")
                parsedResult = JSON.parse(msg.content);
            } catch (e) {}

            const artifact = msg.artifact || {};
            if (artifact.tables_used && Array.isArray(artifact.tables_used)) {
              artifact.tables_used.forEach((table) => {
                if (!currentInteraction.combinedTablesUsed.includes(table))
                  currentInteraction.combinedTablesUsed.push(table);
              });
            }

            if (Array.isArray(artifact.related_tables)) {
              artifact.related_tables.forEach((entry) => {
                const table = entry && entry.view_name;
                if (table && !currentInteraction.combinedTablesUsed.includes(table))
                  currentInteraction.combinedTablesUsed.push(table);
              });
            }

            if (artifact.vql) {
              currentInteraction.combinedVqls +=
                (currentInteraction.combinedVqls ? "\n\n" : "") + artifact.vql;
            }

            // Find the sequential block and update it
            const blockIndex = currentInteraction.blocks.findIndex(
              (b) => b.type === "tool" && b.toolCallId === msg.tool_call_id,
            );

            // Mirror the live-stream behavior: a result whose artifact carries
            // an error (e.g. an interrupted tool call) renders as errored.
            const resultStatus = artifact && artifact.error ? "error" : "finished";

            if (blockIndex !== -1) {
              currentInteraction.blocks[blockIndex].status = resultStatus;
              currentInteraction.blocks[blockIndex].result = parsedResult;
              currentInteraction.blocks[blockIndex].output = parsedResult;
              currentInteraction.blocks[blockIndex].contentToLLM = msg.content;
              currentInteraction.blocks[blockIndex].artifact = artifact;
            } else {
              // Edge case: Tool answer without previous Tool call registered
              const newToolBlock = {
                type: "tool",
                toolName: msg.tool_name || "tool",
                name: msg.tool_name || "tool",
                toolCallId: msg.tool_call_id,
                status: resultStatus,
                result: parsedResult,
                output: parsedResult,
                contentToLLM: msg.content,
                artifact: artifact,
                args: {},
              };
              currentInteraction.toolCalls.push(newToolBlock);
              currentInteraction.blocks.push(newToolBlock);
            }
          }
        }
      }

      if (currentInteraction) formattedResults.push(currentInteraction);

      dispatch({
        type: actionTypes.SET_CHAT_HISTORY,
        payload: formattedResults,
      });
    } catch (error) {
      console.error(error);
      alert("Error loading this conversation.");
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const confirmDeleteChat = async (handleNewChat) => {
    if (!chatToDelete) return;
    try {
      await api.delete(`history/${chatToDelete}`);
      if (currentThreadId === chatToDelete) handleNewChat();
      fetchChatHistoryList(false);
    } catch (error) {
      alert("Error deleting the chat history.");
    } finally {
      setChatToDelete(null);
    }
  };

  const handleRenameSubmit = async () => {
    if (!chatToRename || !newChatName.trim()) return;
    try {
      await api.put(`history/${chatToRename.thread_id}`, {
        title: newChatName,
      });
      fetchChatHistoryList(false);
    } catch (e) {
      alert("Error renaming chat.");
    } finally {
      setChatToRename(null);
      setNewChatName("");
    }
  };

  const handlePinChat = async (threadId, isPinned) => {
    try {
      await api.put(`history/${threadId}/pin`, { is_pinned: isPinned });
      fetchChatHistoryList(false);
    } catch (e) {
      alert("Error pin status.");
    }
  };

  const handleExportChat = async (chat) => {
    try {
      const response = await api.get(`history/${chat.thread_id}/export`);
      const exportPayload = { ...response.data, title: chat.title };
      const blob = new Blob([JSON.stringify(exportPayload, null, 2)], {
        type: "application/json",
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `denodo_chat_${chat.title.replace(/[^a-z0-9]/gi, "_").toLowerCase()}.json`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("Error exporting chat.");
    }
  };

  const handleImportChat = async (file, forceOverwrite = false) => {
    if (!file) return;

    setIsLoadingHistory(true);

    const formData = new FormData();
    formData.append("file", file);
    if (forceOverwrite) formData.append("force_overwrite", "true");

    try {
      const response = await api.post("history/import", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      if (response.data.success) {
        await fetchChatHistoryList(false);
        await handleLoadOldChat({
          thread_id: response.data.thread_id,
          agent_id: response.data.agent_id,
          title: response.data.title
        });

        if (response.data.was_truncated) {
          showToast(
            `The imported chat exceeded the maximum length. Only the last ${response.data.max_messages} messages were kept to ensure optimal performance.`,
            'warning',
            'Chat Truncated'
          );
        } else {
          showToast("Chat imported successfully!", "success", "Import Successful");
        }
      }
    } catch (error) {
      if (
        error.response &&
        error.response.status === 409 &&
        error.response.data.error === "limit_reached"
      ) {
        if (handleLimitReached) {
          handleLimitReached(error.response.data, {
            type: "import",
            file: file,
          });
        }
      } else if (error.response && error.response.status === 413) {
        showToast(error.response.data.error || "File is too large.", 'danger', 'File Too Large');
      } else if (error.response && error.response.status === 400) {
         showToast(error.response.data.error || "Invalid JSON format.", 'danger', 'Import Error');
      } else {
        showToast("Error importing chat. Make sure it's a valid JSON export file.", "danger", "Import Failed");
      }
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const resetHistoryState = () => {
    setChatHistoryList([]);
    setChatOffset(0);
    setSearchQuery("");
    setHasMoreChats(true);
  };

  return {
    currentThreadId,
    setCurrentThreadId,
    chatHistoryList,
    isLoadingHistory,
    chatToDelete,
    setChatToDelete,
    chatToRename,
    setChatToRename,
    newChatName,
    setNewChatName,
    hasMoreChats,
    isLoadingList,
    searchQuery,
    setSearchQuery,
    fetchChatHistoryList,
    handleLoadOldChat,
    confirmDeleteChat,
    handleRenameSubmit,
    handlePinChat,
    handleExportChat,
    handleImportChat,
    handleRequestCompletion,
    resetHistoryState,
    toastConfig,
    closeToast,
  };
};

import { useState } from "react";
import { actionTypes } from "../reducers/chatReducer";

export const useChatLimits = (dispatch) => {
  const [limitModal, setLimitModal] = useState({
    show: false,
    type: null,
    pendingData: null,
    limit: 0,
    current: 0,
    targetsToDelete: [],
  });
  const [autoOverwriteAccepted, setAutoOverwriteAccepted] = useState(false);

  const handleLimitReached = (errorData, pendingRequestData) => {
    setLimitModal({
      show: true,
      type: errorData.type,
      limit: errorData.limit,
      current: errorData.current,
      targetsToDelete: errorData.targets_to_delete || [],
      pendingData: pendingRequestData,
    });
  };

  const closeLimitModal = () => {
    if (
      limitModal.pendingData &&
      limitModal.pendingData.resultIndex !== undefined
    ) {
      dispatch({
        type: actionTypes.DELETE_CHAT_ITEM,
        payload: { resultIndex: limitModal.pendingData.resultIndex },
      });
    }
    setLimitModal((prev) => ({
      ...prev,
      show: false,
      pendingData: null,
    }));
  };

  return {
    limitModal,
    setLimitModal,
    autoOverwriteAccepted,
    setAutoOverwriteAccepted,
    handleLimitReached,
    closeLimitModal,
  };
};

import { useState, useRef, useEffect } from "react";
import { useConfig } from "../contexts/ConfigContext";
import { actionTypes } from "../reducers/chatReducer";
import useToolSelector from "./useToolSelector";

const useQuestionForm = (currentQuestion, setCurrentQuestion, results, dispatch, sdk, isAuthenticated, selectedChatbot) => {
  const { config, profile } = useConfig();
  const { isLoading, processQuestion, cancelQuery, runningRequests } = sdk;

  const [showFilterModal, setShowFilterModal] = useState(false);
  const [searchFilters, setSearchFilters] = useState({
    databases: [],
    tags: [],
  });
  const [allowExternalAssociations, setAllowExternalAssociations] = useState(false);
  const [lastToolRequest, setLastToolRequest] = useState(null);

  const textInputRef = useRef(null);

  useEffect(() => {
    setSearchFilters({
      databases: [],
      tags: [],
    });
    setAllowExternalAssociations(false);
  }, [selectedChatbot]);

  const activeRequestId = runningRequests.length > 0 ? runningRequests[runningRequests.length - 1] : null;
  const isQueryRunning = activeRequestId !== null;
  const isAnyQueryRunning = isLoading || results.some((r) => r.isLoading);
  const filterCount = searchFilters.databases.length + searchFilters.tags.length;

  const {
    prepareSubmission,
  } = useToolSelector(config);

  const handleQuestionChange = (event) => {
    setCurrentQuestion(event.target.value);
  };

  const handleFilterSave = ({ databases, tags, allowExternalAssociations }) => {
    setSearchFilters({ databases, tags });
    setAllowExternalAssociations(allowExternalAssociations);
  };

  const submitQuestion = async (questionText, forceType = null) => {
    if (!isAuthenticated || !questionText.trim() || isAnyQueryRunning) return;

    const { finalQuestion, toolName, toolPrettyName } = prepareSubmission(questionText, forceType);
    if (!finalQuestion) return;

    if (toolName) {
      setLastToolRequest({
        name: toolName,
        prettyName: toolPrettyName || toolName,
      });
    }

    const resultIndex = results.length;

    dispatch({
      type: actionTypes.ADD_CHAT_ITEM,
      payload: { 
        question: finalQuestion, 
        isLoading: true, 
        result: "", 
        toolCalls: [],
        blocks: [],
        combinedTablesUsed: []
      }
    });

    const options = {
      databases: searchFilters.databases,
      tags: searchFilters.tags,
      allow_external_associations: allowExternalAssociations
    };

    await processQuestion(finalQuestion, toolName, resultIndex, options);

    setCurrentQuestion("");
  };

  const handleSubmit = (event, forceType = null) => {
    if (event && event.preventDefault) event.preventDefault();
    submitQuestion(currentQuestion, forceType);
  };

  const handleSendClick = (event, forceType = null) => {
    if (!isAuthenticated || isAnyQueryRunning) return;

    if (!currentQuestion.trim()) {
      textInputRef.current?.focus();
      return;
    }

    handleSubmit(event, forceType);
  };

  const handleCancelQuery = () => {
    if (activeRequestId) {
      cancelQuery(activeRequestId);
    }
  };

  return {
    currentQuestion,
    setCurrentQuestion,
    showFilterModal,
    setShowFilterModal,
    searchFilters,
    allowExternalAssociations,
    isQueryRunning,
    isAnyQueryRunning,
    filterCount,
    textInputRef,
    handleQuestionChange,
    handleFilterSave,
    handleSubmit,
    handleSendClick,
    handleCancelQuery,
    lastToolRequest,
    config,
    profile,
  };
};

export default useQuestionForm;

import { useState, useRef } from "react";
import { actionTypes } from "../reducers/chatReducer";
import { buildApiUrl } from "../api/client";

const useSDK = (dispatch, onRequestComplete, currentThreadId, onThreadIdUpdate, onLimitReached, autoOverwriteAccepted, onContextUsage) => {
  const [isLoading, setLoading] = useState(false);
  const [runningRequests, setRunningRequests] = useState(new Set());
  const activeControllers = useRef(new Map()); // Map of requestId -> { controller, resultIndex }
  const requestIdCounter = useRef(0);

  const handleStream = async (url, body, resultIndex, requestId, onMessage, options) => {
    const controller = new AbortController();
    const signal = controller.signal;

    activeControllers.current.set(requestId, { controller, resultIndex });

    try {

      const isQuestion = url.includes('question');
      const fetchUrl = isQuestion ? buildApiUrl("question") : buildApiUrl(url);
      const method = isQuestion ? 'POST' : 'GET';

      const fetchOptions = {
        method,
        headers: isQuestion ? { 'Content-Type': 'application/json' } : undefined,
        body: isQuestion ? JSON.stringify(body) : undefined,
        signal
      };

      const response = await fetch(fetchUrl, fetchOptions);

      if (response.status === 409 && isQuestion) {
        const errorData = await response.json();

        if (onLimitReached) {
          onLimitReached(errorData, {
            query: body.query,
            toolName: body.tool,
            resultIndex,
            options
          });
        }

        return; 
      }

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const returnedThreadId = response.headers.get('X-Thread-ID');
      if (returnedThreadId && onThreadIdUpdate) {
        onThreadIdUpdate(returnedThreadId);
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        // Process complete lines (SSE format usually ends with \n\n)
        const lines = buffer.split('\n\n');
        buffer = lines.pop(); // Keep the incomplete part

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6);
            if (data.trim() === '[DONE]') continue; // OpenAI style, just in case

            // Check for special markers from backend if any (e.g. <STREAMOFF>)
            if (data.includes('<STREAMOFF>')) continue;

            try {
               // Check if it is a JSON object
               if (data.startsWith('{')) {
                   const payload = JSON.parse(data);
                   onMessage(payload);
               } else {

                   onMessage({ type: 'message', content: data });
               }
            } catch (e) {
               // Fallback for plain text
               onMessage({ type: 'message', content: data });
            }
          }
        }
      }

    } catch (error) {
      if (error.name === 'AbortError') {
        return;
      }
      console.error("Stream error:", error);
      const backendMessage = error.message || 'Unknown error';
      dispatch({
        type: actionTypes.ERROR_CHAT_ITEM,
        payload: {
          resultIndex,
          message: `Fatal error when connecting to chatbot backend: ${backendMessage}`,
          errorDetails: backendMessage
        }
      });
    } finally {
      activeControllers.current.delete(requestId);
      setRunningRequests(prev => {
        const next = new Set(prev);
        next.delete(requestId);
        return next;
      });
      onRequestComplete(requestId);
      setLoading(false);
    }
  };

  const processQuestion = async (question, _type, resultIndex, options = {}) => {
    setLoading(true);
    const requestId = `agent_${Date.now()}_${++requestIdCounter.current}`;
    setRunningRequests(prev => new Set([...prev, requestId]));

    const body = {
      query: question,
      cancellation_id: requestId,
      tool: _type,
      databases: options.databases,
      tags: options.tags,
      allow_external_associations: options.allow_external_associations,
      thread_id: currentThreadId,
      force_overwrite: options.force_overwrite !== undefined ? options.force_overwrite : autoOverwriteAccepted
    };

    handleStream('question', body, resultIndex, requestId, (payload) => {
      const type = payload.type;

      if (type === 'message') {
        const text = (payload.content || '').replace(/<NEWLINE>/g, '\n');
        dispatch({
          type: actionTypes.UPDATE_CHAT_ITEM_TEXT,
          payload: { resultIndex, text }
        });
      } else if (type === 'tool_start') {
        const { tool_name, tool_call_id, args } = payload;
        dispatch({
          type: actionTypes.TOOL_CALL_START,
          payload: {
             resultIndex,
             toolCall: { toolName: tool_name, toolCallId: tool_call_id, args: args || {}, status: 'running' }
          }
        });
      } else if (type === 'tool_end') {
        const { tool_name, tool_call_id, content, artifact } = payload;
        dispatch({
            type: actionTypes.TOOL_CALL_END,
            payload: { resultIndex, toolName: tool_name, toolCallId: tool_call_id, content, artifact }
        });
      } else if (type === 'done') {
        if (payload.context_usage && onContextUsage) {
          onContextUsage(payload.context_usage);
        }
        dispatch({
            type: actionTypes.COMPLETE_CHAT_ITEM,
            payload: { resultIndex, payload }
        });
      } else if (type === 'error') {
        const rawMessage = payload.message || 'Error';
        const message = `Fatal error when connecting to chatbot backend: ${rawMessage}`;
        dispatch({
          type: actionTypes.ERROR_CHAT_ITEM,
          payload: {
            resultIndex,
            message,
            errorDetails: payload.traceback || rawMessage
          }
        });
      }
    }, options);

    return requestId;
  };

  const cancelQuery = async (requestId) => {
    const connection = activeControllers.current.get(requestId);
    if (connection) {
      const { controller, resultIndex } = connection;

      controller.abort();
      activeControllers.current.delete(requestId);

      dispatch({
        type: actionTypes.DELETE_CHAT_ITEM,
        payload: { resultIndex }
      });

      setRunningRequests(prev => {
        const newSet = new Set(prev);
        newSet.delete(requestId);
        return newSet;
      });
      setLoading(false);

      // Tell the backend to abort the query, including any in-flight AI SDK
      // request. The endpoint responds once the rollback and empty-chat
      // cleanup have finished, so the sidebar refresh below always sees the
      // final state.
      try {
        await fetch(buildApiUrl('question/cancel'), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ cancellation_id: requestId })
        });
      } catch {
        // Ignore: the request may already be finished; refresh regardless.
      }
      onRequestComplete(requestId);
    }
  };

  return {
    isLoading,
    processQuestion,
    cancelQuery,
    runningRequests: Array.from(runningRequests)
  };
};

export default useSDK;

import { useMemo, useCallback } from "react";

const normalizeString = (value) =>
  String(value || "")
    .toLowerCase()
    .replace(/\s+/g, "")
    .replace(/_/g, "")
    .replace(/@/g, "");

const useToolSelector = (config) => {
  const availableTools = useMemo(() => {
    const tools = Array.isArray(config?.chatbot_tools) ? config.chatbot_tools : [];

    return tools.filter(tool => {
      if (tool.name === 'deep_query' && !config?.enable_deep_query) return false;
      if (tool.name === 'knowledge_query' && !config?.unstructured_mode) return false;
      return true;
    });
  }, [config]);

  const resolveToolFromToken = useCallback(
    (rawToken) => {
      if (!rawToken) return null;
      const token = normalizeString(
        rawToken.startsWith("@") ? rawToken.slice(1) : rawToken
      );

      for (const tool of availableTools) {
        if (tool.name && normalizeString(tool.name) === token) return tool;
        if (Array.isArray(tool.aliases)) {
          if (
            tool.aliases.some(
              (alias) => normalizeString(alias) === token
            )
          ) {
            return tool;
          }
        }
      }
      return null;
    },
    [availableTools]
  );

  const prepareSubmission = useCallback(
    (questionText, forcedTool) => {
      const trimmedStart = questionText.replace(/^\s*/, "");
      let toolName = forcedTool || null;
      let toolPrettyName = null;
      let finalQuestion = questionText.trim();

      if (trimmedStart.startsWith("@")) {
        const match = trimmedStart.match(/^@(\S*)/);
        const token = match ? match[1] : "";
        const resolvedTool = token ? resolveToolFromToken(token) : null;

        if (resolvedTool) {
          toolName = resolvedTool.name;
          toolPrettyName = resolvedTool.pretty_name || resolvedTool.name;
          finalQuestion = questionText.replace(/^@\S+\s*/, "").trim();
        }
      }

      if (toolName && !toolPrettyName) {
        const matched = availableTools.find((tool) => tool.name === toolName);
        if (matched) {
          toolPrettyName = matched.pretty_name || matched.name;
        } else {
          toolPrettyName = toolName;
        }
      }

      return { finalQuestion, toolName, toolPrettyName };
    },
    [resolveToolFromToken, availableTools]
  );

  return {
    prepareSubmission,
  };
};

export default useToolSelector;

html,
body {
  overflow: hidden;
}

import React from "react";
