export const actionTypes = {
  ADD_CHAT_ITEM: "ADD_CHAT_ITEM",
  UPDATE_CHAT_ITEM_TEXT: "UPDATE_CHAT_ITEM_TEXT",
  TOOL_CALL_START: "TOOL_CALL_START",
  TOOL_CALL_END: "TOOL_CALL_END",
  COMPLETE_CHAT_ITEM: "COMPLETE_CHAT_ITEM",
  ERROR_CHAT_ITEM: "ERROR_CHAT_ITEM",
  CLEAR_CHAT: "CLEAR_CHAT",
  DELETE_CHAT_ITEM: "DELETE_CHAT_ITEM",
  PURGE_EXITING_ITEMS: "PURGE_EXITING_ITEMS",
  SET_CHAT_ITEM_FEEDBACK: "SET_CHAT_ITEM_FEEDBACK",
  SET_CHAT_HISTORY: "SET_CHAT_HISTORY",
};

export const chatReducer = (state, action) => {
  switch (action.type) {
    case actionTypes.ADD_CHAT_ITEM:
      return [...state, action.payload];

    case actionTypes.CLEAR_CHAT:
      return [];

    case actionTypes.DELETE_CHAT_ITEM: {
      const { resultIndex } = action.payload;
      return state.map((r, i) => i === resultIndex ? { ...r, isExiting: true } : r);
    }

    case actionTypes.PURGE_EXITING_ITEMS: {
      return state.filter((r) => !r.isExiting);
    }

    case actionTypes.SET_CHAT_ITEM_FEEDBACK: {
      const { resultIndex, feedback, feedbackDetails } = action.payload;
      return state.map((r, i) =>
        i === resultIndex ? { ...r, feedback, feedbackDetails } : r
      );
    }

    case actionTypes.UPDATE_CHAT_ITEM_TEXT: {
      const { resultIndex, text } = action.payload;
      return state.map((r, i) => {
        if (i !== resultIndex) return r;
        const blocks = Array.isArray(r.blocks) ? [...r.blocks] : [];
        const last = blocks[blocks.length - 1];
        if (last && last.type === 'message') {
          last.content = (last.content || '') + text;
        } else {
          blocks.push({ type: 'message', content: text });
        }
        return { ...r, result: (r.result || '') + text, blocks };
      });
    }

    case actionTypes.TOOL_CALL_START: {
      const { resultIndex, toolCall } = action.payload;
      return state.map((r, i) => {
        if (i !== resultIndex) return r;
        const blocks = Array.isArray(r.blocks)
          ? [...r.blocks, { type: 'tool', ...toolCall }]
          : [{ type: 'tool', ...toolCall }];
        return {
          ...r,
          toolCalls: [...(r.toolCalls || []), toolCall],
          blocks,
        };
      });
    }

    case actionTypes.TOOL_CALL_END: {
      const { resultIndex, toolName, toolCallId, content, artifact } = action.payload;
      return state.map((r, i) => {
        if (i !== resultIndex) return r;
        const hasError = artifact && artifact.error;

        const updatedCalls = (r.toolCalls || []).map((c) =>
          c.toolCallId === toolCallId
            ? { ...c, status: hasError ? 'error' : 'finished', contentToLLM: content, artifact: artifact || {} }
            : c
        );

        const blocks = Array.isArray(r.blocks)
          ? r.blocks.map((b) =>
              b.type === 'tool' && b.toolCallId === toolCallId
                ? { ...b, status: hasError ? 'error' : 'finished', contentToLLM: content, artifact: artifact || {} }
                : b
            )
          : [];

        let combined = new Set(r.combinedTablesUsed || []);
        // data_agent: backwards compatibility for chats saved before it was split into generate_vql / execute_vql / generate_graph
        const isVqlTool = ['generate_vql', 'execute_vql', 'generate_graph', 'data_agent'].includes(toolName);
        // Searched views come from metadata_search (or the VQL tools'
        // tables_used); used views are later matched against the VQL.
        // Collect from any artifact that carries them, mirroring the
        // history rebuild in useChatHistory.
        if (artifact && Array.isArray(artifact.tables_used)) {
          for (const t of artifact.tables_used) combined.add(t);
        }
        if (artifact && Array.isArray(artifact.related_tables)) {
          for (const entry of artifact.related_tables) {
            if (entry && entry.view_name) combined.add(entry.view_name);
          }
        }

        let combinedVqls = Array.isArray(r.combinedVqls) ? [...r.combinedVqls] : [];
        if (isVqlTool && artifact && artifact.vql) {
          combinedVqls.push(String(artifact.vql));
        }

        return {
          ...r,
          toolCalls: updatedCalls,
          blocks,
          combinedTablesUsed: Array.from(combined),
          combinedVqls,
        };
      });
    }

    case actionTypes.COMPLETE_CHAT_ITEM: {
      const { resultIndex, payload } = action.payload;
      return state.map((r, i) => {
        if (i !== resultIndex) return r;
        const rel = payload.related_questions || [];
        const relDeepQuery = payload.related_questions_deepquery || [];
        return {
          ...r,
          isLoading: false,
          uuid: payload.uuid || r.uuid,
          relatedQuestions: rel,
          relatedQuestionsDeepQuery: relDeepQuery,
          chatbot_llm: payload.chatbot_llm || r.chatbot_llm,
        };
      });
    }

    case actionTypes.ERROR_CHAT_ITEM: {
      const { resultIndex, message, errorDetails } = action.payload;
      return state.map((r, i) =>
        i === resultIndex
          ? {
              ...r,
              isLoading: false,
              result: message,
              isError: true,
              errorMessage: message,
              errorDetails: errorDetails || message,
            }
          : r
      );
    }

    case actionTypes.SET_CHAT_HISTORY:
      return action.payload;

    default:
      return state;
  }
};

// Number formats the user can pick in the User Profile modal.
// The key is both the label shown in the dropdown and the value stored for that user.
export const NUMBER_FORMATS = {
  '1,234.56': { thousands: ',', decimal: '.' },
  '1.234,56': { thousands: '.', decimal: ',' },
};

export const DEFAULT_NUMBER_FORMAT = '1,234.56';

// Picks the number format that matches the browser locale.
// The decimal separator is checked instead of the thousands separator because some locales
// do not group four-digit numbers (es-ES shows 1000, not 1.000) and others group with a space
// or an apostrophe (fr-FR, de-CH) while still using a comma as the decimal separator.
export const inferNumberFormat = () => {
  try {
    const decimal = new Intl.NumberFormat().formatToParts(1.5).find((part) => part.type === 'decimal');
    return decimal?.value === ',' ? '1.234,56' : '1,234.56';
  } catch {
    return DEFAULT_NUMBER_FORMAT;
  }
};

export const getNumberFormat = () => inferNumberFormat();

// Formats a number with the thousands and decimal separators of the given number format.
// Returns null when the value is not a number so callers can show their own fallback.
export const formatNumber = (value, numberFormat, decimals = 0) => {
  if (value == null || value === '') return null;
  const number = Number(value);
  if (!Number.isFinite(number)) return null;

  const separators = NUMBER_FORMATS[numberFormat] || NUMBER_FORMATS[DEFAULT_NUMBER_FORMAT];
  const enUS = number.toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
  return enUS.replace(/[,.]/g, (char) => (char === ',' ? separators.thousands : separators.decimal));
};

// Helpers to turn DeepQuery report HTML into downloadable files.

export const buildReportFilename = (title, fallback = "deepquery") => {
  const safeTitle = (title || "")
    .trim()
    .replace(/[/\\?%*:|"<>]/g, "")
    .replace(/\s+/g, "_");
  return `${safeTitle || fallback}_report.html`;
};

export const downloadHtmlFile = (html, title, fallback) => {
  const blob = new Blob([html], { type: "text/html;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = buildReportFilename(title, fallback);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  // Revoke on the next tick so the browser has started the download
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};

/**
 * Builds the Data Marketplace link for a view returned by the AI SDK.
 */
export const buildViewCatalogUrl = (dataCatalogUrl, table) => {
  if (!dataCatalogUrl || !table) {
    return null;
  }

  const cleanTable = String(table).replace(/"/g, "");
  const separatorIndex = cleanTable.indexOf(".");
  const database =
    separatorIndex === -1 ? cleanTable : cleanTable.slice(0, separatorIndex);
  const viewName =
    separatorIndex === -1 ? cleanTable : cleanTable.slice(separatorIndex + 1);

  return `${dataCatalogUrl}/#/view/${database}/${viewName}`;
};

export default buildViewCatalogUrl;

// Shared logic for deciding which searched views an answer actually used.
//
// The candidate views come from the AI SDK artifact `tables_used` (the views
// returned by the vector search). A view counts as used when the generated
// VQL references it as "db"."view" (see isViewUsedInVql).

export const cleanViewName = (name) => String(name || "").replace(/"/g, "").trim();

const normalizeViewName = (name) => cleanViewName(name).toLowerCase();

// A view is used when the VQL references it as "db"."view". Checking the
// quoted form (with a bare db.view fallback on word boundaries) avoids
// prefix false positives such as `loan` matching inside `loan_officer`.
function isViewUsedInVql(normalizedTable, rawVql, cleanVql) {
  const quoted = normalizedTable
    .split(".")
    .map((part) => `"${part}"`)
    .join(".");
  if (rawVql.includes(quoted)) return true;
  const escaped = normalizedTable.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`(^|[^a-z0-9_])${escaped}([^a-z0-9_]|$)`).test(cleanVql);
}

export function splitUsedTables(tables, vql, extraViews) {
  let rawVql = "";
  if (Array.isArray(vql)) {
    rawVql = vql.filter(Boolean).map((entry) => String(entry).toLowerCase()).join(" ");
  } else if (vql) {
    rawVql = String(vql).toLowerCase();
  }
  const cleanVql = rawVql.replace(/"/g, "");

  // extraViews: views already known (e.g. in the context window) that were
  // not searched for this answer. The agent may reuse their schemas without
  // a new metadata_search, so they can still be the used ones. They only
  // ever join the used side; the unused side stays the searched views.
  const usedTables = [];
  const seenUsed = new Set();
  const markUsed = (table) => {
    const key = normalizeViewName(table);
    if (key && !seenUsed.has(key)) {
      seenUsed.add(key);
      usedTables.push(table);
    }
  };

  const unusedTables = [];
  (tables || []).forEach((table) => {
    if (!normalizeViewName(table)) return;
    if (isViewUsedInVql(normalizeViewName(table), rawVql, cleanVql)) {
      markUsed(table);
    } else {
      unusedTables.push(table);
    }
  });
  (extraViews || []).forEach((view) => {
    const name = typeof view === "string" ? view : view && view.name;
    if (name && isViewUsedInVql(normalizeViewName(name), rawVql, cleanVql)) {
      markUsed(name);
    }
  });
  return { usedTables, unusedTables };
}

// Map of normalized view name -> token count, built from the live context
// window usage views. Views from older answers may no longer be in context,
// in which case they simply have no token count to show.
export function buildViewTokenLookup(contextViews) {
  const lookup = new Map();
  for (const view of contextViews || []) {
    if (view && view.name != null && view.tokens) {
      lookup.set(normalizeViewName(view.name), view.tokens);
    }
  }
  return lookup;
}

export function viewTokens(table, lookup) {
  if (!lookup) return null;
  const tokens = lookup.get(normalizeViewName(table));
  return tokens == null ? null : tokens;
}

