"""
Memory endpoints for the sample chatbot.

Every logged-in user can list, read, update, and delete the memories they
own for the current agent: 'user' (no link) and 'user-metadata' (personal,
linked). 'metadata' (a fact about the metadata, linked) belongs to the user
and is listed for every agent. Only the agent creates memories. There is no
admin memory UI, but two resource endpoints below stay available to admins
at the API level for a future enhancement where an AI agent will propose semantic layer improvements
based on the user's memories.
"""

import logging

from flask import Blueprint, request, jsonify
from flask_login import login_required, current_user

from sample_chatbot.engine.memory import (
    MemoryError,
    delete_memory,
    is_memory_enabled,
    list_memories,
    list_metadata_for_resource,
    metadata_link_index,
    read_memory,
    set_memory_enabled,
    user_index_status,
    write_memory,
)
from sample_chatbot.routes.skills import _invalidate_chatbot_if_current, _resolve_agent_config

logger = logging.getLogger(__name__)

memory_bp = Blueprint("memory", __name__)

def _user():
    return current_user._get_current_object()

def _is_admin(user):
    return user.is_admin

def _current_config(user, agent_id=None):
    """Config of the agent whose memories are being viewed (default: current)."""
    return _resolve_agent_config(user, agent_id)

def _share_general(config):
    return config.share_general_memory

def _resolve_scope(user, raw_scope):
    """Config for a client-supplied memory scope; the current agent by default."""
    scope = (raw_scope or "").strip()
    return _resolve_agent_config(user, scope or None)

@memory_bp.route("/api/memories", methods=["GET"])
@login_required
def list_user_memories():
    """List the memories owned by the current user for an agent."""
    user = _user()
    memory_type = (request.args.get("type") or "").strip() or None
    try:
        config = _current_config(user, request.args.get("agent_id"))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403
    try:
        memories = list_memories(
            user.id,
            memory_type=memory_type,
            link_kind=request.args.get("link_kind"),
            link_name=request.args.get("link_name"),
            query=request.args.get("q"),
            agent_id=config.id,
            include_shared_general=_share_general(config),
        )
        index = user_index_status(user.id, config.id, _share_general(config))
    except MemoryError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    return jsonify({
        "success": True,
        "is_admin": _is_admin(user),
        "agent_id": config.id,
        "share_general_memory": _share_general(config),
        "memories": memories,
        "index": index,
    })

@memory_bp.route("/api/memories/by_resource", methods=["GET"])
@login_required
def list_resource_memories():
    """List metadata memories attached to a view, database, or tag."""
    user = _user()
    if not _is_admin(user):
        return jsonify({"success": False, "error": "Only an admin can browse metadata memories for a resource."}), 403
    try:
        memories = list_metadata_for_resource(
            request.args.get("kind"),
            request.args.get("name"),
        )
    except MemoryError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    return jsonify({"success": True, "memories": memories})

@memory_bp.route("/api/memories/links", methods=["GET"])
@login_required
def metadata_links():
    """Databases, tags, and views that already have a metadata memory."""
    user = _user()
    if not _is_admin(user):
        return jsonify({"success": False, "error": "Only an admin can browse metadata memories for a resource."}), 403
    try:
        index = metadata_link_index()
    except MemoryError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    return jsonify({"success": True, **index})

@memory_bp.route("/api/memories/activation", methods=["GET"])
@login_required
def memory_activation():
    """Whether memory formation is on for the current user on an agent."""
    user = _user()
    try:
        config = _resolve_agent_config(user, request.args.get("agent_id"))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403
    return jsonify({
        "success": True,
        "active": is_memory_enabled(user.id, config.id),
        "agent_id": config.id,
    })

@memory_bp.route("/api/memories/activation", methods=["POST"])
@login_required
def set_memory_activation():
    """Turn memory formation on or off for the current user on an agent."""
    user = _user()
    data = request.get_json() or {}
    try:
        config = _resolve_agent_config(user, data.get("agent_id"))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403
    active = bool(data.get("active", True))
    set_memory_enabled(user.id, config.id, active)
    _invalidate_chatbot_if_current(user, config)
    logger.info(f"User '{user.id}' set memory formation to {active} for agent '{config.id}'.")
    return jsonify({"success": True, "active": active, "agent_id": config.id})

@memory_bp.route("/api/memories/<memory_type>/<name>", methods=["GET"])
@login_required
def get_memory(memory_type, name):
    """Return one memory owned by the current user.

    ``agent_id`` names the scope the memory lives in (the UI passes the
    listed record's agent). Without it, the current agent is searched,
    including the general agent's shared kinds when sharing is on.
    """
    user = _user()
    scope = (request.args.get("agent_id") or "").strip()
    try:
        config = _resolve_scope(user, scope)
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403
    try:
        if scope:
            memory = read_memory(user.id, memory_type, name, agent_id=config.id)
        else:
            memory = read_memory(
                user.id, memory_type, name,
                agent_id=config.id, include_shared_general=_share_general(config),
            )
    except MemoryError as exc:
        message = str(exc)
        status = 404 if message.startswith("No ") else 400
        return jsonify({"success": False, "error": message}), status
    return jsonify({"success": True, "memory": memory})

@memory_bp.route("/api/memories", methods=["POST"])
@login_required
def save_memory():
    """Replace a memory the agent already created for the current user."""
    user = _user()
    data = request.get_json() or {}
    try:
        config = _resolve_scope(user, data.get("agent_id"))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403
    try:
        result = write_memory(
            user.id,
            data.get("memory_type"),
            data.get("name"),
            data.get("description"),
            data.get("body"),
            links=data.get("links"),
            allow_create=False,
            agent_id=config.id,
        )
    except MemoryError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    logger.info(f"User '{user.id}' saved {data.get('memory_type')} memory '{data.get('name')}'.")
    return jsonify({"success": True, **result})

@memory_bp.route("/api/memories/<memory_type>/<name>", methods=["DELETE"])
@login_required
def remove_memory(memory_type, name):
    """Delete a memory owned by the current user from one agent's scope."""
    user = _user()
    try:
        config = _resolve_scope(user, request.args.get("agent_id"))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403
    try:
        result = delete_memory(user.id, memory_type, name, agent_id=config.id)
    except MemoryError as exc:
        message = str(exc)
        status = 404 if message.startswith("No ") else 400
        return jsonify({"success": False, "error": message}), status
    return jsonify({"success": True, **result})

"""
DeepQuery report endpoints.

Reports are generated by background jobs (see services/report_jobs.py) and
persisted in the chatbot database. These endpoints let the UI poll the status,
cancel running jobs, create language variants and read or delete reports.
Every endpoint is scoped to the logged-in user.
"""

import json
import logging

from flask import Blueprint, request, jsonify
from flask_login import login_required, current_user

from utils.database_utils import DeepQueryReports
from sample_chatbot.config import get_config
from sample_chatbot.services.report_jobs import (
    ReportJobContext,
    ReportNotFoundError,
    ReportLimitError,
    ReportQueueFullError,
    VariantUnavailableError,
    get_max_reports_per_user,
    report_job_manager,
)

logger = logging.getLogger(__name__)

reports_bp = Blueprint('reports', __name__)

_PRIVATE_FIELDS = ("user_id", "agent_id")

def _user():
    """Resolve the underlying user (not the LocalProxy)."""
    return current_user._get_current_object()

def _public_report(report):
    """Report info safe to send to the browser (no owner columns)."""
    return {key: value for key, value in report.items() if key not in _PRIVATE_FIELDS}

def _job_context(user):
    """Job context from the logged-in user's session (the password stays in memory only)."""
    config = get_config(user.agent_id)
    chatbot = user.get_or_create_chatbot()
    return ReportJobContext(
        user_id=user.id,
        password=user.password,
        agent_id=user.agent_id,
        api_host=config.ai_sdk_host,
        verify_ssl=config.ai_sdk_verify_ssl,
        timeout=config.chatbot_timeout,
        ai_sdk_params=dict(chatbot.ai_sdk_params or {}),
    )

def _not_found():
    return jsonify({"success": False, "error": "Report not found."}), 404

def _queue_full(error):
    return jsonify({"success": False, "error": str(error), "code": "queue_full"}), 503

def _limit_reached(error):
    return jsonify({"success": False, "error": str(error), "code": "report_limit", "limit": get_max_reports_per_user()}), 409

@reports_bp.route('/api/reports/status', methods=['GET'])
@login_required
def reports_status():
    """List all the user's reports (any agent) and the per-user report limit. Never returns HTML or metadata."""
    user = _user()
    reports = DeepQueryReports.list_reports(user.id)
    return jsonify({
        "reports": [_public_report(report) for report in reports],
        "limit": get_max_reports_per_user(),
    })

@reports_bp.route('/api/reports/<report_id>/html', methods=['GET'])
@login_required
def report_html(report_id):
    """Return the stored HTML of a completed report."""
    user = _user()
    report = DeepQueryReports.get_report_html(report_id, user.id)
    if report is None:
        return _not_found()
    if not report["html"]:
        return jsonify({"success": False, "error": "The report is not ready yet."}), 409
    return jsonify({"html_report": report["html"], "title": report["title"]})

@reports_bp.route('/api/reports/<report_id>/analysis', methods=['GET'])
@login_required
def report_analysis(report_id):
    """Return the question and stored deepquery_metadata (VQL, tables, graphs) behind a report."""
    user = _user()
    report = DeepQueryReports.get_report(report_id, user.id)
    if not report:
        return _not_found()

    analysis = DeepQueryReports.get_analysis(report["analysis_id"], user.id)
    if not analysis or not analysis.get("metadata"):
        return jsonify({"success": False, "error": "The analysis data is not available (yet)."}), 409
    return jsonify({
        "question": analysis["question"],
        "title": analysis.get("title") or report["title"],
        "deepquery_metadata": analysis["metadata"],
    })

@reports_bp.route('/api/reports/<report_id>/cancel', methods=['POST'])
@login_required
def cancel_report(report_id):
    """Cancel a pending or running report."""
    user = _user()
    try:
        cancelled = report_job_manager.cancel(report_id, user.id)
    except ReportNotFoundError:
        return _not_found()
    if not cancelled:
        return jsonify({"success": False, "error": "Only pending or running reports can be cancelled."}), 409
    return jsonify({"success": True})

@reports_bp.route('/api/reports/<report_id>/variant', methods=['POST'])
@login_required
def create_variant(report_id):
    """Generate the same analysis in another language, reusing the stored data."""
    user = _user()
    data = request.get_json(silent=True) or {}
    language = (data.get('language') or '').strip()
    if not language:
        return jsonify({"success": False, "error": "Missing language."}), 400

    ctx = _job_context(user)

    try:
        report = report_job_manager.variant(ctx, report_id, language)
    except ReportNotFoundError:
        return _not_found()
    except VariantUnavailableError as e:
        return jsonify({"success": False, "error": str(e)}), 409
    except ReportLimitError as e:
        return _limit_reached(e)
    except ReportQueueFullError as e:
        return _queue_full(e)
    except ValueError as e:
        return jsonify({"success": False, "error": str(e)}), 400

    return jsonify({"success": True, "report": _public_report(report)}), 201

@reports_bp.route('/api/reports', methods=['POST'])
@login_required
def create_reports():
    """Queue a new DeepQuery analysis (one report per language) from its question."""
    user = _user()
    data = request.get_json(silent=True) or {}
    question = str(data.get('question') or '').strip()[:4000]
    if not question:
        return jsonify({"success": False, "error": "Missing question."}), 400
    if not user.password:
        return jsonify({"success": False, "error": "Your session cannot be used to generate the report. Please log in again."}), 409

    try:
        _, reports = report_job_manager.submit(_job_context(user), question, data.get('languages'))
    except ReportLimitError as e:
        return _limit_reached(e)
    except ReportQueueFullError as e:
        return _queue_full(e)
    except ValueError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    created = [DeepQueryReports.get_report(report['report_id'], user.id) for report in reports]
    return jsonify({"success": True, "reports": [_public_report(report) for report in created if report]}), 201

@reports_bp.route('/api/reports/<report_id>/retry', methods=['POST'])
@login_required
def retry_report(report_id):
    """Re-run a failed or cancelled report in place."""
    user = _user()
    if not user.password:
        return jsonify({"success": False, "error": "Your session cannot be used to retry this report. Please log in again."}), 409
    try:
        report = report_job_manager.retry(_job_context(user), report_id)
    except ReportNotFoundError:
        return _not_found()
    except ReportQueueFullError as e:
        return _queue_full(e)
    except (VariantUnavailableError, ValueError) as e:
        return jsonify({"success": False, "error": str(e)}), 409
    return jsonify({"success": True, "report": _public_report(report)})

_MAX_LEGACY_METADATA_BYTES = 30 * 1024 * 1024

@reports_bp.route('/api/reports/from-legacy', methods=['POST'])
@login_required
def report_from_legacy():
    """Create a report from the deepquery_metadata of a chat message generated before async reports."""
    user = _user()
    data = request.get_json(silent=True) or {}
    metadata = data.get('deepquery_metadata')
    question = str(data.get('question') or '')[:4000]
    language = (data.get('language') or '').strip()

    if not isinstance(metadata, dict) or not metadata:
        return jsonify({"success": False, "error": "Missing deepquery_metadata."}), 400
    if len(json.dumps(metadata, default=str)) > _MAX_LEGACY_METADATA_BYTES:
        return jsonify({"success": False, "error": "deepquery_metadata is too large."}), 413
    if not user.password:
        return jsonify({"success": False, "error": "Your session cannot be used to generate the report. Please log in again."}), 409

    try:
        report = report_job_manager.submit_from_legacy(_job_context(user), question, metadata, language)
    except ReportLimitError as e:
        return _limit_reached(e)
    except ReportQueueFullError as e:
        return _queue_full(e)
    except ValueError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    return jsonify({"success": True, "report": _public_report(report)}), 201

@reports_bp.route('/api/reports/<report_id>', methods=['DELETE'])
@login_required
def delete_report(report_id):
    """Delete a report (cancelling it first if it is still running)."""
    user = _user()
    if not report_job_manager.delete(report_id, user.id):
        return _not_found()
    return jsonify({"success": True})

@reports_bp.route('/api/reports', methods=['DELETE'])
@login_required
def delete_all_reports():
    """Delete every report of the user."""
    user = _user()
    deleted = report_job_manager.delete_all(user.id)
    return jsonify({"success": True, "deleted": deleted})

"""
Handles user settings, custom instructions, and LLM configuration endpoints.
"""

import logging

from flask import Blueprint, request, jsonify
from flask_login import login_required, current_user

from sample_chatbot.config import get_config
from sample_chatbot.services.ui_preferences import (
    agent_row,
    drop_saved_llm,
    save_agent_instructions,
    save_agent_llm,
    save_profile,
    validate_llm_settings,
)

settings_bp = Blueprint('settings', __name__)

@settings_bp.route('/api/config', methods=['GET'])
def get_frontend_config():
    """Endpoint to expose configuration variables to the frontend."""

    agent_id = 'global' if not current_user.is_authenticated else current_user.agent_id

    config = get_config(agent_id)

    from sample_chatbot.engine.context import TOOL_DEFINITIONS

    frontend_config = {
        "has_ai_sdk_credentials": config.has_ai_sdk_credentials,
        "allow_sync": config.allow_sync,
        "chatbot_feedback": config.effective_feedback_enabled,
        "unstructured_mode": config.unstructured_mode,
        "user_edit_llm": config.user_edit_llm,
        "enable_deep_query": config.deepquery_enabled,
        "input_method": config.input_method,
        "chatbot_tools": [
            {
                "name": name,
                "pretty_name": tool_cfg["pretty_name"],
                "aliases": tool_cfg["aliases"],
                "optional": tool_cfg["optional"],
                "tool_public_text_key": tool_cfg["tool_public_text_key"],
            }
            for name, tool_cfg in TOOL_DEFINITIONS.items()
        ],
    }

    frontend_config["chatbot_llm_defaults"] = {
        "provider": config.llm_provider.lower(),
        "model": config.llm_model,
        "temperature": config.llm_temperature,
        "max_tokens": config.llm_max_tokens,
        "context_window": config.llm_context_window,
    }

    if config.data_marketplace_url:
        frontend_config["data_marketplace_url"] = config.data_marketplace_url.rstrip('/')

    frontend_config["default_custom_instructions"] = {
        "ai_sdk": config.custom_instructions_ai_sdk,
        "chatbot": config.custom_instructions_chatbot,
    }
    frontend_config["can_edit_instructions"] = config.user_edit_instructions

    if current_user.is_authenticated and current_user.ai_sdk_info:
        frontend_config["embeddings_token_limit"] = current_user.ai_sdk_info.get("embeddings_token_limit", 0)
    else:
        frontend_config["embeddings_token_limit"] = 0

    frontend_config["is_admin"] = bool(
        current_user.is_authenticated and current_user.is_admin
    )

    return jsonify(frontend_config)

@settings_bp.route('/api/update_custom_instructions', methods=['POST'])
@login_required
def update_custom_instructions():
    """Update user's custom instructions and profile."""
    data = request.json or {}
    custom_instructions = data.get("custom_instructions")
    instruction_entries = None
    if custom_instructions is not None:
        try:
            instruction_entries = _instruction_entries(custom_instructions, data.get("agent_id"))
        except PermissionError as e:
            return jsonify({"error": str(e)}), 403
        except LookupError:
            return jsonify({"error": "Unknown agent."}), 404

    save_profile(
        current_user.id,
        user_details=data.get("user_details") if "user_details" in data else None,
        input_method=data.get("input_method"),
        number_format=data.get("number_format"),
    )
    if "user_details" in data:
        current_user.user_details = data.get("user_details") or ""
        current_user.chatbot = None

    if instruction_entries is not None:
        for agent_id, entry in instruction_entries.items():
            saved_entry = save_agent_instructions(current_user.id, agent_id, entry)
            if agent_id == current_user.agent_id:
                current_user.merge_custom_instructions_for_agent(agent_id, saved_entry)

    return jsonify({"message": "Profile updated successfully"}), 200

def _instruction_entries(custom_instructions, requested_agent):
    """Return {agent_id: entry} after checking each agent can take the edit."""
    if isinstance(custom_instructions, dict) and set(custom_instructions.keys()) <= {"ai_sdk", "chatbot"}:
        config = _require_editable_instructions(requested_agent)
        return {config.id: custom_instructions}

    from sample_chatbot.models.user import _normalize_instruction_map
    normalized = _normalize_instruction_map(custom_instructions)
    entries = {}
    for agent_id, entry in normalized.items():
        config = _require_editable_instructions(agent_id)
        entries[config.id] = entry
    return entries

def _require_editable_instructions(agent_id):
    """Return the agent config, or raise when this user cannot edit its instructions."""
    try:
        config = _resolve_settings_agent(agent_id)
    except PermissionError:
        raise PermissionError("You are not allowed to use this agent.")
    if config is None:
        raise LookupError(agent_id)
    if not config.user_edit_instructions:
        raise PermissionError("Instruction editing is not enabled.")
    return config

@settings_bp.route('/api/llm_settings', methods=['GET'])
@login_required
def get_llm_settings():
    """Return the user's current LLM preferences and cached AI SDK configuration.

    Accepts an optional agent_id so the per-agent Settings modal can show any
    agent's defaults without switching agents. Session preferences only apply
    to the user's current agent; for other agents the frontend falls back to
    its stored per-agent settings.
    """
    agent_id = 'global' if not current_user.is_authenticated else current_user.agent_id

    requested_agent = request.args.get('agent_id')
    is_current_agent = not requested_agent or requested_agent == agent_id
    if not is_current_agent:
        from sample_chatbot import config as chatbot_configs
        requested_config = chatbot_configs._configs.get(requested_agent)
        if requested_config is None:
            return jsonify({"success": False, "error": "Unknown agent."}), 404
        if not requested_config.is_user_allowed(
            username=current_user.id,
            roles=current_user.roles,
            is_admin=current_user.is_admin,
            legacy_permissions_endpoint=current_user.legacy_permissions_endpoint,
        ):
            return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403
        agent_id = requested_agent

    config = get_config(agent_id)

    ai_sdk_base_llm_defaults = {}
    if config.ai_sdk_base_llm_model:
        ai_sdk_base_llm_defaults = {
            "provider": config.ai_sdk_base_llm_provider,
            "model": config.ai_sdk_base_llm_model,
            "temperature": config.ai_sdk_base_llm_temperature,
            "max_tokens": config.ai_sdk_base_llm_max_tokens,
        }

    ai_sdk_thinking_llm_defaults = {}
    if config.ai_sdk_thinking_llm_model:
        ai_sdk_thinking_llm_defaults = {
            "provider": config.ai_sdk_thinking_llm_provider,
            "model": config.ai_sdk_thinking_llm_model,
            "temperature": config.ai_sdk_thinking_llm_temperature,
            "max_tokens": config.ai_sdk_thinking_llm_max_tokens,
        }

    sdk_info = current_user.ai_sdk_info or {}
    agent_check_ambiguity = config.check_ambiguity
    check_ambiguity_default = (
        agent_check_ambiguity if agent_check_ambiguity is not None
        else sdk_info.get("check_ambiguity", True)
    )
    saved = agent_row(current_user.id, agent_id)
    saved_llm = saved.get("llm_settings") or {}
    if is_current_agent:
        chatbot_prefs = current_user.chatbot_llm_preferences
        base_prefs = current_user.ai_sdk_base_llm_preferences
        thinking_prefs = current_user.ai_sdk_thinking_llm_preferences
        check_ambiguity = current_user.check_ambiguity
        auto_fixing = current_user.auto_fixing
        auto_fixing_attempts = current_user.auto_fixing_attempts
        use_base = current_user.use_base_llm_for_execution
    else:
        chatbot_prefs = saved_llm.get("chatbot_llm") or {}
        base_prefs = saved_llm.get("ai_sdk_base_llm") or {}
        thinking_prefs = saved_llm.get("ai_sdk_thinking_llm") or {}
        check_ambiguity = saved_llm.get("check_ambiguity")
        auto_fixing = saved_llm.get("auto_fixing")
        auto_fixing_attempts = saved_llm.get("auto_fixing_attempts")
        use_base = saved_llm.get("use_base_llm_for_execution")
    return jsonify({
        "chatbot_llm_defaults": {
            "provider": config.llm_provider.lower(),
            "model": config.llm_model,
            "temperature": config.llm_temperature,
            "max_tokens": config.llm_max_tokens,
            "context_window": config.llm_context_window,
        },
        "ai_sdk_base_llm_defaults": ai_sdk_base_llm_defaults,
        "ai_sdk_thinking_llm_defaults": ai_sdk_thinking_llm_defaults,
        "use_base_llm_for_execution_default": config.use_base_llm_for_execution,
        "check_ambiguity_default": check_ambiguity_default,
        "auto_fixing_default": sdk_info.get("auto_fixing", True),
        "auto_fixing_attempts_default": sdk_info.get("auto_fixing_attempts", 2),
        "use_base_llm_for_execution": use_base,
        "chatbot_llm_preferences": chatbot_prefs,
        "ai_sdk_base_llm_preferences": base_prefs,
        "ai_sdk_thinking_llm_preferences": thinking_prefs,
        "check_ambiguity": check_ambiguity,
        "auto_fixing": auto_fixing,
        "auto_fixing_attempts": auto_fixing_attempts,
        "custom_instructions": saved.get("custom_instructions"),
        "user_edit_llm": config.user_edit_llm,
        "user_edit_instructions": config.user_edit_instructions,
        "ai_sdk_info": current_user.ai_sdk_info,
        "chatbot_deepquery": config.deepquery_enabled,
        "default_custom_instructions": {
            "ai_sdk": config.custom_instructions_ai_sdk,
            "chatbot": config.custom_instructions_chatbot,
        },
    }), 200

@settings_bp.route('/api/reset_llm_settings', methods=['POST'])
@login_required
def reset_llm_settings():
    """Reset all user LLM preferences back to server defaults."""
    agent_id = 'global' if not current_user.is_authenticated else current_user.agent_id

    config = get_config(agent_id)

    if not config.user_edit_llm:
        return jsonify({"error": "LLM editing is not enabled"}), 403

    # Determine which component to reset based on the request body
    data = request.json or {}
    component = data.get('component', 'all')

    if component in ('chatbot', 'all'):
        current_user.chatbot_llm_preferences = {}

    if component in ('ai_sdk', 'all'):
        current_user.ai_sdk_base_llm_preferences = {}
        if config.ai_sdk_base_llm_model:
            current_user.ai_sdk_base_llm_preferences = {
                'provider': config.ai_sdk_base_llm_provider,
                'model': config.ai_sdk_base_llm_model,
                'temperature': config.ai_sdk_base_llm_temperature,
                'max_tokens': config.ai_sdk_base_llm_max_tokens
            }

        current_user.ai_sdk_thinking_llm_preferences = {}
        if config.ai_sdk_thinking_llm_model:
            current_user.ai_sdk_thinking_llm_preferences = {
                'provider': config.ai_sdk_thinking_llm_provider,
                'model': config.ai_sdk_thinking_llm_model,
                'temperature': config.ai_sdk_thinking_llm_temperature,
                'max_tokens': config.ai_sdk_thinking_llm_max_tokens
            }

        current_user.apply_ai_sdk_defaults()

    drop_saved_llm(current_user.id, agent_id, component)

    # Reset chatbot to force recreation with default settings
    current_user.chatbot = None

    return jsonify({"message": "LLM settings reset to defaults"}), 200

@settings_bp.route('/api/update_llm_settings', methods=['POST'])
@login_required
def update_llm_settings():
    """Update user's LLM preferences and store them for the next session."""
    data = request.json or {}
    requested_agent = data.get("agent_id")
    try:
        config = _resolve_settings_agent(requested_agent)
    except PermissionError:
        return jsonify({"error": "You are not allowed to use this agent."}), 403
    if config is None:
        return jsonify({"error": "Unknown agent."}), 404

    if not config.user_edit_llm:
        return jsonify({"error": "LLM editing is not enabled"}), 403

    payload = {key: value for key, value in data.items() if key != "agent_id"}

    try:
        if config.id == current_user.agent_id:
            current_user.update_llm_preferences(payload)
            # A null value means "drop this override". update_llm_preferences
            # leaves the previous value in place when the key is null.
            if "ai_sdk_thinking_llm" in payload and payload["ai_sdk_thinking_llm"] is None:
                current_user.ai_sdk_thinking_llm_preferences = {}
            if "use_base_llm_for_execution" in payload and payload["use_base_llm_for_execution"] is None:
                current_user.use_base_llm_for_execution = config.use_base_llm_for_execution
            current_user.chatbot = None
        else:
            validate_llm_settings(config, payload)
        save_agent_llm(current_user.id, config.id, payload)
        return jsonify({"message": "LLM settings updated successfully"}), 200

    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        return jsonify({"error": f"Invalid input: {str(e)}"}), 400

def _resolve_settings_agent(agent_id):
    """Return the config for agent_id, or the user's current agent when omitted.

    Raises PermissionError when the user cannot use that agent. Returns None
    when the agent does not exist. Does not create a config for an unknown id.
    """
    from sample_chatbot import config as chatbot_configs

    if not agent_id or agent_id == current_user.agent_id:
        return chatbot_configs._configs.get(current_user.agent_id) or get_config(current_user.agent_id or "global")

    config = chatbot_configs._configs.get(agent_id)
    if config is None:
        return None
    if not config.is_user_allowed(
        username=current_user.id,
        roles=current_user.roles,
        is_admin=current_user.is_admin,
        legacy_permissions_endpoint=current_user.legacy_permissions_endpoint,
    ):
        raise PermissionError(agent_id)
    return config

@settings_bp.route('/api/reset_agent_resources', methods=['POST'])
@login_required
def reset_agent_resources():
    """Restore modifiable skill and knowledge-base toggles for one agent.

    Defaults match a user who has never changed them: user-toggleable skills
    on, user-toggleable knowledge bases off. Agent-managed items stay as the
    agent configured them.
    """
    from utils.database_utils import UserSkills

    data = request.json or {}
    try:
        config = _resolve_settings_agent(data.get('agent_id'))
    except PermissionError:
        return jsonify({"error": "You are not allowed to use this agent."}), 403
    if config is None:
        return jsonify({"error": "Unknown agent."}), 404

    if config.is_unstructured_mode_allowed_for_user(
        username=current_user.id,
        roles=current_user.roles,
        is_admin=current_user.is_admin,
        legacy_permissions_endpoint=current_user.legacy_permissions_endpoint,
    ):
        try:
            from sample_chatbot.services.kb_registry import get_registry_for
            get_registry_for(config).set_active_set(current_user.id, config.id, [])
        except Exception:
            logging.exception(f"[Settings] Could not reset knowledge bases for '{current_user.id}' on '{config.id}'")
            return jsonify({"error": "Knowledge bases could not be reset."}), 500

    UserSkills.clear_agent_prefs(current_user.id, config.id)

    if config.id == current_user.agent_id:
        current_user.chatbot = None

    logging.info(f"[Settings] '{current_user.id}' reset skills and knowledge bases for agent '{config.id}'")
    return jsonify({"message": "Skills and knowledge bases reset to defaults"}), 200

"""
Skills management endpoints.

System skills live on disk under the AI SDK skills/ directory and are shared
by every user; personal skills are created/uploaded per user and stored in the
same database as the conversation history. Every logged-in user can list and
read the skills that apply to them and manage their own personal skills.

Activation is configured per agent from each agent's Settings modal, so the
list/activate endpoints accept an optional agent_id (defaulting to the user's
current agent). System skill files themselves are managed on disk (or via the
chat tools by authorized users), not through these endpoints.
"""

import logging

from flask import Blueprint, request, jsonify
from flask_login import login_required, current_user

from utils.database_utils import UserSkills, UserUiPreferences
from sample_chatbot import config as chatbot_configs
from sample_chatbot.engine import skills as skills_engine
from sample_chatbot.engine.skills import SkillError

logger = logging.getLogger(__name__)

skills_bp = Blueprint('skills', __name__)

UserSkills.init_db()
UserUiPreferences.init_db()

def _user():
    """Resolve the underlying user (not the LocalProxy)."""
    return current_user._get_current_object()

def _resolve_agent_config(user, agent_id):
    """Return the ChatbotConfig for agent_id (default: the user's current agent).

    Raises PermissionError if the user may not use that agent, KeyError if the
    agent does not exist.
    """
    if not agent_id or agent_id == user._config.id:
        return user._config
    # Look up without creating: get_config() would silently instantiate an
    # env-based config for unknown ids.
    config = chatbot_configs._configs.get(agent_id)
    if config is None:
        raise KeyError(agent_id)
    if not config.is_user_allowed(
        username=user.id,
        roles=user.roles,
        is_admin=user.is_admin,
        legacy_permissions_endpoint=user.legacy_permissions_endpoint,
    ):
        raise PermissionError(agent_id)
    return config

def _invalidate_chatbot_if_current(user, config):
    """Rebuild the engine only when the change affects the user's current agent."""
    if config.id == user._config.id:
        user.chatbot = None

@skills_bp.route('/api/skills/list', methods=['GET'])
@login_required
def list_skills():
    """List the skills that apply to the user on an agent (system + personal)."""
    user = _user()
    try:
        config = _resolve_agent_config(user, request.args.get('agent_id'))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403

    merged = skills_engine.discover_skills_for_user(user.id, config.id, config.agent_skills, config.disabled_skills)
    skills_list = [
        {
            "skill_name": name,
            "description": meta["description"],
            "references": meta["references"],
            "scope": meta["scope"],
            "active": meta["active"],
            "agent_managed": meta["agent_managed"],
            "feature_disabled": meta.get("feature_disabled", False),
            "valid": meta.get("valid", True),
            "error": meta.get("error"),
        }
        for name, meta in merged.items()
    ]
    return jsonify({
        "success": True,
        "skills": skills_list,
        "agent_id": config.id,
        "can_manage_skills": config.is_skill_management_allowed_for_user(
            username=user.id,
            roles=user.roles,
            is_admin=user.is_admin,
            legacy_permissions_endpoint=user.legacy_permissions_endpoint,
        ),
    })

@skills_bp.route('/api/skills/read/<skill_name>', methods=['GET'])
@login_required
def read_skill(skill_name):
    """Return the full content of one of the user's skills (personal or system)."""
    user = _user()
    try:
        config = _resolve_agent_config(user, request.args.get('agent_id'))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403

    try:
        # Only expose skills that actually apply to this user/agent.
        merged = skills_engine.discover_skills_for_user(user.id, config.id, config.agent_skills, config.disabled_skills)
        if skill_name not in merged:
            return jsonify({"success": False, "error": f"Skill '{skill_name}' was not found."}), 404
        content = skills_engine.read_skill_for_user(user.id, skill_name)
        return jsonify({
            "success": True,
            "skill_name": skill_name,
            "scope": merged[skill_name]["scope"],
            "content": content,
        })
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400

@skills_bp.route('/api/skills/create', methods=['POST'])
@login_required
def create_skill():
    """Create (or upload) a personal skill for the current user."""
    user = _user()
    data = request.get_json() or {}
    skill_name = (data.get('skill_name') or '').strip()
    content = data.get('content') or ''
    try:
        skills_engine.create_personal_skill(user.id, skill_name, content)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    user.chatbot = None
    logger.info(f"User '{user.id}' created personal skill '{skill_name}'.")
    return jsonify({"success": True, "skill_name": skill_name, "scope": "personal"})

@skills_bp.route('/api/skills/update/<skill_name>', methods=['PUT'])
@login_required
def update_skill(skill_name):
    """Replace the content of one of the current user's personal skills."""
    user = _user()
    data = request.get_json() or {}
    content = data.get('content') or ''
    try:
        skills_engine.update_personal_skill(user.id, skill_name, content)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    user.chatbot = None
    return jsonify({"success": True, "skill_name": skill_name, "scope": "personal"})

@skills_bp.route('/api/skills/delete/<skill_name>', methods=['DELETE'])
@login_required
def delete_skill(skill_name):
    """Delete one of the current user's personal skills."""
    user = _user()
    try:
        skills_engine.delete_personal_skill(user.id, skill_name)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    user.chatbot = None
    logger.info(f"User '{user.id}' deleted personal skill '{skill_name}'.")
    return jsonify({"success": True, "skill_name": skill_name})

@skills_bp.route('/api/skills/activate', methods=['POST'])
@login_required
def activate_skill():
    """Activate/deactivate a skill for the current user on an agent."""
    user = _user()
    data = request.get_json() or {}
    skill_name = (data.get('skill_name') or '').strip()
    active = bool(data.get('active', True))
    try:
        config = _resolve_agent_config(user, data.get('agent_id'))
    except KeyError:
        return jsonify({"success": False, "error": "Unknown agent."}), 404
    except PermissionError:
        return jsonify({"success": False, "error": "You are not allowed to use this agent."}), 403

    try:
        # Only skills that apply to this user/agent can be toggled.
        merged = skills_engine.discover_skills_for_user(user.id, config.id, config.agent_skills, config.disabled_skills)
        if skill_name not in merged:
            return jsonify({"success": False, "error": f"Skill '{skill_name}' was not found."}), 404
        if merged[skill_name].get("feature_disabled"):
            return jsonify({"success": False, "error": f"Skill '{skill_name}' is disabled by this agent's configuration and cannot be activated."}), 400
        if merged[skill_name]["agent_managed"]:
            return jsonify({"success": False, "error": f"Skill '{skill_name}' is managed by this agent and cannot be toggled."}), 400
        skills_engine.set_skill_active(user.id, config.id, skill_name, active)
    except SkillError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    _invalidate_chatbot_if_current(user, config)
    return jsonify({"success": True, "skill_name": skill_name, "active": active, "agent_id": config.id})

"""
Asynchronous DeepQuery report jobs.

The deep_query chat tool only enqueues work here and returns immediately. A
small pool of daemon worker threads runs the two phases of each job by calling
the AI SDK endpoints:

  1. Analysis (once per analysis): /deepQuery extracts the data and returns the
     deepquery_metadata, which is persisted so variants can reuse it.
  2. Report (once per language / variant): /generateDeepQueryReport renders the
     metadata into a themed HTML document, which is persisted too.

Every state change is written to the database (DeepQueryReports) so the UI can
poll it. Cancellation is cooperative and in-memory (threading.Event per report
and per analysis), so it only works within a single chatbot process. The user's
password is held in memory only while a job is queued or running.
"""

import os
import re
import uuid
import queue
import logging
import threading
from dataclasses import dataclass, field

from utils import denodo_tools
from utils.database_utils import DeepQueryReports
from utils.denodo_tools import AISDKRequestCancelled, create_basic_auth_header

logger = logging.getLogger(__name__)

ACTIVE_STATUSES = DeepQueryReports.ACTIVE_STATUSES
MAX_LANGUAGES_PER_REQUEST = 5
DEFAULT_LANGUAGE = "English"
DEFAULT_MAX_REPORTS_PER_USER = 20
DEFAULT_MAX_QUEUE_SIZE = 1000
DEFAULT_COLOR_PALETTE = "red"
MAX_ERROR_LENGTH = 2000

# Same constraints as the AI SDK /generateDeepQueryReport `language` field.
_LANGUAGE_PATTERN = re.compile(r"^[a-zA-Z\u00C0-\u024F\s-]{1,30}$")

# Keys of the chatbot's AI SDK params that are forwarded to /generateDeepQueryReport
LLM_OVERRIDE_KEYS = (
    "llm_provider",
    "llm_model",
    "llm_temperature",
    "llm_max_tokens",
    "thinking_llm_provider",
    "thinking_llm_model",
    "thinking_llm_temperature",
    "thinking_llm_max_tokens",
    "check_ambiguity",
)

class VariantUnavailableError(Exception):
    """The stored analysis has no metadata to generate a new report from."""

class ReportNotFoundError(Exception):
    """The report does not exist or does not belong to the user."""

class ReportQueueFullError(ValueError):
    """The job queue is full; the request cannot be accepted right now."""

class ReportLimitError(ValueError):
    """The user already has the maximum number of stored reports."""

def get_max_reports_per_user():
    """Maximum number of stored reports per user (CHATBOT_MAX_REPORTS_PER_USER, default 20)."""
    try:
        return max(1, int(os.getenv("CHATBOT_MAX_REPORTS_PER_USER", str(DEFAULT_MAX_REPORTS_PER_USER))))
    except ValueError:
        return DEFAULT_MAX_REPORTS_PER_USER

def check_report_limit(user_id, needed=1):
    """Raise ReportLimitError if creating `needed` more reports would exceed the per-user limit."""
    limit = get_max_reports_per_user()
    if DeepQueryReports.count_reports(user_id) + needed > limit:
        raise ReportLimitError(
            f"Report limit reached ({limit} per user). Delete some reports in the DeepQuery Reports Manager to create new ones."
        )

@dataclass
class ReportJobContext:
    """Everything a background job needs; captured when the job is created."""
    user_id: str
    password: str = field(repr=False)
    agent_id: str
    api_host: str
    verify_ssl: bool
    timeout: int
    ai_sdk_params: dict = field(default_factory=dict)
    thread_id: str | None = None

    @classmethod
    def from_user_context(cls, context):
        """Build from the chatbot's per-request UserContext."""
        return cls(
            user_id=context.username,
            password=context.password,
            agent_id=context.agent_id,
            api_host=context.api_host,
            verify_ssl=context.verify_ssl,
            timeout=context.timeout,
            ai_sdk_params=dict(context.ai_sdk_params or {}),
            thread_id=getattr(context, "thread_id", None),
        )

    @property
    def auth(self):
        return create_basic_auth_header(self.user_id, self.password)

def normalize_languages(languages):
    """Trim, validate and de-duplicate (case-insensitive) the requested languages.

    Returns the list of valid languages (default: English). Raises ValueError if
    languages were requested but none of them is valid.
    """
    if isinstance(languages, str):
        languages = [languages]
    requested = [lang for lang in (languages or []) if isinstance(lang, str) and lang.strip()]
    if not requested:
        return [DEFAULT_LANGUAGE]

    result, seen = [], set()
    for lang in requested:
        cleaned = " ".join(lang.split())
        if not _LANGUAGE_PATTERN.match(cleaned):
            continue
        key = cleaned.lower()
        if key not in seen:
            seen.add(key)
            result.append(cleaned)

    if not result:
        raise ValueError(f"Invalid language(s): {', '.join(map(str, requested))}. Use plain language names such as 'English' or 'French'.")
    return result[:MAX_LANGUAGES_PER_REQUEST]

def _truncate_error(message):
    message = str(message or "Unknown error")
    return message if len(message) <= MAX_ERROR_LENGTH else message[:MAX_ERROR_LENGTH] + "..."

def _error_detail(response):
    """Extract a human-readable error from an AI SDK response dict (or None)."""
    if not isinstance(response, dict):
        return None
    detail = response.get("detail") or response.get("error")
    return str(detail) if detail else None

class ReportJobManager:
    """Queues and runs DeepQuery analysis / report jobs on background threads."""

    def __init__(self, max_workers=None):
        if max_workers is None:
            try:
                max_workers = int(os.getenv("CHATBOT_REPORT_MAX_CONCURRENT_JOBS", "4"))
            except ValueError:
                max_workers = 4
        self._max_workers = max(1, max_workers)
        try:
            max_queue = int(os.getenv("CHATBOT_REPORT_MAX_QUEUE_SIZE", str(DEFAULT_MAX_QUEUE_SIZE)))
        except ValueError:
            max_queue = DEFAULT_MAX_QUEUE_SIZE
        self._queue = queue.Queue(maxsize=max(1, max_queue))
        self._workers = []
        self._lock = threading.RLock()
        self._report_events = {}
        self._analysis_events = {}

    # ------------------------------------------------------------------
    # Worker pool
    # ------------------------------------------------------------------

    def _ensure_workers(self):
        with self._lock:
            if self._workers:
                return
            for index in range(self._max_workers):
                worker = threading.Thread(target=self._worker_loop, name=f"dq-report-worker-{index}", daemon=True)
                worker.start()
                self._workers.append(worker)

    def _worker_loop(self):
        while True:
            func, args = self._queue.get()
            try:
                func(*args)
            except Exception:
                logger.error("Unexpected error in DeepQuery report worker", exc_info=True)
                self._discard_events(func, args)
            finally:
                self._queue.task_done()

    def _discard_events(self, func, args):
        """Drop the cancel events of a job that died with an unexpected error, so they do not leak."""
        try:
            with self._lock:
                if func == self._run_analysis:
                    self._analysis_events.pop(args[1], None)
                    for report_id in args[3]:
                        self._report_events.pop(report_id, None)
                elif func == self._run_report:
                    self._report_events.pop(args[1], None)
        except Exception:
            logger.error("Could not clean up DeepQuery job events", exc_info=True)

    def _enqueue(self, func, *args):
        """Queue a job. Raises ReportQueueFullError (without blocking) if the queue is full."""
        self._ensure_workers()
        try:
            self._queue.put_nowait((func, args))
        except queue.Full:
            raise ReportQueueFullError(
                "The report queue is full. Please try again in a few minutes."
            ) from None

    def _abort_job(self, report_ids, analysis_id=None, message="The report queue is full."):
        """Fail reports that could not be queued and release their events."""
        with self._lock:
            if analysis_id:
                self._analysis_events.pop(analysis_id, None)
            for report_id in report_ids:
                self._report_events.pop(report_id, None)
        self._fail_reports(report_ids, message)
        if analysis_id:
            DeepQueryReports.update_analysis_status(analysis_id, "FAILED", _truncate_error(message))

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def submit(self, ctx, analysis_request, languages):
        """Create an analysis with one PENDING report per language and queue it.

        Returns (analysis_id, [{"report_id", "language"}, ...]). Never blocks on the AI SDK.
        """
        languages = normalize_languages(languages)
        check_report_limit(ctx.user_id, len(languages))
        analysis_id = str(uuid.uuid4())

        DeepQueryReports.create_analysis(analysis_id, ctx.user_id, ctx.agent_id, ctx.thread_id, analysis_request)
        reports = []
        for language in languages:
            report_id = str(uuid.uuid4())
            DeepQueryReports.create_report(report_id, analysis_id, ctx.user_id, ctx.agent_id, language)
            reports.append({"report_id": report_id, "language": language})
        with self._lock:
            self._analysis_events[analysis_id] = threading.Event()
            for report in reports:
                self._report_events[report["report_id"]] = threading.Event()

        report_ids = [r["report_id"] for r in reports]
        try:
            self._enqueue(self._run_analysis, ctx, analysis_id, analysis_request, report_ids)
        except ReportQueueFullError as e:
            self._abort_job(report_ids, analysis_id, str(e))
            raise
        logger.info(f"Queued DeepQuery analysis {analysis_id} for user '{ctx.user_id}' ({len(reports)} report(s))")
        return analysis_id, reports

    def variant(self, ctx, report_id, language):
        """Create a new report on the analysis of report_id, reusing its stored metadata.

        Only the HTML generation phase runs. Raises ReportNotFoundError if the
        report is not the user's, VariantUnavailableError if there is no metadata.
        """
        language = normalize_languages([language])[0] if language else DEFAULT_LANGUAGE
        source = DeepQueryReports.get_report(report_id, ctx.user_id)
        if not source:
            raise ReportNotFoundError(report_id)

        analysis = DeepQueryReports.get_analysis(source["analysis_id"], ctx.user_id)
        if not analysis or not analysis.get("metadata"):
            raise VariantUnavailableError(
                "This analysis has no stored data to generate a new variant from (it failed or was cancelled)."
            )

        check_report_limit(ctx.user_id)
        new_report_id = str(uuid.uuid4())
        DeepQueryReports.create_report(new_report_id, source["analysis_id"], ctx.user_id, source["agent_id"], language)
        with self._lock:
            self._report_events[new_report_id] = threading.Event()

        try:
            self._enqueue(self._run_report, ctx, new_report_id, language, analysis["metadata"])
        except ReportQueueFullError as e:
            self._abort_job([new_report_id], message=str(e))
            raise
        return DeepQueryReports.get_report(new_report_id, ctx.user_id)

    def retry(self, ctx, report_id):
        """Re-queue a FAILED / CANCELLED report in place.

        With stored metadata only the HTML phase runs; otherwise the whole
        analysis runs again from the stored question. Returns the updated report.
        Raises ReportNotFoundError, or ValueError if the report is not retryable.
        """
        report = DeepQueryReports.get_report(report_id, ctx.user_id)
        if not report:
            raise ReportNotFoundError(report_id)
        if report["status"] not in ("FAILED", "CANCELLED"):
            raise ValueError("Only failed or cancelled reports can be retried.")

        analysis = DeepQueryReports.get_analysis(report["analysis_id"], ctx.user_id)
        if not analysis:
            raise VariantUnavailableError("The analysis behind this report no longer exists.")
        metadata = analysis.get("metadata")
        question = analysis.get("question")
        if not metadata and not question:
            raise VariantUnavailableError("There is not enough stored information to retry this report.")

        if not DeepQueryReports.reset_report(report_id, ctx.user_id):
            raise ValueError("Only failed or cancelled reports can be retried.")

        analysis_id = None if metadata else report["analysis_id"]
        with self._lock:
            self._report_events[report_id] = threading.Event()
            if analysis_id:
                self._analysis_events[analysis_id] = threading.Event()

        try:
            if metadata:
                self._enqueue(self._run_report, ctx, report_id, report["language"], metadata)
            else:
                DeepQueryReports.update_analysis_status(report["analysis_id"], "PENDING")
                self._enqueue(self._run_analysis, ctx, report["analysis_id"], question, [report_id])
        except ReportQueueFullError as e:
            self._abort_job([report_id], analysis_id, str(e))
            raise
        return DeepQueryReports.get_report(report_id, ctx.user_id)

    def submit_from_legacy(self, ctx, question, metadata, language):
        """Create a report from deepquery_metadata of an old (synchronous) chat tool call.

        Stores the metadata as a new analysis and runs only the HTML phase.
        Returns the new report.
        """
        language = normalize_languages([language])[0] if language else DEFAULT_LANGUAGE
        check_report_limit(ctx.user_id)
        analysis_id = str(uuid.uuid4())
        report_id = str(uuid.uuid4())
        title = metadata.get("analysis_title") if isinstance(metadata, dict) else None

        DeepQueryReports.create_analysis(analysis_id, ctx.user_id, ctx.agent_id, ctx.thread_id, question or "")
        DeepQueryReports.set_analysis_metadata(analysis_id, metadata, title)
        DeepQueryReports.create_report(report_id, analysis_id, ctx.user_id, ctx.agent_id, language, title)
        with self._lock:
            self._report_events[report_id] = threading.Event()

        try:
            self._enqueue(self._run_report, ctx, report_id, language, metadata)
        except ReportQueueFullError as e:
            self._abort_job([report_id], message=str(e))
            raise
        return DeepQueryReports.get_report(report_id, ctx.user_id)

    def cancel(self, report_id, user_id):
        """Cancel a PENDING/PROCESSING report. Returns True if it was cancelled."""
        report = DeepQueryReports.get_report(report_id, user_id)
        if not report:
            raise ReportNotFoundError(report_id)
        if report["status"] not in ACTIVE_STATUSES:
            return False

        changed = DeepQueryReports.update_status(
            report_id, "CANCELLED", stage="done", only_if_status=ACTIVE_STATUSES
        )
        with self._lock:
            event = self._report_events.get(report_id)
            if event:
                event.set()

            # Abort the shared data extraction only when nobody is waiting for it anymore.
            analysis_event = self._analysis_events.get(report["analysis_id"])
            if analysis_event and not analysis_event.is_set():
                siblings = DeepQueryReports.get_analysis_report_statuses(report["analysis_id"])
                if not any(status in ACTIVE_STATUSES for _, status in siblings):
                    analysis_event.set()
        return bool(changed)

    def delete(self, report_id, user_id):
        """Delete a report, cancelling it first if it is still running."""
        try:
            self.cancel(report_id, user_id)
        except ReportNotFoundError:
            return False
        deleted = DeepQueryReports.delete_report(report_id, user_id)
        with self._lock:
            self._report_events.pop(report_id, None)
        return deleted

    def delete_all(self, user_id, agent_id=None):
        """Cancel the user's running reports and delete every report. Returns the deleted count."""
        for report in DeepQueryReports.list_reports(user_id, agent_id):
            if report["status"] in ACTIVE_STATUSES:
                try:
                    self.cancel(report["report_id"], user_id)
                except ReportNotFoundError:
                    pass
        return DeepQueryReports.delete_all(user_id, agent_id)

    # ------------------------------------------------------------------
    # Phase 1: analysis (data extraction)
    # ------------------------------------------------------------------

    def _fail_reports(self, report_ids, message):
        message = _truncate_error(message)
        for report_id in report_ids:
            DeepQueryReports.update_status(
                report_id, "FAILED", stage="done", error=message, only_if_status=ACTIVE_STATUSES
            )

    def _cancel_reports(self, report_ids):
        for report_id in report_ids:
            DeepQueryReports.update_status(
                report_id, "CANCELLED", stage="done", only_if_status=ACTIVE_STATUSES
            )

    def _run_analysis(self, ctx, analysis_id, analysis_request, report_ids):
        with self._lock:
            analysis_event = self._analysis_events.get(analysis_id)

        handed_off = set()
        try:
            running = [
                report_id for report_id in report_ids
                if DeepQueryReports.update_status(
                    report_id, "PROCESSING", stage="extracting_data", only_if_status=ACTIVE_STATUSES
                )
            ]
            if not running:
                DeepQueryReports.update_analysis_status(analysis_id, "CANCELLED")
                return

            DeepQueryReports.update_analysis_status(analysis_id, "PROCESSING")
            response = denodo_tools.deep_query(
                analysis_request=analysis_request,
                api_host=ctx.api_host,
                auth=ctx.auth,
                verify_ssl=ctx.verify_ssl,
                timeout=ctx.timeout,
                cancel_event=analysis_event,
                **ctx.ai_sdk_params,
            )

            metadata = response.get("deepquery_metadata") if isinstance(response, dict) else None
            if not metadata:
                message = _error_detail(response) or "DeepQuery analysis did not return any data."
                DeepQueryReports.update_analysis_status(analysis_id, "FAILED", _truncate_error(message))
                self._fail_reports(running, message)
                return

            title = metadata.get("analysis_title") if isinstance(metadata, dict) else None
            DeepQueryReports.set_analysis_metadata(analysis_id, metadata, title)

            for report_id in running:
                queued = DeepQueryReports.update_status(
                    report_id, "PROCESSING", stage="generating_html", title=title, only_if_status=ACTIVE_STATUSES
                )
                report = DeepQueryReports.get_report(report_id, ctx.user_id) if queued else None
                if report:
                    try:
                        self._enqueue(self._run_report, ctx, report_id, report["language"], metadata)
                        handed_off.add(report_id)
                    except ReportQueueFullError as e:
                        self._fail_reports([report_id], str(e))
        except AISDKRequestCancelled:
            logger.info(f"DeepQuery analysis {analysis_id} cancelled by the user")
            DeepQueryReports.update_analysis_status(analysis_id, "CANCELLED")
            self._cancel_reports(report_ids)
        except Exception as e:
            logger.error(f"DeepQuery analysis {analysis_id} failed", exc_info=True)
            DeepQueryReports.update_analysis_status(analysis_id, "FAILED", _truncate_error(e))
            self._fail_reports(report_ids, e)
        finally:
            with self._lock:
                self._analysis_events.pop(analysis_id, None)
                # Reports that never reach the HTML phase must not leak their cancel events
                for report_id in report_ids:
                    if report_id not in handed_off:
                        self._report_events.pop(report_id, None)

    # ------------------------------------------------------------------
    # Phase 2: HTML report generation
    # ------------------------------------------------------------------

    def _run_report(self, ctx, report_id, language, metadata):
        with self._lock:
            report_event = self._report_events.get(report_id)

        try:
            started = DeepQueryReports.update_status(
                report_id, "PROCESSING", stage="generating_html", only_if_status=ACTIVE_STATUSES
            )
            if not started:
                return  # Cancelled or deleted while waiting in the queue

            llm_params = {
                key: ctx.ai_sdk_params[key]
                for key in LLM_OVERRIDE_KEYS
                if ctx.ai_sdk_params.get(key) is not None
            }
            response = denodo_tools.generate_deepquery_report(
                deepquery_metadata=metadata,
                api_host=ctx.api_host,
                auth=ctx.auth,
                color_palette=DEFAULT_COLOR_PALETTE,
                language=language,
                verify_ssl=ctx.verify_ssl,
                timeout=ctx.timeout,
                cancel_event=report_event,
                **llm_params,
            )

            html = response.get("html_report") if isinstance(response, dict) else None
            if not html:
                self._fail_reports([report_id], _error_detail(response) or "Report generation returned no content.")
                return

            DeepQueryReports.set_report_html(report_id, html, response.get("translated_title"))
        except AISDKRequestCancelled:
            logger.info(f"DeepQuery report {report_id} cancelled by the user")
            self._cancel_reports([report_id])
        except Exception as e:
            logger.error(f"DeepQuery report {report_id} failed", exc_info=True)
            self._fail_reports([report_id], e)
        finally:
            with self._lock:
                self._report_events.pop(report_id, None)

