import argparse
import os
import sys
import psutil

from rich.console import Console
from rich.prompt import Confirm

PROCESS_IDENTIFIERS = {
    'api': 'api.main',
    'sample_chatbot': 'sample_chatbot.main',
}

console = Console()

def _process_cwd(process):
    try:
        return process.cwd()
    except (psutil.Error, OSError):
        return "unknown"

def find_matching_processes(identifier):
    matches = []
    current_pid = os.getpid()
    for process in psutil.process_iter(['pid', 'name', 'cmdline']):
        if process.info['pid'] == current_pid:
            continue
        cmdline = process.info['cmdline']
        if cmdline and any(identifier in cmd_part for cmd_part in cmdline):
            matches.append(process)
    return matches

def terminate_process(process, service_name):
    try:
        console.print(f"[bold green]Terminating {service_name} (PID: {process.pid})...")
        process.terminate()
        process.wait(timeout=5)
        console.print(f"[bold green]{service_name} (PID: {process.pid}) stopped successfully.")
    except psutil.TimeoutExpired:
        console.print(f"[bold yellow]! {service_name} (PID: {process.pid}) did not terminate gracefully. Forcing kill...")
        process.kill()
        console.print(f"[bold green]{service_name} (PID: {process.pid}) killed.")
    except psutil.NoSuchProcess:
        console.print(f"[bold green]{service_name} (PID: {process.pid}) was already stopped during shutdown.")

def find_and_terminate_process(identifier: str, service_name: str):
    """Finds and terminates processes by an identifier in their command line."""
    try:
        matches = find_matching_processes(identifier)
    except Exception as e:
        console.print(f"[bold red]Error while searching for processes: {e}")
        return

    if not matches:
        console.print(f"[bold yellow]{service_name} service not found. It might be already stopped.\n")
        return

    console.print(f"[bold green]Found {len(matches)} {service_name} process(es):")
    for process in matches:
        cwd = _process_cwd(process)
        console.print(f"  PID {process.pid}  cwd={cwd}")
    console.print()

    if len(matches) > 1:
        if sys.stdin.isatty():
            if not Confirm.ask(f"[bold yellow]Stop all {len(matches)} {service_name} processes?[/]"):
                console.print(f"[bold red]Skipped stopping {service_name}.\n")
                return
        else:
            console.print(f"[bold yellow]Multiple {service_name} processes found; stopping all (non-interactive).")

    for process in matches:
        terminate_process(process, service_name)
    console.print()

def main():
    parser = argparse.ArgumentParser(
        description="Stops the AI SDK API, the sample chatbot, or both.",
        formatter_class=argparse.RawTextHelpFormatter
    )
    parser.add_argument(
        "service",
        choices=["api", "sample_chatbot", "both"],
        help="The service to stop:\n"
             "  api            - Stops only the AI SDK API.\n"
             "  sample_chatbot - Stops only the sample chatbot.\n"
             "  both           - Stops both services."
    )
    args = parser.parse_args()

    if args.service == 'both':
        print("Attempting to stop both services...")
        find_and_terminate_process(PROCESS_IDENTIFIERS['api'], 'API')
        find_and_terminate_process(PROCESS_IDENTIFIERS['sample_chatbot'], 'sample chatbot')
    elif args.service == 'api':
        find_and_terminate_process(PROCESS_IDENTIFIERS['api'], 'API')
    elif args.service == 'sample_chatbot':
        find_and_terminate_process(PROCESS_IDENTIFIERS['sample_chatbot'], 'sample chatbot')

    console.print("[bold cyan]Stop script finished.")

if __name__ == "__main__":
    main()

import os
import json
import sqlite3
import logging
import threading
from datetime import datetime, timezone

from utils.utils import get_chatbot_data_dir

_pg_pool = None
_oracle_pool = None
_local = threading.local()

def get_sqlite_path():
    """
    Returns the path to the SQLite database, ensuring the directory exists.
    """
    db_dir = os.path.join(get_chatbot_data_dir(), "conversations_history")
    os.makedirs(db_dir, exist_ok=True)
    return os.path.join(db_dir, "history.db")

def get_sqlite_conn():
    """
    Returns a thread-local SQLite connection enabling WAL mode and busy timeout
    to allow concurrent reads and writes across threads without transaction collisions.
    """
    conn = getattr(_local, "sqlite_conn", None)
    if conn is None:
        sqlite_path = get_sqlite_path()
        conn = sqlite3.connect(sqlite_path, timeout=30.0, check_same_thread=False)
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute("PRAGMA busy_timeout=30000;")
        conn.execute("PRAGMA synchronous=NORMAL;")
        _local.sqlite_conn = conn
    return conn

def _get_normalized_pg_uri():
    """
    Fetches the PostgreSQL connection string and normalizes it for psycopg3.
    """
    uri = os.getenv("POSTGRESQL_DATABASE_CONNECTION_STRING")
    if not uri:
        raise ValueError("POSTGRESQL_DATABASE_CONNECTION_STRING is not set.")

    if uri.startswith("postgresql+psycopg2://") or uri.startswith("postgresql+psycopg://"):
        uri = uri.replace("postgresql+psycopg2://", "postgresql://").replace("postgresql+psycopg://", "postgresql://")
    return uri

def get_pg_pool():
    global _pg_pool
    if _pg_pool is None:
        from psycopg_pool import ConnectionPool

        uri = _get_normalized_pg_uri()

        try:
            from psycopg.conninfo import make_conninfo
            make_conninfo(uri)
        except Exception as e:
            raise ValueError(f"Invalid PostgreSQL connection string syntax: {e}") from e

        _pg_pool = ConnectionPool(conninfo=uri)
    return _pg_pool

def get_oracle_pool():
    global _oracle_pool
    if _oracle_pool is None:
        import oracledb

        dsn = os.getenv("ORACLE_DATABASE_DSN")
        user = os.getenv("ORACLE_DATABASE_USERNAME")
        password = os.getenv("ORACLE_DATABASE_PASSWORD")
        if not all([dsn, user, password]):
            raise ValueError(
                "Oracle connection parameters (ORACLE_DATABASE_DSN, ORACLE_DATABASE_USERNAME, ORACLE_DATABASE_PASSWORD) are not fully set."
            )

        # Return CLOB/NCLOB as str (and BLOB as bytes) so callers can treat
        # Oracle text columns like SQLite/Postgres TEXT without LOB handling.
        oracledb.defaults.fetch_lobs = False
        _oracle_pool = oracledb.create_pool(user=user, password=password, dsn=dsn, min=2, max=10, increment=1, ping_interval=0)
    return _oracle_pool

class UniformCheckpointer:
    @staticmethod
    def get_saver():
        provider = os.getenv("CHATBOT_DATABASE_PROVIDER", "SQLite").upper()

        if provider == "SQLITE":
            from langgraph.checkpoint.sqlite import SqliteSaver

            conn = get_sqlite_conn()
            saver = SqliteSaver(conn)
            saver.setup()
            return saver

        elif provider == "POSTGRESQL":
            from langgraph.checkpoint.postgres import PostgresSaver
            import psycopg

            uri = _get_normalized_pg_uri()

            try:
                with psycopg.connect(uri, autocommit=True) as conn:
                    PostgresSaver(conn).setup()
            except Exception as e:
                logging.warning(f"Warning initializing tables in PostgresSaver: {e}")

            pool = get_pg_pool()
            return PostgresSaver(pool)

        elif provider == "ORACLE":
            from langgraph_oracledb.checkpoint.oracle import OracleSaver

            pool = get_oracle_pool()
            saver = OracleSaver(pool)
            try:
                saver.setup()
            except Exception as e:
                logging.warning(f"Warning initializing tables in OracleSaver: {e}")

            return saver
        else:
            raise ValueError(f"Chat history provider not supported: {provider}")

class UserSkills:
    """
    Storage for personal skills and per-user skill activation preferences.

    Personal skills are created/uploaded by a user and only visible to that
    user; they live in the same database as the conversation history.
    System skills (the on-disk skills/ folder) are visible to everyone.
    Activation is per (user, agent, skill) via user_skill_prefs — the same
    skill can be active in one agent's settings and inactive in another's.
    """

    @staticmethod
    def _get_connection():
        return HistoryMetadata._get_connection()

    @staticmethod
    def _execute(sql, params=(), fetch=None):
        """
        Run a statement written with placeholders, adapting
        the params to the active provider. fetch: None | 'one' | 'all'.
        Returns fetched rows (or rowcount for writes).
        """
        conn_obj, provider = UserSkills._get_connection()
        if not conn_obj:
            return None

        if provider == "SQLITE":
            cursor = conn_obj.execute(sql, params)
            if fetch == "one":
                result = cursor.fetchone()
            elif fetch == "all":
                result = cursor.fetchall()
            else:
                result = cursor.rowcount
            conn_obj.commit()
            return result

        elif provider == "POSTGRESQL":
            pg_sql = sql.replace("?", "%s")
            with conn_obj as conn:
                with conn.cursor() as cur:
                    cur.execute(pg_sql, params)
                    if fetch == "one":
                        result = cur.fetchone()
                    elif fetch == "all":
                        result = cur.fetchall()
                    else:
                        result = cur.rowcount
                conn.commit()
                return result

        elif provider == "ORACLE":
            oracle_sql = sql
            index = 1
            while "?" in oracle_sql:
                oracle_sql = oracle_sql.replace("?", f":{index}", 1)
                index += 1
            with conn_obj as conn:
                with conn.cursor() as cur:
                    cur.execute(oracle_sql, list(params))
                    if fetch == "one":
                        result = cur.fetchone()
                    elif fetch == "all":
                        result = cur.fetchall()
                    else:
                        result = cur.rowcount
                conn.commit()
                return result

        return None

    @staticmethod
    def init_db():
        conn_obj, provider = UserSkills._get_connection()
        if not conn_obj:
            return

        if provider == "SQLITE":
            conn_obj.execute("""
                CREATE TABLE IF NOT EXISTS user_skills (
                    user_id TEXT,
                    skill_name TEXT,
                    content TEXT,
                    active INTEGER DEFAULT 1,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY (user_id, skill_name)
                )
            """)
            conn_obj.execute("""
                CREATE TABLE IF NOT EXISTS user_skill_prefs (
                    user_id TEXT,
                    agent_id TEXT,
                    skill_name TEXT,
                    active INTEGER DEFAULT 1,
                    PRIMARY KEY (user_id, agent_id, skill_name)
                )
            """)
            conn_obj.commit()

        elif provider == "POSTGRESQL":
            with conn_obj as conn:
                with conn.cursor() as cur:
                    cur.execute("""
                        CREATE TABLE IF NOT EXISTS user_skills (
                            user_id TEXT,
                            skill_name TEXT,
                            content TEXT,
                            active INTEGER DEFAULT 1,
                            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            PRIMARY KEY (user_id, skill_name)
                        )
                    """)
                    cur.execute("""
                        CREATE TABLE IF NOT EXISTS user_skill_prefs (
                            user_id TEXT,
                            agent_id TEXT,
                            skill_name TEXT,
                            active INTEGER DEFAULT 1,
                            PRIMARY KEY (user_id, agent_id, skill_name)
                        )
                    """)
                conn.commit()

        elif provider == "ORACLE":
            with conn_obj as conn:
                with conn.cursor() as cur:
                    for ddl in (
                        """
                        CREATE TABLE user_skills (
                            user_id VARCHAR2(255),
                            skill_name VARCHAR2(255),
                            content CLOB,
                            active NUMBER(1) DEFAULT 1,
                            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            PRIMARY KEY (user_id, skill_name)
                        )
                        """,
                        """
                        CREATE TABLE user_skill_prefs (
                            user_id VARCHAR2(255),
                            agent_id VARCHAR2(255),
                            skill_name VARCHAR2(255),
                            active NUMBER(1) DEFAULT 1,
                            PRIMARY KEY (user_id, agent_id, skill_name)
                        )
                        """,
                    ):
                        try:
                            cur.execute(ddl)
                        except Exception as e:
                            if "ORA-00955" not in str(e):
                                raise
                conn.commit()

    # -- Personal skills ------------------------------------------------

    @staticmethod
    def list_personal(user_id):
        rows = UserSkills._execute(
            """
            SELECT skill_name, content, active, created_at, updated_at
            FROM user_skills WHERE user_id = ? ORDER BY skill_name
            """,
            (user_id,),
            fetch="all",
        ) or []
        return [
            {
                "skill_name": row[0],
                "content": row[1],
                "active": bool(row[2]),
                "created_at": row[3],
                "updated_at": row[4],
            }
            for row in rows
        ]

    @staticmethod
    def get_personal(user_id, skill_name):
        row = UserSkills._execute(
            "SELECT content, active FROM user_skills WHERE user_id = ? AND skill_name = ?",
            (user_id, skill_name),
            fetch="one",
        )
        if not row:
            return None
        return {"content": row[0], "active": bool(row[1])}

    @staticmethod
    def create_personal(user_id, skill_name, content):
        """Create a personal skill. Returns False if it already exists."""
        if UserSkills.get_personal(user_id, skill_name) is not None:
            return False
        UserSkills._execute(
            "INSERT INTO user_skills (user_id, skill_name, content, active) VALUES (?, ?, ?, 1)",
            (user_id, skill_name, content),
        )
        return True

    @staticmethod
    def update_personal(user_id, skill_name, content):
        """Update a personal skill's content. Returns False if it does not exist."""
        count = UserSkills._execute(
            """
            UPDATE user_skills SET content = ?, updated_at = CURRENT_TIMESTAMP
            WHERE user_id = ? AND skill_name = ?
            """,
            (content, user_id, skill_name),
        )
        return bool(count)

    @staticmethod
    def delete_personal(user_id, skill_name):
        count = UserSkills._execute(
            "DELETE FROM user_skills WHERE user_id = ? AND skill_name = ?",
            (user_id, skill_name),
        )
        if count:
            UserSkills._execute(
                "DELETE FROM user_skill_prefs WHERE user_id = ? AND skill_name = ?",
                (user_id, skill_name),
            )
        return bool(count)

    # -- Skill activation preferences (per user, per agent) --------------

    @staticmethod
    def get_prefs(user_id, agent_id):
        """Return {skill_name: active} the user has toggled for this agent.

        Skills without a row default to active. Covers both system and
        personal skills.
        """
        rows = UserSkills._execute(
            "SELECT skill_name, active FROM user_skill_prefs WHERE user_id = ? AND agent_id = ?",
            (user_id, agent_id),
            fetch="all",
        ) or []
        return {row[0]: bool(row[1]) for row in rows}

    @staticmethod
    def set_active(user_id, agent_id, skill_name, active):
        value = 1 if active else 0
        count = UserSkills._execute(
            "UPDATE user_skill_prefs SET active = ? WHERE user_id = ? AND agent_id = ? AND skill_name = ?",
            (value, user_id, agent_id, skill_name),
        )
        if not count:
            UserSkills._execute(
                "INSERT INTO user_skill_prefs (user_id, agent_id, skill_name, active) VALUES (?, ?, ?, ?)",
                (user_id, agent_id, skill_name, value),
            )

    @staticmethod
    def clear_agent_prefs(user_id, agent_id):
        """Drop this user's skill toggles for one agent.

        A skill with no row is active, which is the default. Agent-managed
        skills ignore these rows, so clearing them does not change those.
        """
        UserSkills._execute(
            "DELETE FROM user_skill_prefs WHERE user_id = ? AND agent_id = ?",
            (user_id, agent_id),
        )

class UserUiPreferences:
    """
    UI settings that used to live only in the browser.

    One row per user for the profile (scope "user"): what agents should
    know about them, the input method, and the number format.
    One row per user per agent (scope "agent:" plus the agent id) for that
    agent's instructions and LLM / AI SDK options.
    """

    PROFILE_SCOPE = "user"
    _ready = False
    _init_lock = threading.Lock()

    @staticmethod
    def ensure():
        """Create the table once. Later calls skip the lock."""
        if UserUiPreferences._ready:
            return
        with UserUiPreferences._init_lock:
            if UserUiPreferences._ready:
                return
            UserUiPreferences.init_db()
            UserUiPreferences._ready = True

    @staticmethod
    def init_db():
        conn_obj, provider = UserSkills._get_connection()
        if not conn_obj:
            return

        if provider == "SQLITE":
            conn_obj.execute("""
                CREATE TABLE IF NOT EXISTS user_ui_prefs (
                    user_id TEXT,
                    scope TEXT,
                    prefs_json TEXT,
                    PRIMARY KEY (user_id, scope)
                )
            """)
            conn_obj.commit()
        elif provider == "POSTGRESQL":
            with conn_obj as conn:
                with conn.cursor() as cur:
                    cur.execute("""
                        CREATE TABLE IF NOT EXISTS user_ui_prefs (
                            user_id TEXT,
                            scope TEXT,
                            prefs_json TEXT,
                            PRIMARY KEY (user_id, scope)
                        )
                    """)
                conn.commit()
        elif provider == "ORACLE":
            with conn_obj as conn:
                with conn.cursor() as cur:
                    try:
                        cur.execute("""
                            CREATE TABLE user_ui_prefs (
                                user_id VARCHAR2(255),
                                scope VARCHAR2(255),
                                prefs_json CLOB,
                                PRIMARY KEY (user_id, scope)
                            )
                        """)
                    except Exception as e:
                        if "ORA-00955" not in str(e):
                            raise
                conn.commit()

    @staticmethod
    def get(user_id, scope):
        UserUiPreferences.ensure()
        row = UserSkills._execute(
            "SELECT prefs_json FROM user_ui_prefs WHERE user_id = ? AND scope = ?",
            (user_id, scope),
            fetch="one",
        )
        if not row or row[0] in (None, ""):
            return {}
        raw = row[0]
        if not isinstance(raw, str):
            raw = str(raw)
        try:
            parsed = json.loads(raw)
        except (TypeError, ValueError):
            logging.error(f"Invalid stored prefs_json for user {user_id} scope {scope}")
            return {}
        return parsed if isinstance(parsed, dict) else {}

    @staticmethod
    def merge(user_id, scope, patch):
        """Replace the named keys on this row and leave the others in place."""
        UserUiPreferences.ensure()
        current = UserUiPreferences.get(user_id, scope)
        for key, value in patch.items():
            if value is None:
                current.pop(key, None)
            else:
                current[key] = value
        payload = json.dumps(current)
        exists = UserSkills._execute(
            "SELECT 1 FROM user_ui_prefs WHERE user_id = ? AND scope = ?",
            (user_id, scope),
            fetch="one",
        )
        if exists:
            UserSkills._execute(
                "UPDATE user_ui_prefs SET prefs_json = ? WHERE user_id = ? AND scope = ?",
                (payload, user_id, scope),
            )
        else:
            UserSkills._execute(
                "INSERT INTO user_ui_prefs (user_id, scope, prefs_json) VALUES (?, ?, ?)",
                (user_id, scope, payload),
            )
        return current


def _is_unique_violation(exc):
    """True when an insert collided with a row that already exists."""
    name = type(exc).__name__
    if name in ("IntegrityError", "UniqueViolation"):
        return True
    text = str(exc)
    return "ORA-00001" in text or "UNIQUE constraint failed" in text or "duplicate key" in text.lower()

class UserMemories:
    """
    Durable chatbot memories in the same database as conversation history.

    One row in ``memories`` is one fact. A name is unique for one user,
    across types and agents. ``user`` and ``user-metadata`` are scoped to
    one user on one agent (``agent_id``; the general chat is ``global``).
    ``metadata`` is one fact per user and name, readable and writable from
    every agent of that user. The row keeps the agent that first saved it.
    ``position`` keeps the order of the user-memory index. Each linked
    fact can point at several views, databases, or tags. Those pointers
    are rows in ``memory_links``.
    """

    _SELECT = """
        SELECT user_id, agent_id, memory_type, name, description, body,
               owner, modified, position
        FROM memories
    """

    _LINK_SELECT = """
        SELECT user_id, agent_id, memory_type, name, link_kind, link_name
        FROM memory_links
    """

    @staticmethod
    def _execute(sql, params=(), fetch=None):
        return UserSkills._execute(sql, params, fetch)

    @staticmethod
    def _apply(work):
        """Run ``work(execute)`` in one transaction. ``execute`` matches ``_execute``."""
        conn_obj, provider = UserSkills._get_connection()
        if not conn_obj:
            return None

        if provider == "SQLITE":
            def execute(sql, params=(), fetch=None):
                cursor = conn_obj.execute(sql, params)
                if fetch == "one":
                    return cursor.fetchone()
                if fetch == "all":
                    return cursor.fetchall()
                return cursor.rowcount

            try:
                result = work(execute)
                conn_obj.commit()
                return result
            except Exception:
                conn_obj.rollback()
                raise

        if provider == "POSTGRESQL":
            with conn_obj as conn:
                try:
                    with conn.cursor() as cur:
                        def execute(sql, params=(), fetch=None):
                            cur.execute(sql.replace("?", "%s"), params)
                            if fetch == "one":
                                return cur.fetchone()
                            if fetch == "all":
                                return cur.fetchall()
                            return cur.rowcount

                        result = work(execute)
                    conn.commit()
                    return result
                except Exception:
                    conn.rollback()
                    raise

        if provider == "ORACLE":
            def adapt(sql):
                oracle_sql = sql
                index = 1
                while "?" in oracle_sql:
                    oracle_sql = oracle_sql.replace("?", f":{index}", 1)
                    index += 1
                return oracle_sql

            with conn_obj as conn:
                try:
                    with conn.cursor() as cur:
                        def execute(sql, params=(), fetch=None):
                            cur.execute(adapt(sql), list(params))
                            if fetch == "one":
                                return cur.fetchone()
                            if fetch == "all":
                                return cur.fetchall()
                            return cur.rowcount

                        result = work(execute)
                    conn.commit()
                    return result
                except Exception:
                    conn.rollback()
                    raise

        return None

    @staticmethod
    def _as_records(rows, links_by_key):
        records = []
        for row in rows or []:
            key = (row[0], row[1], row[2], row[3])
            records.append({
                "user_id": row[0],
                "agent_id": row[1],
                "memory_type": row[2],
                "name": row[3],
                "description": row[4],
                "body": row[5] or "",
                "owner": row[6],
                "modified": "" if row[7] is None else str(row[7]),
                "position": int(row[8] or 0),
                "links": links_by_key.get(key, []),
            })
        return records

    @staticmethod
    def _group_links(rows):
        grouped = {}
        seen = {}
        for row in rows or []:
            if not row[4] or not row[5]:
                continue
            key = (row[0], row[1], row[2], row[3])
            marker = (row[4], str(row[5]).casefold())
            bag = seen.setdefault(key, set())
            if marker in bag:
                continue
            bag.add(marker)
            grouped.setdefault(key, []).append({"kind": row[4], "name": row[5]})
        return grouped

    @staticmethod
    def _attach(rows, link_rows):
        return UserMemories._as_records(rows, UserMemories._group_links(link_rows))

    @staticmethod
    def _replace_links(execute, user_id, agent_id, memory_type, name, links):
        execute(
            "DELETE FROM memory_links WHERE user_id = ? AND agent_id = ? AND memory_type = ? AND name = ?",
            (user_id, agent_id, memory_type, name),
        )
        for position, link in enumerate(links or [], start=1):
            execute(
                """
                INSERT INTO memory_links (
                    user_id, agent_id, memory_type, name, link_kind, link_name, position
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (user_id, agent_id, memory_type, name, link["kind"], link["name"], position),
            )

    @staticmethod
    def init_db():
        conn_obj, provider = UserSkills._get_connection()
        if not conn_obj:
            return

        if provider == "SQLITE":
            UserMemories._init_sqlite(conn_obj)
        elif provider == "POSTGRESQL":
            UserMemories._init_postgresql(conn_obj)
        elif provider == "ORACLE":
            UserMemories._init_oracle(conn_obj)

    @staticmethod
    def _create_unique_name_index(execute, sql=None, savepoint=None):
        """One memory name per user. Existing duplicate names are left in place.

        A failed index must not abort the rest of init. PostgreSQL aborts the
        transaction on that failure, so the index runs inside a savepoint there.
        """
        statement = sql or """
            CREATE UNIQUE INDEX IF NOT EXISTS idx_memories_user_name
            ON memories (user_id, name)
        """
        if savepoint:
            execute(f"SAVEPOINT {savepoint}")
        try:
            execute(statement)
        except Exception as exc:
            if savepoint:
                execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
            text = str(exc)
            if "ORA-00955" in text or "ORA-01408" in text:
                return
            if (
                "UNIQUE constraint failed" in text
                or "duplicate key" in text.lower()
                or "ORA-01452" in text
            ):
                logging.warning(
                    "Could not add the unique memory-name index because some names are already reused. "
                    "A write that reuses a name is still refused."
                )
                return
            raise
        if savepoint:
            execute(f"RELEASE SAVEPOINT {savepoint}")

    @staticmethod
    def _init_sqlite(conn_obj):
        conn_obj.execute("""
            CREATE TABLE IF NOT EXISTS memories (
                user_id TEXT NOT NULL,
                agent_id TEXT NOT NULL DEFAULT 'global',
                memory_type TEXT NOT NULL,
                name TEXT NOT NULL,
                description TEXT NOT NULL,
                body TEXT NOT NULL,
                owner TEXT NOT NULL,
                modified TEXT NOT NULL,
                position INTEGER NOT NULL,
                PRIMARY KEY (user_id, agent_id, memory_type, name)
            )
        """)
        UserMemories._create_unique_name_index(conn_obj.execute)
        conn_obj.execute("""
            CREATE TABLE IF NOT EXISTS memory_links (
                user_id TEXT NOT NULL,
                agent_id TEXT NOT NULL DEFAULT 'global',
                memory_type TEXT NOT NULL,
                name TEXT NOT NULL,
                link_kind TEXT NOT NULL,
                link_name TEXT NOT NULL,
                position INTEGER NOT NULL,
                PRIMARY KEY (user_id, agent_id, memory_type, name, link_kind, link_name)
            )
        """)
        conn_obj.execute("""
            CREATE INDEX IF NOT EXISTS idx_memory_links
            ON memory_links (memory_type, link_kind, link_name)
        """)
        conn_obj.execute("""
            CREATE TABLE IF NOT EXISTS user_memory_prefs (
                user_id TEXT NOT NULL,
                agent_id TEXT NOT NULL,
                active INTEGER NOT NULL,
                PRIMARY KEY (user_id, agent_id)
            )
        """)
        conn_obj.commit()

    @staticmethod
    def _init_postgresql(conn_obj):
        with conn_obj as conn:
            with conn.cursor() as cur:
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS memories (
                        user_id TEXT NOT NULL,
                        agent_id TEXT NOT NULL DEFAULT 'global',
                        memory_type TEXT NOT NULL,
                        name TEXT NOT NULL,
                        description TEXT NOT NULL,
                        body TEXT NOT NULL,
                        owner TEXT NOT NULL,
                        modified TEXT NOT NULL,
                        position INTEGER NOT NULL,
                        PRIMARY KEY (user_id, agent_id, memory_type, name)
                    )
                """)
                UserMemories._create_unique_name_index(cur.execute, savepoint="memories_name_index")
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS memory_links (
                        user_id TEXT NOT NULL,
                        agent_id TEXT NOT NULL DEFAULT 'global',
                        memory_type TEXT NOT NULL,
                        name TEXT NOT NULL,
                        link_kind TEXT NOT NULL,
                        link_name TEXT NOT NULL,
                        position INTEGER NOT NULL,
                        PRIMARY KEY (user_id, agent_id, memory_type, name, link_kind, link_name)
                    )
                """)
                cur.execute("""
                    CREATE INDEX IF NOT EXISTS idx_memory_links
                    ON memory_links (memory_type, link_kind, link_name)
                """)
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS user_memory_prefs (
                        user_id TEXT NOT NULL,
                        agent_id TEXT NOT NULL,
                        active INTEGER NOT NULL,
                        PRIMARY KEY (user_id, agent_id)
                    )
                """)
            conn.commit()

    @staticmethod
    def _oracle_ignoring_exists(cur, ddl):
        try:
            cur.execute(ddl)
        except Exception as e:
            message = str(e)
            if "ORA-00955" not in message and "ORA-01408" not in message:
                raise

import base64
import asyncio
import logging
import httpx
import requests
import traceback

from utils.execution_result_helpers import (
    get_full_execution_result_rows,
)
from utils.schema_catalog import SchemaCatalog, VQL_SCHEMA_GRAMMAR

def create_basic_auth_header(username, password):
    """Create a Basic Authorization header value from username and password."""
    credentials = f"{username}:{password}"
    encoded = base64.b64encode(credentials.encode("utf-8")).decode("utf-8")
    return f"Basic {encoded}"

class AISDKRequestCancelled(Exception):
    """Raised when an in-flight AI SDK request is cancelled by the user."""

async def _cancellable_request(method, endpoint, payload, headers, verify_ssl, timeout, cancel_event):
    """Run the AI SDK request as an asyncio task, polling the cancel event.

    Cancelling the task closes the underlying connection, which lets the AI SDK's
    RequestCancelledMiddleware cancel the request server-side too.
    """
    async with httpx.AsyncClient(verify=verify_ssl, timeout=timeout) as client:
        if method == "GET":
            request_task = asyncio.create_task(client.get(endpoint, params=payload, headers=headers))
        else:
            request_task = asyncio.create_task(client.post(endpoint, json=payload, headers=headers))

        while True:
            done, _ = await asyncio.wait({request_task}, timeout=0.25)
            if done:
                return request_task.result()
            if cancel_event.is_set():
                request_task.cancel()
                raise AISDKRequestCancelled(f"AI SDK request to {endpoint} cancelled by the user.")

def make_ai_sdk_request(endpoint, payload, auth, method="POST", verify_ssl=False, timeout=1200, cancel_event=None):
    """Helper function to make AI SDK requests with standardized error handling.

    Args:
        endpoint: The API endpoint URL
        payload: Request body (POST) or params (GET)
        auth: Authorization header value (e.g., "Basic xyz..." or "Bearer xyz...")
        method: HTTP method (POST or GET)
        verify_ssl: Whether to verify SSL certificates
        timeout: Request timeout in seconds
        cancel_event: Optional threading.Event; when set, the in-flight request is
            aborted (closing the connection) and AISDKRequestCancelled is raised
    """
    headers = {"Authorization": auth}

    try:
        if cancel_event is not None:
            response = asyncio.run(_cancellable_request(method, endpoint, payload, headers, verify_ssl, timeout, cancel_event))
        elif method == "GET":
            response = requests.get(
                endpoint,
                params=payload,
                headers=headers,
                verify=verify_ssl,
                timeout=timeout
            )
        else:
            response = requests.post(
                endpoint,
                json=payload,
                headers=headers,
                verify=verify_ssl,
                timeout=timeout
            )
        response.raise_for_status()
        return response.json()
    except AISDKRequestCancelled:
        raise
    except (requests.HTTPError, httpx.HTTPStatusError) as e:
        logging.error(f"Error making AI SDK request: {e}")
        logging.error(f"Traceback: {traceback.format_exc()}")
        try:
            error_data = e.response.json()
            detail = error_data.get('detail', error_data)
            if isinstance(detail, dict):
                detail = detail.get('error') or detail.get('message') or str(detail)
            return {
                "error": f"An error occurred when connecting to the AI SDK: {detail}",
                "traceback": traceback.format_exc()
            }
        except Exception as e:
            return {
                "error": f"An error occurred when connecting to the AI SDK: {e}",
                "traceback": traceback.format_exc()
            }
    except Exception as e:
        logging.error(f"Error making AI SDK request: {e}")
        logging.error(f"Traceback: {traceback.format_exc()}")
        return {
            "error": f"An error occurred when connecting to the AI SDK: {e}",
            "traceback": traceback.format_exc()
        }

def deep_query(
    analysis_request,
    api_host,
    auth,
    verify_ssl=False,
    vdp_database_names=None,
    vdp_tag_names=None,
    allow_external_associations=False,
    timeout=1200,
    cancel_event=None,
    **llm_params
):
    request_body = {
        'question': analysis_request,
        'allow_external_associations': allow_external_associations
    }

    if vdp_database_names:
        request_body['vdp_database_names'] = vdp_database_names
    if vdp_tag_names:
        request_body['vdp_tag_names'] = vdp_tag_names

    request_body.update(llm_params)

    endpoint = f'{api_host}/deepQuery'
    response = make_ai_sdk_request(endpoint, request_body, auth, verify_ssl=verify_ssl, timeout=timeout, cancel_event=cancel_event)

    return response

